:root {
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #17211a;
  background: #f5f7f3;
  font-synthesis: none;
}

/* INVENTORY_PHYSICAL_COUNT_V1 */
.inventory-count-page { width: min(100%, 1540px); max-width: 1540px; margin: 0 auto; padding: 28px clamp(18px, 3vw, 40px) 52px; }
.inventory-count-page > .module-header, .inventory-count-page > .maintenance-alert { width: 100%; max-width: none; margin-bottom: 16px; }
.inventory-count-layout { display: grid; grid-template-columns: 310px minmax(0, 1fr); align-items: start; gap: 18px; }
.inventory-count-sidebar, .inventory-count-workspace { border: 1px solid #d4e1e6; border-radius: 15px; box-shadow: 0 9px 28px rgba(31,55,70,.055); }
.inventory-count-sidebar { position: sticky; top: 18px; padding: 18px; }
.inventory-count-sidebar form { display: grid; gap: 13px; padding-bottom: 19px; border-bottom: 1px solid #e1e9ed; }
.inventory-count-sidebar form h2 { margin: -6px 0 3px; }
.inventory-count-sidebar label { display: grid; gap: 7px; color: #536b79; font-size: .78rem; font-weight: 750; }
.inventory-count-sidebar select, .inventory-count-sidebar textarea { width: 100%; border: 1px solid #cad9e0; border-radius: 9px; background: #fbfcfd; }
.inventory-count-history { display: grid; gap: 8px; margin-top: 18px; }
.inventory-count-history__item { display: flex; align-items: center; justify-content: space-between; gap: 8px; width: 100%; padding: 11px; text-align: left; border: 1px solid #dde6ea; border-radius: 10px; background: #fff; }
.inventory-count-history__item:hover, .inventory-count-history__item--active { border-color: #7bb69e; background: #f1faf6; }
.inventory-count-history__item span { display: grid; gap: 3px; min-width: 0; }
.inventory-count-history__item small { overflow: hidden; color: #788995; font-size: .67rem; text-overflow: ellipsis; white-space: nowrap; }
.inventory-count-status { display: inline-flex; width: max-content; padding: 5px 8px; border: 1px solid transparent; border-radius: 999px; font-size: .66rem; font-weight: 850; }
.inventory-count-status--draft { color: #8a5a12; background: #fff6e7; border-color: #efd6aa; }
.inventory-count-status--confirmed { color: #176b47; background: #eaf7ef; border-color: #c9e6d5; }
.inventory-count-status--cancelled { color: #9b3b36; background: #fff0ef; border-color: #efc8c5; }
.inventory-count-workspace { min-width: 0; padding: 20px; }
.inventory-count-heading { align-items: start; padding-bottom: 16px; border-bottom: 1px solid #e1e9ed; }
.inventory-count-heading small { color: #748692; }
.inventory-count-summary { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; margin: 17px 0; }
.inventory-count-summary article { display: grid; gap: 4px; padding: 14px 15px; border: 1px solid #dce6ea; border-radius: 11px; background: #f9fbfb; }
.inventory-count-summary span { color: #687b87; font-size: .74rem; font-weight: 700; }
.inventory-count-summary strong { color: #183f31; font-size: 1.2rem; }
.inventory-count-table { min-width: 1050px; }
.inventory-count-table th { white-space: nowrap; }
.inventory-count-table td { vertical-align: middle; }
.inventory-count-table td small { display: block; margin-top: 3px; color: #788995; }
.inventory-count-table input { width: 100%; min-width: 105px; min-height: 38px; padding: 7px 9px; border: 1px solid #cfdae0; border-radius: 8px; }
.inventory-count-table .inventory-count-input { max-width: 135px; text-align: right; font-weight: 800; }
.inventory-count-number { text-align: right; font-variant-numeric: tabular-nums; font-weight: 750; }
.inventory-count-positive { color: #18724b; }
.inventory-count-negative { color: #b5433a; }
.inventory-count-actions { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: 18px; padding-top: 17px; border-top: 1px solid #e1e9ed; }
.inventory-count-actions > div { display: flex; gap: 10px; }
.inventory-count-print-brand { display: none; }
@media (max-width: 1050px) { .inventory-count-layout { grid-template-columns: 1fr; } .inventory-count-sidebar { position: static; } .inventory-count-summary { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 650px) { .inventory-count-page { padding: 16px 12px 36px; } .inventory-count-summary { grid-template-columns: 1fr; } .inventory-count-actions, .inventory-count-actions > div { align-items: stretch; flex-direction: column; } }
@media print {
  body > * { visibility: hidden !important; }
  .inventory-count-page, .inventory-count-page * { visibility: visible !important; }
  .inventory-count-page { position: absolute !important; inset: 0 !important; display: block !important; width: 100% !important; max-width: none !important; margin: 0 !important; padding: 0 !important; background: #fff !important; }
  .inventory-count-page > .module-header, .inventory-count-page > .maintenance-alert, .inventory-count-sidebar, .inventory-count-actions { display: none !important; }
  .inventory-count-print-brand { display: flex !important; align-items: center; gap: 13px; margin-bottom: 5mm; padding-bottom: 3mm; border-bottom: 2px solid #176b4d; }
  .inventory-count-print-brand img { width: 15mm; height: 15mm; object-fit: contain; }
  .inventory-count-print-brand h1 { margin: 1mm 0; font-size: 16pt; }
  .inventory-count-print-brand p { margin: 0; font-size: 8pt; }
  .inventory-count-layout { display: block !important; }
  .inventory-count-workspace { display: block !important; padding: 0 !important; border: 0 !important; box-shadow: none !important; }
  .inventory-count-summary { grid-template-columns: repeat(4, 1fr); gap: 2mm; margin: 3mm 0; }
  .inventory-count-summary article { padding: 2mm; border-radius: 0; }
  .inventory-count-page .maintenance-table-wrap { overflow: visible !important; }
  .inventory-count-table { width: 100% !important; min-width: 0 !important; font-size: 7pt; }
  .inventory-count-table th, .inventory-count-table td { padding: 1.5mm !important; }
  .inventory-count-table tr { break-inside: avoid; page-break-inside: avoid; }
  @page { size: A4 landscape; margin: 9mm; }
}

/* INVENTORY_AUDIT_HISTORY_V1 */
.inventory-audit-page { width: min(100%, 1540px); max-width: 1540px; margin: 0 auto; padding: 28px clamp(18px, 3vw, 40px) 52px; }
.inventory-audit-page > .module-header, .inventory-audit-page > .maintenance-alert, .inventory-audit-page > .maintenance-card { width: 100%; max-width: none; margin-inline: 0; }
.inventory-audit-page > .module-header { margin-bottom: 16px; border: 1px solid #d9e5e9; border-radius: 15px; box-shadow: 0 9px 26px rgba(27,64,51,.06); }
.inventory-audit-filters { display: grid; grid-template-columns: 280px minmax(260px, 1fr); gap: 14px; align-items: end; margin-bottom: 16px; padding: 18px 20px !important; border: 1px solid #d4e1e6; border-left: 4px solid #4d8fac; border-radius: 14px; }
.inventory-audit-filters label { display: grid; gap: 7px; color: #536b79; font-size: .78rem; font-weight: 750; }
.inventory-audit-filters select { min-height: 43px; border: 1px solid #cad9e0; border-radius: 9px; background: #fbfcfd; }
.inventory-audit-filters .maintenance-search { min-height: 43px; width: 100%; border: 1px solid #cad9e0; border-radius: 9px; }
.inventory-audit-card { padding: 20px !important; border: 1px solid #d2e0e6; border-radius: 15px; box-shadow: 0 10px 30px rgba(31,55,70,.055); }
.inventory-audit-card .maintenance-toolbar { padding-bottom: 16px; border-bottom: 1px solid #e2eaee; }
.inventory-audit-card .maintenance-table-wrap { margin-top: 18px; overflow: auto; border: 1px solid #d5e1e6; border-radius: 12px; }
.inventory-audit-table { min-width: 1420px; }
.inventory-audit-table th { padding: 13px 11px; color: #536a78; background: #f2f7f8; font-size: .7rem; white-space: nowrap; }
.inventory-audit-table td { padding: 12px 11px; border-bottom: 1px solid #e7edef; vertical-align: middle; }
.inventory-audit-table td small { display: block; margin-top: 3px; color: #788995; font-size: .7rem; }
.inventory-audit-table tbody tr:nth-child(even) { background: #fbfcfc; }
.inventory-audit-table tbody tr:hover { background: #f3faf7; }
.inventory-audit-number { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.inventory-audit-type { display: inline-flex; padding: 5px 8px; border-radius: 999px; font-size: .66rem; font-weight: 850; white-space: nowrap; }
.inventory-audit-type--in { color: #12613f; background: #e7f5ed; border: 1px solid #cce7d8; }
.inventory-audit-type--out { color: #a23b34; background: #fff0ee; border: 1px solid #f0ccc7; }
.inventory-audit-print-brand { display: none; }
@media (max-width: 760px) { .inventory-audit-page { padding: 16px 12px 36px; } .inventory-audit-filters { grid-template-columns: 1fr; } }
@media print {
  body > * { visibility: hidden !important; }
  .inventory-audit-page, .inventory-audit-page * { visibility: visible !important; }
  .inventory-audit-page { position: absolute !important; inset: 0 !important; width: 100% !important; max-width: none !important; padding: 0 !important; background: #fff !important; }
  .inventory-audit-page > .module-header, .inventory-audit-page > .maintenance-alert, .inventory-audit-filters { display: none !important; }
  .inventory-audit-print-brand { display: flex !important; align-items: center; gap: 13px; margin-bottom: 5mm; padding-bottom: 3mm; border-bottom: 2px solid #176b4d; }
  .inventory-audit-print-brand img { width: 15mm; height: 15mm; object-fit: contain; }
  .inventory-audit-print-brand h1 { margin: 1mm 0; font-size: 16pt; }
  .inventory-audit-print-brand p { margin: 0; font-size: 8pt; }
  .inventory-audit-card { display: block !important; padding: 0 !important; border: 0 !important; box-shadow: none !important; }
  .inventory-audit-card .maintenance-toolbar { display: none !important; }
  .inventory-audit-card .maintenance-table-wrap { overflow: visible !important; border-radius: 0; }
  .inventory-audit-table { display: table !important; width: 100% !important; min-width: 0 !important; font-size: 6.5pt; }
  .inventory-audit-table th, .inventory-audit-table td { padding: 1.4mm !important; }
  .inventory-audit-table tr { display: table-row !important; break-inside: avoid; page-break-inside: avoid; }
  @page { size: A4 landscape; margin: 9mm; }
}

* { box-sizing: border-box; }
body { margin: 0; min-width: 320px; min-height: 100vh; }
button, input, select { font: inherit; }

button {
  min-height: 48px;
  border: 0;
  border-radius: 12px;
  padding: 0 20px;
  font-weight: 700;
  background: #1f5c3f;
  color: white;
  cursor: pointer;
}

button:hover { filter: brightness(.96); }
.secondary-button { background: #e7eee9; color: #1f4b37; }
.shell { max-width: 1240px; margin: 0 auto; padding: 28px; }

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding-bottom: 28px;
}

.topbar-actions { display: flex; align-items: center; gap: 12px; }
.user-label { color: #617067; font-weight: 700; }
.brand { font-size: 24px; font-weight: 900; letter-spacing: 0.08em; }
.topbar p, .brand-block p { margin: 2px 0 0; color: #66756b; }

.hero {
  border-radius: 24px;
  padding: 40px;
  background: linear-gradient(135deg, #e6efe8, #ffffff);
  border: 1px solid #dce7df;
}

.eyebrow { text-transform: uppercase; letter-spacing: .12em; font-weight: 800; color: #1f5c3f; }
.hero h1 { max-width: 700px; margin: 10px 0; font-size: clamp(34px, 6vw, 64px); line-height: 1; }
.hero p:last-child, .muted { color: #59685f; font-size: 18px; }

.grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin: 24px 0;
}

.card, .panel, .login-card {
  background: white;
  border: 1px solid #e1e7e2;
  border-radius: 18px;
  padding: 22px;
}

.card span { color: #69776e; }
.card strong { display: block; margin-top: 12px; font-size: 30px; }
.status-row { display: flex; gap: 10px; align-items: center; font-weight: 700; }
.dot { width: 10px; height: 10px; border-radius: 50%; background: #2c8c5b; }

.auth-shell {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background:
    radial-gradient(circle at top left, rgba(44, 140, 91, .14), transparent 34%),
    #f5f7f3;
}

.login-card {
  width: min(460px, 100%);
  padding: 34px;
  display: grid;
  gap: 28px;
  box-shadow: 0 24px 60px rgba(24, 54, 38, .08);
}

.brand-block { padding-bottom: 10px; border-bottom: 1px solid #e8ece9; }
.form-stack, .order-form { display: grid; gap: 18px; }

.form-stack label, .order-form label {
  display: grid;
  gap: 8px;
  font-weight: 700;
  color: #34453a;
}

input, select {
  width: 100%;
  min-height: 50px;
  border: 1px solid #cfd9d2;
  border-radius: 12px;
  padding: 0 14px;
  background: white;
  color: #17211a;
}

input:focus, select:focus {
  outline: 3px solid rgba(44, 140, 91, .14);
  border-color: #2c8c5b;
}

.error-message { margin: 0; color: #a13c3c; font-weight: 700; }
.demo-note { margin: 0; color: #6b786f; font-size: 14px; }
.order-panel { padding: 30px; }
.order-form { grid-template-columns: repeat(2, minmax(0, 1fr)); margin-top: 28px; }
.form-actions { grid-column: 1 / -1; display: flex; justify-content: flex-end; gap: 12px; }

.success-box {
  margin-top: 22px;
  border-radius: 12px;
  padding: 16px;
  background: #e7f5ec;
  color: #1f5c3f;
  font-weight: 700;
}

@media (max-width: 850px) {
  .grid { grid-template-columns: repeat(2, 1fr); }
  .order-form { grid-template-columns: 1fr; }
  .shell { padding: 18px; }
  .hero { padding: 28px; }
}

@media (max-width: 600px) {
  .grid { grid-template-columns: 1fr; }
  .topbar { align-items: flex-start; flex-direction: column; }
  .topbar-actions { width: 100%; flex-wrap: wrap; }
  .topbar-actions button { flex: 1; }
}


/* POS táctil */
.pos-shell {
  min-height: 100vh;
  background: #eef1ee;
}

.pos-topbar {
  min-height: 78px;
  display: grid;
  grid-template-columns: 240px 1fr 180px;
  align-items: center;
  gap: 18px;
  padding: 12px 18px;
  background: #ffffff;
  border-bottom: 1px solid #dce3de;
  position: sticky;
  top: 0;
  z-index: 20;
}

.pos-brand-block {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.pos-brand-block > span:last-child {
  color: #6b786f;
  font-size: 14px;
}

.pos-nav {
  display: flex;
  gap: 8px;
  overflow-x: auto;
}

.nav-chip {
  white-space: nowrap;
  min-height: 44px;
  background: #edf2ee;
  color: #274534;
  border-radius: 10px;
}

.active-chip {
  background: #1f5c3f;
  color: #ffffff;
}

.cashier-box {
  text-align: right;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.cashier-box span {
  color: #758178;
  font-size: 13px;
}

.pos-content {
  display: grid;
  grid-template-columns: minmax(380px, 32%) 1fr;
  min-height: calc(100vh - 78px);
}

.order-sidebar {
  background: #ffffff;
  border-right: 1px solid #dce3de;
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  position: sticky;
  top: 78px;
  height: calc(100vh - 78px);
  overflow: auto;
}

.order-sidebar label {
  display: grid;
  gap: 7px;
  font-weight: 700;
  color: #34453a;
}

.order-sidebar-header {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
}

.order-sidebar-header h1 {
  margin: 2px 0 0;
  font-size: 30px;
}

.icon-button {
  width: 44px;
  min-height: 44px;
  padding: 0;
  border-radius: 50%;
  background: #edf2ee;
  color: #2d4938;
  font-size: 26px;
}

.compact-grid {
  display: grid;
  grid-template-columns: 1fr 140px;
  gap: 12px;
}

.order-lines {
  flex: 1;
  min-height: 220px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  overflow: auto;
}

.empty-order {
  min-height: 180px;
  display: grid;
  place-items: center;
  align-content: center;
  text-align: center;
  color: #77837b;
  border: 1px dashed #cad4cd;
  border-radius: 14px;
}

.empty-order span {
  font-size: 34px;
}

.order-line {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px;
  padding: 14px 42px 14px 14px;
  border: 1px solid #e0e6e2;
  border-radius: 12px;
  background: #fbfcfb;
}

.order-line > div:first-child,
.order-line-amount {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.order-line span {
  color: #6d7a71;
  font-size: 13px;
}

.order-line-amount {
  text-align: right;
}

.remove-line {
  position: absolute;
  top: 8px;
  right: 8px;
  width: 28px;
  min-height: 28px;
  padding: 0;
  border-radius: 50%;
  background: #f5e8e8;
  color: #8e3b3b;
}

.totals-box {
  border-top: 1px solid #dde4df;
  padding-top: 14px;
  display: grid;
  gap: 8px;
}

.totals-box > div {
  display: flex;
  justify-content: space-between;
  gap: 20px;
}

.grand-total {
  margin-top: 4px;
  padding-top: 12px;
  border-top: 1px dashed #cbd5ce;
  font-size: 22px;
}

.order-actions {
  display: grid;
  grid-template-columns: 1fr 1.2fr 1.1fr;
  gap: 10px;
}

.hold-button {
  background: #d7a53f;
  color: #2b2415;
}

.pay-button {
  background: #111814;
}

.catalog-panel {
  padding: 18px;
  overflow: auto;
}

.catalog-toolbar {
  display: flex;
  gap: 12px;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.search-box {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 8px;
  max-width: 560px;
  background: white;
  border: 1px solid #d6dfd9;
  border-radius: 12px;
  padding: 0 12px;
}

.search-box input {
  border: 0;
  min-height: 48px;
  padding-left: 0;
}

.search-box input:focus {
  outline: 0;
}

.category-tabs {
  display: flex;
  gap: 8px;
}

.category-tab {
  min-height: 46px;
  background: #ffffff;
  color: #34503f;
  border: 1px solid #d5ded8;
}

.selected-tab {
  background: #1f5c3f;
  color: white;
}

.service-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 14px;
}

.service-card {
  min-height: 180px;
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: flex-start;
  gap: 4px;
  padding: 16px;
  background: white;
  color: #1b2b21;
  border: 1px solid #d9e1dc;
  border-radius: 16px;
  text-align: left;
  box-shadow: 0 6px 16px rgba(24, 56, 38, 0.04);
}

.service-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 26px rgba(24, 56, 38, 0.08);
}

.service-card-price {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  padding: 8px 10px;
  border-radius: 16px 16px 0 0;
  background: #e7efe9;
  color: #1f5c3f;
  text-align: right;
  font-weight: 900;
}

.service-card-icon {
  font-size: 44px;
  margin-bottom: 8px;
}

.service-card strong {
  font-size: 15px;
}

.service-card span,
.service-card small {
  color: #6d7a71;
}

@media (max-width: 1080px) {
  .pos-topbar {
    grid-template-columns: 180px 1fr;
  }

  .cashier-box {
    display: none;
  }

  .pos-content {
    grid-template-columns: minmax(340px, 42%) 1fr;
  }
}

@media (max-width: 820px) {
  .pos-topbar {
    position: static;
    grid-template-columns: 1fr;
  }

  .pos-content {
    grid-template-columns: 1fr;
  }

  .order-sidebar {
    position: static;
    height: auto;
  }

  .catalog-panel {
    min-height: 560px;
  }

  .catalog-toolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .search-box {
    max-width: none;
  }
}

@media (max-width: 520px) {
  .compact-grid,
  .order-actions {
    grid-template-columns: 1fr;
  }

  .service-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .service-card {
    min-height: 160px;
  }
}

.error-box {
  border-radius: 12px;
  padding: 14px;
  background: #faeaea;
  color: #8f3434;
  font-weight: 700;
}

.catalog-message {
  padding: 28px;
  text-align: center;
  color: #6e7a72;
  background: white;
  border: 1px dashed #ccd5cf;
  border-radius: 14px;
  margin-bottom: 14px;
}

button:disabled {
  opacity: .65;
  cursor: wait;
}

.service-grid { grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); }

.brand-button {
  min-height: 54px;
  padding: 4px 8px;
  background: transparent;
  color: #17211a;
  display: flex;
  align-items: center;
  gap: 10px;
  justify-content: flex-start;
}
