.command-center {
  --cc-bg: #f2f5f3;
  --cc-surface: #ffffff;
  --cc-surface-soft: #f7f9f8;

  --cc-text: #101a14;
  --cc-muted: #778179;

  --cc-green-950: #071d13;
  --cc-green-900: #0b2d1e;
  --cc-green-800: #10402b;
  --cc-green-600: #187047;
  --cc-green-500: #25915e;
  --cc-green-soft: #e8f2ec;

  --cc-border: #dfe7e2;

  --cc-radius: 22px;
  --cc-shadow:
    0 20px 60px rgba(12, 44, 29, .07);

  min-height: 100vh;

  display: grid;
  grid-template-columns: 240px minmax(0, 1fr);

  background:
    radial-gradient(
      circle at 90% 0%,
      rgba(37, 145, 94, .07),
      transparent 25%
    ),
    var(--cc-bg);

  color: var(--cc-text);
}

