  min-height: 100vh;

  position: sticky;
  top: 0;

  align-self: start;

  height: 100vh;

  display: flex;
  flex-direction: column;

  padding: 22px 16px;

  background:
    linear-gradient(
      180deg,
      var(--cc-green-950),
      #09170f
    );

  color: white;
}

.command-brand {
  min-height: 54px;

  display: flex;
  align-items: center;
  gap: 11px;

  padding: 6px 8px;

  background: transparent;

  text-align: left;
}

.command-brand:hover {
  filter: none;
}

.command-brand__mark {
  width: 42px;
  height: 42px;

  display: grid;
  place-items: center;

  border-radius: 13px;

  background:
    linear-gradient(
      145deg,
      #2a9965,
      #176741
    );

  font-weight: 950;
  font-size: 19px;

  box-shadow:
    0 10px 30px rgba(33, 142, 91, .22);
}

.command-brand__copy {
  display: grid;
  gap: 1px;
}

.command-brand__copy strong {
  font-size: 16px;
  letter-spacing: .12em;
}

.command-brand__copy small {
  color: rgba(255, 255, 255, .46);
  font-size: 10px;
}

.command-nav {
  flex: 1;

  display: flex;
  flex-direction: column;
  gap: 24px;

  margin-top: 34px;
}

.command-nav__group {
  display: grid;
  gap: 5px;
}

.command-nav__group--bottom {
  margin-top: auto;
}

.command-nav__group > small {
  padding: 0 12px 6px;

  color: rgba(255, 255, 255, .32);

  font-size: 9px;
  font-weight: 850;
  letter-spacing: .13em;
}

.command-nav button {
  min-height: 44px;

  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 11px;

  padding: 0 12px;

  border-radius: 12px;

  background: transparent;
  color: rgba(255, 255, 255, .64);

  font-size: 13px;
  font-weight: 650;
}

.command-nav button:hover {
  filter: none;

  background: rgba(255, 255, 255, .06);
  color: white;
}

.command-nav button.active {
  background: rgba(255, 255, 255, .1);
  color: white;

  box-shadow:
    inset 0 0 0 1px
    rgba(255, 255, 255, .06);
}

.command-sidebar__profile {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 10px;
  align-items: center;

  margin-top: 20px;
  padding: 12px;

  border-top:
    1px solid rgba(255, 255, 255, .08);
}

.command-avatar {
  width: 34px;
  height: 34px;

  display: grid;
  place-items: center;

  border-radius: 11px;

  background: rgba(255, 255, 255, .09);

  font-size: 13px;
  font-weight: 850;
}

.command-sidebar__profile > div:nth-child(2) {
  min-width: 0;

  display: grid;
  gap: 2px;
}

.command-sidebar__profile strong {
  overflow: hidden;
  text-overflow: ellipsis;

  font-size: 12px;
  white-space: nowrap;
}

.command-sidebar__profile small {
  color: rgba(255, 255, 255, .4);
  font-size: 9px;
}

.command-logout {
  width: 34px;
  min-height: 34px;

  padding: 0;

  display: grid;
  place-items: center;

  border-radius: 10px;

  background: rgba(255, 255, 255, .06);
  color: rgba(255, 255, 255, .65);
}

/* Workspace */

.command-workspace {
  min-width: 0;

  padding: 34px;
}

.command-header,
.command-bento,
.command-section,
.command-bottom-grid {
  width: min(1440px, 100%);
  margin-left: auto;
  margin-right: auto;
}

.command-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 30px;

  margin-bottom: 24px;
}

.command-kicker {
  color: var(--cc-green-600);

  font-size: 10px;
  font-weight: 850;
  letter-spacing: .13em;
  text-transform: uppercase;
}

.command-header h1 {
  margin: 7px 0 4px;

  font-size:
    clamp(32px, 4vw, 52px);

  line-height: 1;
  letter-spacing: -.04em;
}

.command-header p {
  margin: 0;

  color: var(--cc-muted);

  font-size: 14px;
}

.command-primary-action {
  min-height: 46px;

  display: inline-flex;
  align-items: center;
  gap: 8px;

  border-radius: 13px;

  background:
    linear-gradient(
      145deg,
      var(--cc-green-600),
      var(--cc-green-800)
    );
}

/* Bento */

.command-bento {
  display: grid;

  grid-template-columns:
    minmax(0, 1.7fr)
    minmax(240px, .65fr);

  grid-template-rows: 1fr 1fr;

  gap: 14px;
}

.command-bento > article {
  border-radius: var(--cc-radius);

  box-shadow:
    0 10px 35px rgba(10, 43, 27, .045);
}

.command-bento__sales {
  grid-row: 1 / 3;

  min-height: 340px;

  padding: 28px;

  position: relative;
  overflow: hidden;

  background:
    linear-gradient(
      140deg,
      var(--cc-green-950),
      #10482f
    );

  color: white;
}

.command-bento__sales::after {
  content: '';

  position: absolute;

  width: 380px;
  height: 380px;

  right: -100px;
  top: -130px;

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(81, 204, 135, .2),
      transparent 68%
    );
}

.command-bento__eyebrow {
  position: relative;
  z-index: 1;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  color: rgba(255, 255, 255, .55);

  font-size: 10px;
  font-weight: 800;
  letter-spacing: .1em;
}

.command-live-indicator {
  display: inline-flex;
  align-items: center;
  gap: 7px;

  font-size: 10px;
  letter-spacing: 0;
}

.command-live-indicator > span {
  width: 7px;
  height: 7px;

  border-radius: 50%;

  background: #64d991;

  box-shadow:
    0 0 0 5px rgba(100, 217, 145, .1);
}

.command-bento__big-number {
  position: relative;
  z-index: 1;

  display: block;

  margin-top: 38px;

  font-size:
    clamp(38px, 5vw, 68px);

  line-height: 1;
  letter-spacing: -.05em;
}

.command-bento__sales > p {
  position: relative;
  z-index: 1;

  max-width: 500px;

  margin: 12px 0 0;

  color: rgba(255, 255, 255, .55);
  font-size: 12px;
}

.command-fake-chart {
  position: absolute;

  left: 28px;
  right: 28px;
  bottom: 28px;

  height: 92px;

  display: flex;
  align-items: flex-end;
  gap: 7px;
}

.command-fake-chart span {
  flex: 1;

  min-height: 10px;

  border-radius: 6px 6px 2px 2px;

  background:
    linear-gradient(
      180deg,
      rgba(100, 217, 145, .95),
      rgba(100, 217, 145, .16)
    );
}

.command-bento__vehicles,
.command-bento__delivery {
  padding: 21px;

  display: flex;
  flex-direction: column;

  border: 1px solid var(--cc-border);

  background: var(--cc-surface);
}

.command-card-icon {
  width: 42px;
  height: 42px;

  display: grid;
  place-items: center;

  margin-bottom: auto;

  border-radius: 13px;

  background: var(--cc-green-soft);
  color: var(--cc-green-600);
}

.command-bento__vehicles > span,
.command-bento__delivery > span {
  margin-top: 16px;

  color: var(--cc-muted);
  font-size: 11px;
}

.command-bento__vehicles > strong,
.command-bento__delivery > strong {
  margin-top: 4px;

  font-size: 34px;
  letter-spacing: -.04em;
}

.command-bento__delivery p {
  margin: 5px 0 0;

  color: var(--cc-muted);
  font-size: 10px;
}

.command-stat-line {
  display: flex;
  gap: 10px;

  margin-top: 7px;

  color: var(--cc-muted);
  font-size: 9px;
}

/* Sections */

.command-section {
  margin-top: 30px;
}

.command-section__heading {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 20px;

  margin-bottom: 13px;
}

.command-section__heading > div {
  display: grid;
  gap: 3px;
}

.command-section__heading span {
  color: var(--cc-green-600);

  font-size: 9px;
  font-weight: 850;
  letter-spacing: .11em;
}

.command-section__heading h2 {
  margin: 0;

  font-size: 21px;
  letter-spacing: -.025em;
}

.command-section__heading p {
  max-width: 390px;

  margin: 0;

  color: var(--cc-muted);
  font-size: 11px;
}

/* Modules */

.command-module-grid {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 12px;
}

.command-module {
  position: relative;

  min-height: 210px;

  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-start;

  padding: 20px;

  border: 1px solid var(--cc-border);
  border-radius: 20px;

  background: white;
  color: var(--cc-text);

  text-align: left;

  box-shadow:
    0 8px 25px rgba(10, 43, 27, .035);

  transition:
    transform .18s cubic-bezier(.2,.8,.2,1),
    box-shadow .18s ease,
    border-color .18s ease;
}

.command-module:hover {
  filter: none;

  transform: translateY(-4px);

  border-color: #b9cec0;

  box-shadow:
    0 18px 45px rgba(10, 43, 27, .085);
}

.command-module--dark {
  border-color: transparent;

  background:
    linear-gradient(
      145deg,
      #0b2c1d,
      #123f2a
    );

  color: white;
}

.command-module__icon {
  width: 48px;
  height: 48px;

  display: grid;
  place-items: center;

  margin-bottom: 22px;

  border-radius: 14px;

  background: var(--cc-green-soft);
  color: var(--cc-green-600);
}

.command-module--dark .command-module__icon {
  background: rgba(255, 255, 255, .09);
  color: white;
}

.command-module > div:nth-child(2) {
  display: grid;
  gap: 5px;
}

.command-module small {
  color: var(--cc-muted);

  font-size: 8px;
  font-weight: 850;
  letter-spacing: .1em;
}

.command-module--dark small {
  color: rgba(255, 255, 255, .42);
}

.command-module strong {
  font-size: 19px;
}

.command-module p {
  margin: 0;

  color: var(--cc-muted);

  font-size: 11px;
  font-weight: 500;
  line-height: 1.45;
}

.command-module--dark p {
  color: rgba(255, 255, 255, .55);
}

.command-module__arrow {
  position: absolute;

  right: 18px;
  bottom: 16px;

  font-size: 19px;

  opacity: .52;
}

/* Bottom */

.command-bottom-grid {
  display: grid;
  grid-template-columns:
    minmax(0, 1.5fr)
    minmax(300px, .7fr);

  gap: 14px;

  margin-top: 30px;
}

.command-recent,
.command-management {
  padding: 20px;

  border: 1px solid var(--cc-border);
  border-radius: 20px;

  background: var(--cc-surface);
}

.command-activity-list {
  display: grid;
}

.command-activity-list article {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 12px;
  align-items: center;

  padding: 13px 0;

  border-bottom: 1px solid #edf1ee;
}

.command-activity-list article:last-child {
  border-bottom: 0;
}

.command-activity-icon {
  width: 37px;
  height: 37px;

  display: grid;
  place-items: center;

  border-radius: 11px;

  background: var(--cc-green-soft);
  color: var(--cc-green-600);
}

.command-activity-list article > div {
  display: grid;
  gap: 3px;
}

.command-activity-list strong {
  font-size: 12px;
}

.command-activity-list small {
  color: var(--cc-muted);
  font-size: 10px;
}

.command-status-pill {
  padding: 5px 8px;

  border-radius: 999px;

  background: var(--cc-green-soft);
  color: var(--cc-green-600);

  font-size: 9px;
  font-weight: 800;
}

.command-management__links {
  display: grid;
  gap: 7px;
}

.command-management__links button {
  min-height: 58px;

  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 10px;
  align-items: center;

  padding: 10px 12px;

  border: 1px solid transparent;
  border-radius: 13px;

  background: #f8faf9;
  color: var(--cc-text);

  text-align: left;
}

.command-management__links button:hover {
  filter: none;

  border-color: var(--cc-border);
  background: white;
}

.command-management__links svg {
  color: var(--cc-green-600);
}

.command-management__links span {
  display: grid;
  gap: 2px;
}

.command-management__links strong {
  font-size: 11px;
}

.command-management__links small {
  color: var(--cc-muted);
  font-size: 9px;
}

.command-management__links b {
  color: var(--cc-muted);
  font-size: 13px;
}

/* Responsive */

@media (max-width: 1180px) {
  .command-center {
    grid-template-columns: 78px minmax(0, 1fr);
  }

  .command-sidebar {
    padding-left: 12px;
    padding-right: 12px;
  }

  .command-brand {
    justify-content: center;
  }

  .command-brand__copy,
  .command-nav button:not(.active) {
  }

  .command-brand__copy,
  .command-nav__group > small,
  .command-nav button {
    font-size: 0;
  }

  .command-nav button {
    justify-content: center;
    padding: 0;
  }

  .command-sidebar__profile {
    grid-template-columns: 1fr;
    justify-items: center;
  }

  .command-sidebar__profile > div:nth-child(2) {
    display: none;
  }

  .command-module-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 820px) {
  .command-center {
    display: block;
  }

  .command-sidebar {
    position: static;

    width: 100%;
    height: auto;
    min-height: 0;

    display: flex;
    flex-direction: row;
    align-items: center;

    padding: 10px 14px;
  }

  .command-brand {
    margin-right: auto;
  }

  .command-brand__copy {
    display: grid;
  }

  .command-nav {
    flex: initial;

    display: flex;
    flex-direction: row;

    margin: 0;
  }

  .command-nav__group {
    display: flex;
  }

  .command-nav__group:not(:first-child) {
    display: none;
  }

  .command-nav__group button {
    display: none;
  }

  .command-sidebar__profile {
    display: flex;

    margin: 0;
    padding: 0;

    border: 0;
  }

  .command-workspace {
    padding: 20px;
  }

  .command-bento,
  .command-bottom-grid {
    grid-template-columns: 1fr;
  }

  .command-bento__sales {
    grid-row: auto;
  }

  .command-bento__vehicles,
  .command-bento__delivery {
    min-height: 170px;
  }
}

@media (max-width: 620px) {
  .command-workspace {
    padding: 16px;
  }

  .command-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .command-primary-action {
    width: 100%;
    justify-content: center;
  }

  .command-module-grid {
    grid-template-columns: 1fr;
  }

  .command-bento__sales {
    min-height: 310px;
    padding: 22px;
  }

  .command-fake-chart {
    left: 22px;
    right: 22px;
  }

  .command-section__heading {
    align-items: flex-start;
    flex-direction: column;
  }
}
/* =========================================================
   CACTUS ALIMENTOS Y BEBIDAS POS V2 — COMMAND CENTER VISUAL LAYER
   Visual only: no business logic changes.
   ========================================================= */

.coffee-pos {
  --cb-bg: #f2f5f3;
  --cb-surface: #ffffff;
  --cb-soft: #f7f9f8;
  --cb-text: #101a14;
  --cb-muted: #758078;
  --cb-green-950: #071d13;
  --cb-green-900: #0b2d1e;
  --cb-green-800: #10402b;
  --cb-green-700: #155a3b;
  --cb-green-600: #187047;
  --cb-green-500: #25915e;
  --cb-green-soft: #e8f2ec;
  --cb-border: #dfe7e2;
  --cb-shadow: 0 20px 60px rgba(12, 44, 29, .07);

  min-height: 100vh;
  padding: 24px;
  color: var(--cb-text);
  background:
    radial-gradient(circle at 90% 0%, rgba(37, 145, 94, .08), transparent 24%),
    radial-gradient(circle at 8% 10%, rgba(24, 112, 71, .05), transparent 22%),
    var(--cb-bg);
}

.coffee-pos__header,
.coffee-pos__layout,
.coffee-hold-board,
.coffee-pos > .operations-error,
.coffee-pos > .operations-success {
  width: min(1500px, 100%);
  max-width: none;
  margin-left: auto;
  margin-right: auto;
}

.coffee-pos__header {
  margin-bottom: 18px;
  padding: 20px 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  border: 1px solid rgba(255, 255, 255, .72);
  border-radius: 22px;
  background:
    linear-gradient(135deg, rgba(255,255,255,.97), rgba(239,246,241,.94));
  box-shadow: var(--cb-shadow);
  backdrop-filter: blur(16px);
}

.coffee-pos__header > div:first-child {
  display: grid;
  gap: 3px;
}

.coffee-pos__header .brand {
  width: fit-content;
  padding: 5px 9px;
  border-radius: 999px;
  background: var(--cb-green-soft);
  color: var(--cb-green-600);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .14em;
}

.coffee-pos__header h1 {
  margin: 2px 0 0;
  font-size: clamp(28px, 3vw, 42px);
  line-height: 1;
  letter-spacing: -.035em;
}

.coffee-pos__header p {
  margin: 5px 0 0;
  color: var(--cb-muted);
  font-size: 13px;
}

.coffee-pos__tabs {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px;
  border: 1px solid var(--cb-border);
  border-radius: 14px;
  background: rgba(255, 255, 255, .78);
}

.coffee-pos__tabs button {
  min-height: 40px;
  padding: 0 13px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #506057;
  font-size: 12px;
  font-weight: 800;
  transition:
    transform .16s ease,
    background .16s ease,
    color .16s ease,
    box-shadow .16s ease;
}

.coffee-pos__tabs button:hover {
  filter: none;
  transform: translateY(-1px);
  background: #f1f5f2;
}

.coffee-pos__tabs button.active {
  background: linear-gradient(145deg, var(--cb-green-600), var(--cb-green-800));
  color: #fff;
  box-shadow: 0 8px 20px rgba(24, 112, 71, .18);
}

/* Layout */

.coffee-pos__layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 400px;
  gap: 16px;
  align-items: start;
}

.coffee-pos__catalog {
  min-width: 0;
  display: grid;
  gap: 14px;
  align-content: start;
  padding: 18px;
  border: 1px solid var(--cb-border);
  border-radius: 22px;
  background: rgba(255,255,255,.92);
  box-shadow: 0 12px 34px rgba(12, 44, 29, .045);
}

.coffee-pos__catalog .operations-search {
  min-height: 48px;
  padding: 0 14px;
  display: flex;
  align-items: center;
  gap: 9px;
  border: 1px solid var(--cb-border);
  border-radius: 14px;
  background: var(--cb-soft);
}

.coffee-pos__catalog .operations-search svg {
  color: var(--cb-green-600);
}

.coffee-pos__catalog .operations-search input {
  width: 100%;
  min-height: 46px;
  border: 0;
  outline: 0;
  background: transparent;
  box-shadow: none;
  color: var(--cb-text);
  font-size: 13px;
}

.coffee-pos__catalog .operations-search input:focus {
  outline: 0;
}

.coffee-pos__catalog .operations-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  overflow: visible;
}

.coffee-pos__catalog .operations-filter {
  min-height: 34px;
  padding: 0 12px;
  border: 1px solid var(--cb-border);
  border-radius: 999px;
  background: #fff;
  color: #5e6d63;
  font-size: 11px;
  font-weight: 800;
}

.coffee-pos__catalog .operations-filter--active {
  border-color: transparent;
  background: var(--cb-green-900);
  color: #fff;
}

/* Product cards */

.coffee-pos .retail-product-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.coffee-pos .retail-product-card {
  min-width: 0;
  min-height: 190px;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-start;
  gap: 5px;
  padding: 15px;
  border: 1px solid var(--cb-border);
  border-radius: 18px;
  background: linear-gradient(180deg, #ffffff, #fbfcfb);
  color: var(--cb-text);
  text-align: left;
  box-shadow: 0 8px 20px rgba(12, 44, 29, .035);
  transition:
    transform .18s cubic-bezier(.2,.8,.2,1),
    box-shadow .18s ease,
    border-color .18s ease;
}

.coffee-pos .retail-product-card:hover {
  filter: none;
  transform: translateY(-4px);
  border-color: #b8cec0;
  box-shadow: 0 18px 34px rgba(12, 44, 29, .085);
}

.coffee-pos .retail-product-card:active {
  transform: translateY(-1px) scale(.99);
}

.coffee-pos .retail-product-icon {
  width: 54px;
  height: 54px;
  display: grid;
  place-items: center;
  margin-bottom: 9px;
  border-radius: 16px;
  background: linear-gradient(145deg, var(--cb-green-soft), #dcebe2);
  color: var(--cb-green-600);
}

.coffee-pos .retail-product-card strong {
  display: block;
  width: 100%;
  font-size: 14px;
  line-height: 1.25;
  overflow-wrap: anywhere;
}

.coffee-pos .retail-product-card span {
  color: var(--cb-muted);
  font-size: 10px;
}

.coffee-pos .retail-product-card small {
  margin-top: auto;
  padding-top: 12px;
  color: #89948d;
  font-size: 9px;
}

.coffee-pos .retail-product-card b {
  margin-top: 3px;
  color: var(--cb-green-600);
  font-size: 16px;
  letter-spacing: -.02em;
}

/* Cart panel */

.coffee-pos__cart {
  position: sticky;
  top: 16px;
  min-width: 0;
  max-height: calc(100vh - 32px);
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 11px;
  padding: 18px;
  border: 1px solid rgba(255,255,255,.72);
  border-radius: 22px;
  background: linear-gradient(180deg, rgba(255,255,255,.98), rgba(247,250,248,.97));
  box-shadow: var(--cb-shadow);
  backdrop-filter: blur(18px);
  scrollbar-width: thin;
}

.coffee-pos .retail-cart__title {
  display: flex;
  align-items: center;
  gap: 9px;
  padding-bottom: 12px;
  border-bottom: 1px solid #ebf0ec;
  color: var(--cb-green-600);
}

.coffee-pos .retail-cart__title h2 {
  margin: 0;
  color: var(--cb-text);
  font-size: 20px;
  letter-spacing: -.025em;
}

.coffee-pos__cart > label {
  display: grid;
  gap: 5px;
  color: #59675e;
  font-size: 10px;
  font-weight: 850;
  letter-spacing: .025em;
}

.coffee-pos__cart input,
.coffee-pos__cart select {
  width: 100%;
  min-width: 0;
  min-height: 42px;
  padding: 0 11px;
  border: 1px solid var(--cb-border);
  border-radius: 11px;
  background: #fff;
  color: var(--cb-text);
  font: inherit;
  font-size: 12px;
  outline: none;
  transition:
    border-color .15s ease,
    box-shadow .15s ease;
}

.coffee-pos__cart input:focus,
.coffee-pos__cart select:focus {
  border-color: #8eb8a0;
  box-shadow: 0 0 0 4px rgba(37, 145, 94, .09);
}

.coffee-pos__cart input:disabled,
.coffee-pos__cart select:disabled {
  background: #f1f4f2;
  color: #8b958e;
}

.coffee-pos .retail-cart__items {
  min-height: 70px;
  display: grid;
  gap: 8px;
  padding: 8px 0;
}

.coffee-pos .retail-cart__item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
  padding: 11px;
  border: 1px solid #e8eeea;
  border-radius: 13px;
  background: #fff;
}

.coffee-pos .retail-cart__item > div:first-child {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.coffee-pos .retail-cart__item > div:first-child strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 11px;
}

.coffee-pos .retail-cart__item > div:first-child span {
  color: var(--cb-muted);
  font-size: 9px;
}

.coffee-pos .retail-cart__item > strong {
  grid-column: 2;
  grid-row: 1;
  align-self: start;
  white-space: nowrap;
  color: var(--cb-green-600);
  font-size: 11px;
}

.coffee-pos .quantity-control {
  grid-column: 1 / -1;
  width: 100%;
  display: grid;
  grid-template-columns: 30px 1fr 30px;
  gap: 6px;
  align-items: center;
  margin-top: 3px;
  border: 0;
  background: transparent;
  overflow: visible;
}

.coffee-pos .quantity-control button {
  width: 30px;
  min-height: 30px;
  padding: 0;
  display: grid;
  place-items: center;
  border: 1px solid var(--cb-border);
  border-radius: 9px;
  background: var(--cb-soft);
  color: var(--cb-green-600);
}

.coffee-pos .quantity-control strong {
  text-align: center;
  font-size: 11px;
}

.coffee-pos .selected-account-existing {
  display: grid;
  gap: 7px;
  padding: 12px;
  border: 1px solid #dce9e1;
  border-radius: 14px;
  background: #f1f7f3;
}

.coffee-pos .selected-account-existing h3 {
  margin: 0 0 3px;
  color: var(--cb-green-800);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: .07em;
}

.coffee-pos .selected-account-existing > div {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  font-size: 10px;
}

.coffee-pos .selected-account-summary,
.coffee-pos .retail-cart__total {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 11px 12px;
  border-radius: 12px;
}

.coffee-pos .selected-account-summary {
  background: #edf4ef;
}

.coffee-pos .selected-account-summary span,
.coffee-pos .retail-cart__total span {
  color: var(--cb-muted);
  font-size: 10px;
  font-weight: 800;
}

.coffee-pos .selected-account-summary strong {
  color: var(--cb-green-800);
  font-size: 16px;
}

.coffee-pos .retail-cart__total {
  margin-top: 1px;
  padding: 15px;
  background: linear-gradient(145deg, var(--cb-green-950), var(--cb-green-800));
  color: #fff;
}

.coffee-pos .retail-cart__total span {
  color: rgba(255,255,255,.58);
}

.coffee-pos .retail-cart__total strong {
  font-size: 24px;
  letter-spacing: -.035em;
}

.coffee-pos__cart > button {
  width: 100%;
  min-height: 44px;
  border-radius: 12px;
  font-size: 12px;
  font-weight: 850;
}

.coffee-pos__cart > button:not(.secondary-button) {
  background: linear-gradient(145deg, var(--cb-green-600), var(--cb-green-800));
  box-shadow: 0 10px 22px rgba(24, 112, 71, .15);
}

.coffee-pos__cart > button.secondary-button {
  border: 1px solid var(--cb-border);
  background: #fff;
  color: var(--cb-green-700);
}

/* HOLD */

.coffee-hold-board {
  padding: 18px;
  border: 1px solid var(--cb-border);
  border-radius: 22px;
  background: rgba(255,255,255,.92);
  box-shadow: 0 12px 34px rgba(12, 44, 29, .045);
}

.coffee-hold-board .coffee-account-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.coffee-hold-board .coffee-account-card {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 9px;
  padding: 16px;
  border: 1px solid var(--cb-border);
  border-radius: 18px;
  background: linear-gradient(180deg, #fff, #fbfcfb);
  box-shadow: 0 7px 18px rgba(12,44,29,.035);
  cursor: default;
  transition:
    transform .18s ease,
    box-shadow .18s ease,
    border-color .18s ease;
}

.coffee-hold-board .coffee-account-card:hover {
  transform: translateY(-3px);
  border-color: #bad0c1;
  box-shadow: 0 16px 32px rgba(12,44,29,.08);
}

.coffee-hold-board .coffee-account-card > div:first-child {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.coffee-hold-board .coffee-account-card > div:first-child > strong {
  color: var(--cb-green-600);
  font-size: 10px;
  letter-spacing: .06em;
}

.coffee-hold-board .coffee-status {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--cb-green-soft);
  color: var(--cb-green-600);
  font-size: 9px;
  font-weight: 850;
}

.coffee-hold-board .coffee-account-card h3 {
  margin: 3px 0 0;
  font-size: 17px;
  letter-spacing: -.02em;
}

.coffee-hold-board .coffee-account-card > p {
  margin: 0;
  color: var(--cb-muted);
  font-size: 10px;
}

.coffee-hold-board .coffee-account-lines {
  display: grid;
  gap: 5px;
  margin: 5px 0 0;
  padding: 10px;
  border-radius: 11px;
  background: var(--cb-soft);
}

.coffee-hold-board .coffee-account-lines span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #56645b;
  font-size: 10px;
}

.coffee-hold-board .coffee-account-total {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin: auto 0 0;
  padding-top: 7px;
  background: transparent;
}

.coffee-hold-board .coffee-account-total span {
  color: var(--cb-muted);
  font-size: 10px;
}

.coffee-hold-board .coffee-account-total strong {
  color: var(--cb-green-800);
  font-size: 18px;
}

.coffee-hold-board .coffee-account-card > button {
  min-height: 40px;
  margin-top: 4px;
  border-radius: 11px;
  background: linear-gradient(145deg, var(--cb-green-600), var(--cb-green-800));
  font-size: 11px;
  font-weight: 850;
}

/* Responsive */

@media (max-width: 1250px) {
  .coffee-pos .retail-product-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .coffee-hold-board .coffee-account-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 980px) {
  .coffee-pos__layout {
    grid-template-columns: 1fr;
  }

  .coffee-pos__cart {
    position: static;
    max-height: none;
    order: initial;
  }

  .coffee-hold-board .coffee-account-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 720px) {
  .coffee-pos {
    padding: 14px;
  }

  .coffee-pos__header {
    align-items: flex-start;
    flex-direction: column;
    padding: 16px;
  }

  .coffee-pos__tabs {
    width: 100%;
    overflow-x: auto;
  }

  .coffee-pos__tabs button {
    flex: 1 0 auto;
  }

  .coffee-pos .retail-product-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .coffee-hold-board .coffee-account-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 460px) {
  .coffee-pos .retail-product-grid {
    grid-template-columns: 1fr;
  }

  .coffee-pos .retail-product-card {
    min-height: 155px;
  }
}
/* =========================================================
   ALIMENTOS Y BEBIDAS POS V2 — LEGIBILIDAD
   ========================================================= */

/* Nombre del artículo */
.coffee-pos .retail-product-card strong {
  font-size: 17px;
  line-height: 1.3;
  font-weight: 800;
}

/* Categoría del artículo */
.coffee-pos .retail-product-card span {
  font-size: 13px;
  line-height: 1.3;
}

/* Stock */
.coffee-pos .retail-product-card small {
  font-size: 12px;
  line-height: 1.3;
}

/* Precio */
.coffee-pos .retail-product-card b {
  font-size: 19px;
  font-weight: 900;
}

/* Etiquetas del carrito: Cliente, Mesa, Caja, Método, etc. */
.coffee-pos__cart > label {
  font-size: 13px;
  line-height: 1.3;
}

/* Inputs y selects */
.coffee-pos__cart input,
.coffee-pos__cart select {
  font-size: 14px;
}

/* Nombre del producto dentro del carrito */
.coffee-pos .retail-cart__item > div:first-child strong {
  font-size: 14px;
}

/* Precio unitario dentro del carrito */
.coffee-pos .retail-cart__item > div:first-child span {
  font-size: 12px;
}

/* Total de la línea */
.coffee-pos .retail-cart__item > strong {
  font-size: 13px;
}

/* Cantidad */
.coffee-pos .quantity-control strong {
  font-size: 14px;
}

/* Textos de resumen */
.coffee-pos .selected-account-summary span,
.coffee-pos .retail-cart__total span {
  font-size: 13px;
}

/* HOLD: referencia */
.coffee-hold-board .coffee-account-card > div:first-child > strong {
  font-size: 12px;
}

/* HOLD: estado */
.coffee-hold-board .coffee-status {
  font-size: 11px;
}

/* HOLD: cliente */
.coffee-hold-board .coffee-account-card h3 {
  font-size: 19px;
}

/* HOLD: detalles */
.coffee-hold-board .coffee-account-card > p,
.coffee-hold-board .coffee-account-lines span,
.coffee-hold-board .coffee-account-total span {
  font-size: 13px;
}

/* =========================================================
   ALIMENTOS Y BEBIDAS POS V2 — CATEGORÍAS MÁS LEGIBLES
   ========================================================= */

.coffee-pos__catalog .operations-filter {
  min-height: 42px;
  padding: 0 18px;

  font-size: 14px;
  font-weight: 800;
  line-height: 1.2;
}

/* Categoría seleccionada */
.coffee-pos__catalog .operations-filter--active {
  font-size: 14px;
  font-weight: 900;
}

/* =========================================================
   ALIMENTOS Y BEBIDAS POS V2 — ARTÍCULOS SELECCIONADOS
   ========================================================= */

/* Tarjeta de cada artículo seleccionado */
.coffee-pos .retail-cart__item {
  padding: 14px;
  gap: 10px;
}

/* Nombre del artículo */
.coffee-pos .retail-cart__item > div:first-child strong {
  font-size: 16px;
  font-weight: 850;
  line-height: 1.3;

  /* Permitir nombres largos */
  white-space: normal;
  overflow: visible;
  text-overflow: unset;
}

/* Precio unitario */
.coffee-pos .retail-cart__item > div:first-child span {
  font-size: 13px;
  font-weight: 600;
}

/* Subtotal del artículo */
.coffee-pos .retail-cart__item > strong {
  font-size: 15px;
  font-weight: 900;
}

/* Cantidad seleccionada */
.coffee-pos .quantity-control strong {
  font-size: 16px;
  font-weight: 900;
}

/* Botones - y + */
.coffee-pos .quantity-control button {
  width: 36px;
  min-height: 36px;
}

/* Control completo de cantidad */
.coffee-pos .quantity-control {
  grid-template-columns: 36px 1fr 36px;
  gap: 8px;
}

/* =========================================================
   ALIMENTOS Y BEBIDAS — ÓRDENES RETENIDAS — ACCIONES
   ========================================================= */

.coffee-hold-board .coffee-account-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-top: 6px;
}

.coffee-hold-board .coffee-account-actions button {
  min-width: 0;
  min-height: 42px;

  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;

  padding: 7px 10px;
  border-radius: 11px;

  font-size: 12px;
  font-weight: 850;
}

.coffee-hold-board
.coffee-account-actions
.secondary-button {
  border: 1px solid #dfe7e2;
  background: #ffffff;
  color: #187047;
}

@media (max-width: 520px) {
  .coffee-hold-board .coffee-account-actions {
    grid-template-columns: 1fr;
  }
}

