/* =========================================================
   INVENTORY KARDEX V2
   ========================================================= */

.inventory-kardex-v2 {
  min-height: 100vh;
  padding: 24px;
  background: #f2f5f3;
}

.inventory-kardex-v2__header,
.inventory-kardex-v2__summary,
.inventory-kardex-v2__layout,
.inventory-kardex-v2__error,
.inventory-kardex-v2__success {
  width: min(1480px, 100%);
  margin-left: auto;
  margin-right: auto;
}

.inventory-kardex-v2__header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 20px;

  margin-bottom: 16px;
  padding: 20px 22px;

  border-radius: 22px;
  background: #fff;

  box-shadow:
    0 18px 46px
    rgba(12, 44, 29, .06);
}

.inventory-kardex-v2__back {
  padding: 0;

  display: inline-flex;
  align-items: center;
  gap: 7px;

  background: transparent;
  color: #187047;
}

.inventory-kardex-v2__eyebrow {
  display: block;

  margin-top: 8px;

  color: #187047;

  font-size: .78rem;
  font-weight: 900;
  letter-spacing: .12em;
}

.inventory-kardex-v2__header h1 {
  margin: 5px 0;

  font-size:
    clamp(30px, 3vw, 44px);
}

.inventory-kardex-v2__summary {
  display: grid;

  grid-template-columns:
    repeat(
      4,
      minmax(0, 1fr)
    );

  gap: 12px;

  margin-bottom: 16px;
}

.inventory-kardex-v2__summary article {
  min-height: 115px;

  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 5px;

  padding: 16px;

  border: 1px solid #dfe7e2;
  border-radius: 18px;

  background: #fff;
}

.inventory-kardex-v2__summary strong {
  font-size: 1.55rem;
}

.inventory-kardex-v2__layout {
  display: grid;

  grid-template-columns:
    350px minmax(0, 1fr);

  gap: 16px;

  align-items: start;
}

.inventory-kardex-v2__movement-form,
.inventory-kardex-v2__history {
  padding: 18px;

  border: 1px solid #dfe7e2;
  border-radius: 22px;

  background: #fff;
}

.inventory-kardex-v2__movement-form {
  position: sticky;
  top: 16px;
}

.inventory-kardex-v2__movement-form form {
  display: grid;
  gap: 12px;

  margin-top: 16px;
}

.inventory-kardex-v2__movement-form label {
  display: grid;
  gap: 6px;

  font-size: .95rem;
  font-weight: 800;
}

.inventory-kardex-v2__movement-form input,
.inventory-kardex-v2__movement-form select,
.inventory-kardex-v2__movement-form textarea {
  width: 100%;
  min-height: 44px;

  padding: 0 11px;

  border: 1px solid #dfe7e2;
  border-radius: 11px;

  font: inherit;
}

.inventory-kardex-v2__movement-form textarea {
  padding-top: 10px;
}

.inventory-kardex-v2__movement-form button {
  min-height: 44px;

  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
}

.inventory-kardex-v2__history-header {
  display: flex;

  justify-content:
    space-between;

  align-items: flex-end;

  gap: 16px;

  margin-bottom: 14px;
}

.inventory-kardex-v2__search {
  min-width: 320px;

  display: flex;
  align-items: center;
  gap: 8px;

  padding: 0 12px;

  border: 1px solid #dfe7e2;
  border-radius: 12px;

  background: #f7f9f8;
}

.inventory-kardex-v2__search input {
  border: 0;
  background: transparent;
  box-shadow: none;
}

.inventory-kardex-v2__table-wrap {
  width: 100%;
  overflow-x: auto;
}

.inventory-kardex-v2__table {
  width: 100%;
  border-collapse: collapse;
}

.inventory-kardex-v2__table th,
.inventory-kardex-v2__table td {
  padding: 13px 10px;

  border-bottom:
    1px solid #e9eeeb;

  text-align: left;
}

.inventory-kardex-v2__table th {
  color: #758078;
  font-size: .85rem;
}

.inventory-kardex-v2__table td {
  font-size: .94rem;
}

.inventory-kardex-v2__table td small {
  display: block;

  margin-top: 3px;

  color: #758078;
}

