  background: #faeaea;
  color: #923f3d;
}

.inventory-kardex-v2__success {
  background: #e8f5ec;
  color: #1f6b42;
}

.inventory-kardex-v2__empty {
  padding: 24px;

  color: #758078;

  text-align: center;
}

