/* =========================================================
   KDS PHASE 2D — LIVE OPERATIONS
   Append after the existing KDS styles
   ========================================================= */

.kds-summary {
  max-width: 1680px;
  margin: 0 auto 14px;
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  color: #66736c;
  font-size: 1.5rem;
}

.kds-summary span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.kds-new-ticket-alert {
  max-width: 1680px;
  margin: 0 auto 14px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 11px 14px;
  border: 1px solid rgba(23, 114, 70, 0.24);
  border-radius: 12px;
  background: rgba(23, 114, 70, 0.08);
  color: #177246;
}

.kds-ticket__timing {
  display: grid;
  justify-items: end;
  gap: 5px;
}

.kds-ticket__urgency {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  width: fit-content;
  padding: 3px 7px;
  border-radius: 999px;
  font-size: 0.7rem;
  font-weight: 900;
  line-height: 1;
}

.kds-ticket__urgency--attention {
  background: #fff4d6;
  color: #8a5a00;
}

.kds-ticket__urgency--urgent {
  background: #fde8e8;
  color: #a12424;
}

.kds-ticket--attention {
  border-color: #e9c66b;
  box-shadow: 0 0 0 1px rgba(201, 144, 24, 0.08);
}

.kds-ticket--urgent {
  border-color: #d86c6c;
  box-shadow: 0 0 0 1px rgba(172, 42, 42, 0.08);
}

.kds-ticket--new {
  animation: kds-new-ticket-pulse 1s ease-in-out 3;
}

@keyframes kds-new-ticket-pulse {
  0%,
  100% {
    transform: translateY(0);
    box-shadow: 0 0 0 0 rgba(23, 114, 70, 0);
  }

  50% {
    transform: translateY(-2px);
    box-shadow: 0 0 0 4px rgba(23, 114, 70, 0.12);
  }
}

@media (prefers-reduced-motion: reduce) {
  .kds-ticket--new {
    animation: none;
  }
}

@media (max-width: 680px) {
  .kds-summary {
    align-items: flex-start;
    flex-direction: column;
    gap: 5px;
  }

  .kds-ticket__timing {
    justify-items: start;
  }

  .kds-ticket__top {
    align-items: flex-start;
    flex-direction: column;
  }
}

