.pos-weight-modal-backdrop {
  position: fixed; inset: 0; z-index: 1000; display: grid;
  place-items: center; padding: 20px;
  background: rgba(15, 23, 42, 0.58); backdrop-filter: blur(3px);
}
.pos-weight-modal {
  width: min(100%, 520px); padding: 22px; border-radius: 18px;
  background: #fff; box-shadow: 0 24px 70px rgba(15, 23, 42, 0.24);
}
.pos-weight-modal__header {
  display: flex; align-items: flex-start; justify-content: space-between; gap: 16px;
}
.pos-weight-modal__header span {
  display: block; margin-bottom: 4px; font-size: .72rem;
  font-weight: 900; letter-spacing: .08em;
}
.pos-weight-modal__header h2 { margin: 0; }
.pos-weight-modal__facts {
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px; margin-top: 20px;
}
.pos-weight-modal__facts > div {
  display: grid; gap: 4px; padding: 12px;
  border: 1px solid rgba(15, 23, 42, .09); border-radius: 12px;
}
.pos-weight-modal__facts span,
.pos-weight-modal__subtotal span { font-size: .78rem; color: #64748b; }
.pos-weight-modal__input {
  display: grid; gap: 8px; margin-top: 20px; font-weight: 800;
}
.pos-weight-modal__input > div {
  display: grid; grid-template-columns: 1fr auto; align-items: center;
  overflow: hidden; border: 2px solid rgba(15, 23, 42, .14);
  border-radius: 14px;
}
.pos-weight-modal__input input {
  min-width: 0; padding: 15px 16px; border: 0; outline: 0;
  font-size: 1.65rem; font-weight: 900;
}
.pos-weight-modal__input > div > span { padding: 0 16px; font-weight: 900; }
.pos-weight-modal__subtotal {
  display: flex; align-items: center; justify-content: space-between;
  gap: 16px; margin-top: 16px; padding: 15px 16px;
  border-radius: 14px; background: rgba(15, 23, 42, .05);
}
.pos-weight-modal__subtotal strong { font-size: 1.35rem; }
.pos-weight-modal__confirm { width: 100%; min-height: 48px; margin-top: 16px; }
.pos-weight-modal__hint {
  display: block; margin-top: 9px; text-align: center; color: #64748b;
}
.quantity-control button:disabled { opacity: .4; cursor: not-allowed; }
@media (max-width: 560px) {
