  width: 100%;
  max-width: 1600px;
  margin: 0 auto;
}

/* Preparación mantiene ancho completo */
.products-admin-v2__preparation,
.products-admin-v2__stations,
.products-admin-v2__preparation-section {
  width: 100%;
}

/* Editor de producto más ancho + catálogo equilibrado */
.products-admin-v2__layout {
  display: grid;
  grid-template-columns:
    minmax(520px, 0.95fr)
    minmax(0, 1.25fr);
  gap: 20px;
  align-items: start;
}

/* Evita que la columna izquierda se comprima */
.products-admin-v2__editor {
  min-width: 0;
  width: 100%;
}

/* Catálogo flexible */
.products-admin-v2__catalog {
  min-width: 0;
  width: 100%;
}

