  grid-column: 1 / -1;
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px !important;
  min-height: 68px;
  padding: 12px 14px;
  border: 1px solid #dfe6e1;
  border-radius: 14px;
  background: #f8faf9;
  cursor: pointer;
