  line-height: 1.35;
}

.customers-page__switch input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.customers-page__switch-control {
  position: relative;
  width: 46px;
  height: 26px;
  border-radius: 999px;
  background: #cbd5ce;
  transition: background .18s ease;
}

.customers-page__switch-control::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: white;
  box-shadow: 0 1px 4px rgba(0, 0, 0, .16);
  transition: transform .18s ease;
}

.customers-page__switch input:checked + .customers-page__switch-control {
  background: #2f7b50;
}

.customers-page__switch input:checked + .customers-page__switch-control::after {
  transform: translateX(20px);
}

