  box-shadow:
    0 22px 65px rgba(28, 45, 34, 0.13),
    0 4px 16px rgba(28, 45, 34, 0.06);
}

/* ---------------------------------------------------------
   BRAND / LOGO
   --------------------------------------------------------- */

.login-brand-panel {
  display: grid;
  place-items: center;
  gap: 12px;

  margin: 0 !important;
  padding: 28px 30px 24px;

  background:
    radial-gradient(
      circle at 50% 0%,
      rgba(122, 255, 0, 0.08),
      transparent 48%
    ),
    #050505;

  border-radius: 0;
}

.login-brand-logo {
  display: block;
  width: min(100%, 310px);
  height: auto;
  object-fit: contain;
}

.login-brand-caption {
  display: grid;
  gap: 5px;
  text-align: center;
}

.login-brand-caption span {
  color: #d9f4dd;
  font-size: 0.74rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.login-brand-caption small {
  max-width: 340px;
  color: rgba(255, 255, 255, 0.62);
  font-size: 0.76rem;
  line-height: 1.45;
}

/* ---------------------------------------------------------
   CONTENIDO PRINCIPAL
   --------------------------------------------------------- */

.login-content {
  display: grid;
  gap: 24px;

  padding: 30px 32px 28px;

  background: #ffffff !important;
}

/* ---------------------------------------------------------
   CABECERA
   --------------------------------------------------------- */

.login-heading {
  display: grid;
  gap: 14px;
}

.login-heading > div {
  min-width: 0;
}

.login-heading .eyebrow {
  margin: 0 0 6px;
  color: #4ba66a;
  font-size: 0.76rem;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.login-heading h1 {
  margin: 0;
  color: #1f2d25;
  font-size: 2rem;
  line-height: 1.05;
}

.login-heading .muted {
  max-width: 100%;
  margin: 8px 0 0;

  color: #728078;
  font-size: 0.9rem;
  line-height: 1.5;
}

.login-status {
  justify-self: start;

  display: inline-flex;
  align-items: center;
  gap: 7px;

  min-height: 28px;
  padding: 5px 10px;

  border: 1px solid #d9eadf;
  border-radius: 999px;

  background: #edf7f0;
  color: #2a7548;

  font-size: 0.72rem;
  font-weight: 900;
  white-space: nowrap;
}

.login-status::before {
  content: '';
  width: 7px;
  height: 7px;

  border-radius: 50%;
  background: currentColor;

  box-shadow:
    0 0 0 3px rgba(42, 117, 72, 0.10);
}

/* ---------------------------------------------------------
   FORMULARIO
   --------------------------------------------------------- */

.login-form {
  display: grid;
  gap: 18px;
}

.login-field {
  display: grid;
  gap: 8px;

  margin: 0;

  color: #33463a;
  font-size: 0.8rem;
  font-weight: 800;
}

.login-field > span {
  display: block;
  line-height: 1.2;
}

.login-input-wrap {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;

  min-height: 50px;
  padding: 0 14px;

  border: 1px solid #dce5df;
  border-radius: 12px;

  background: #fbfcfb;
  color: #6f7d74;

  transition:
    border-color 0.16s ease,
    box-shadow 0.16s ease,
    background 0.16s ease;
}

.login-input-wrap:focus-within {
  border-color: #4f8a64;
  background: #ffffff;
  box-shadow:
    0 0 0 3px rgba(54, 128, 79, 0.10);
}

.login-input-wrap input {
  width: 100%;
  min-width: 0;

  margin: 0;
  padding: 13px 0;

  border: 0;
  outline: 0;

  background: transparent;
  color: #223129;

  font: inherit;
  font-size: 0.9rem;
}

.login-input-wrap input::placeholder {
  color: #9aa59e;
}

.login-password-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  width: 32px;
  height: 32px;
  padding: 0;

  border: 0;
  border-radius: 8px;

  background: transparent;
  color: #6d7b72;

  cursor: pointer;
}

.login-password-toggle:hover {
  background: #edf2ef;
  color: #2e6f48;
}

.login-error {
  margin: 0;
  padding: 11px 12px;

  border: 1px solid #e8c1bf;
  border-radius: 10px;

  background: #fff5f4;
  color: #a33f3c;

  font-size: 0.8rem;
  font-weight: 800;
  line-height: 1.4;
}

.login-submit {
  width: 100%;
  min-height: 50px;
  margin-top: 2px;

  border: 0;
  border-radius: 12px;

  background:
    linear-gradient(
      180deg,
      #347c50 0%,
      #286841 100%
    );

  color: #ffffff;

  font-size: 0.9rem;
  font-weight: 900;
  letter-spacing: 0.01em;

  box-shadow:
    0 8px 18px rgba(40, 104, 65, 0.18);

  cursor: pointer;

  transition:
    transform 0.15s ease,
    box-shadow 0.15s ease,
    opacity 0.15s ease;
}

.login-submit:hover:not(:disabled) {
  transform: translateY(-1px);

  box-shadow:
    0 10px 22px rgba(40, 104, 65, 0.24);
}

.login-submit:active:not(:disabled) {
  transform: translateY(0);
}

.login-submit:disabled {
  opacity: 0.65;
  cursor: not-allowed;
}

/* ---------------------------------------------------------
   PIE
   --------------------------------------------------------- */

.login-footer {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: start;
  gap: 16px;

  margin-top: 2px;
  padding-top: 18px;

  border-top: 1px solid #edf1ee;
}

.login-footer span {
  color: #2f6745;
  font-size: 0.74rem;
  font-weight: 900;
  line-height: 1.35;
}

.login-footer small {
  color: #7b877f;
  font-size: 0.72rem;
  line-height: 1.45;
  text-align: right;
}

/* ---------------------------------------------------------
   RESPONSIVE
   --------------------------------------------------------- */

@media (max-width: 560px) {
  .auth-shell--modern {
    padding: 14px;
  }

  .login-card--modern {
    border-radius: 18px;
  }

  .login-brand-panel {
    padding: 22px 20px 20px;
  }

  .login-brand-logo {
    width: min(100%, 280px);
  }

  .login-content {
    gap: 22px;
    padding: 24px 22px 22px;
  }

  .login-heading h1 {
    font-size: 1.75rem;
  }

  .login-footer {
    grid-template-columns: 1fr;
    gap: 6px;
  }

  .login-footer small {
    text-align: left;
  }
}

/* 2L-F5U1 — USUARIOS Y ACCESOS */

.users-admin-page {
  max-width: 1440px;
  margin: 0 auto;
}

.users-admin-page__toolbar,
.users-admin-page__pagination,
.users-admin-page__detail-heading,
.users-admin-page__status-actions,
.users-admin-page__password-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.users-admin-page__search {
  width: min(100%, 430px);
}

.users-admin-page__table-wrap {
  overflow-x: auto;
  border: 1px solid #e0e7e2;
  border-radius: 14px;
}

.users-admin-page__table {
  width: 100%;
  min-width: 900px;
  border-collapse: collapse;
}

.users-admin-page__table th,
.users-admin-page__table td {
  padding: 12px 14px;
  border-bottom: 1px solid #e7ece8;
  text-align: left;
  vertical-align: middle;
}

.users-admin-page__table th {
  background: #f3f6f4;
  color: #66736b;
  font-size: .72rem;
  font-weight: 900;
  text-transform: uppercase;
}

.users-admin-page__table td:first-child {
  display: grid;
  gap: 3px;
}

.users-admin-page__table td small {
  color: #7a867e;
}

.users-admin-page__roles {
  display: flex;
  gap: 5px;
  flex-wrap: wrap;
}

.users-admin-page__roles span,
.users-admin-page__status {
  display: inline-flex;
  padding: 4px 8px;
  border-radius: 999px;
  font-size: .7rem;
  font-weight: 900;
}

.users-admin-page__roles span {
  background: #edf2f8;
  color: #526579;
}

.users-admin-page__status--active {
  background: #e7f5eb;
  color: #247448;
}

.users-admin-page__status--inactive {
  background: #eef1ef;
  color: #68736c;
}

.users-admin-page__status--locked {
  background: #fae8e7;
  color: #a3423f;
}

.users-admin-page__icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  padding: 0;
  border: 1px solid #dfe6e1;
  border-radius: 9px;
  background: white;
  color: #53635a;
}

.users-admin-page__form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.users-admin-page__form label {
  display: grid;
  gap: 6px;
  font-weight: 800;
}

.users-admin-page__form fieldset,
.users-admin-page__security-block {
  grid-column: 1 / -1;
  display: grid;
  gap: 12px;
  margin: 0;
  padding: 14px;
  border: 1px solid #e0e7e2;
  border-radius: 14px;
}

.users-admin-page__role-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.users-admin-page__role-option {
  display: flex !important;
  align-items: flex-start;
  gap: 9px !important;
  padding: 10px;
  border: 1px solid #e1e7e3;
  border-radius: 10px;
  background: #fafcfb;
}

.users-admin-page__role-option span {
  display: grid;
  gap: 2px;
}

.users-admin-page__role-option small {
  color: #79857e;
  font-size: .7rem;
}

.users-admin-page__detail {
  display: grid;
  gap: 16px;
}

.users-admin-page__detail-heading {
  align-items: flex-start;
}

.users-admin-page__security-block h3 {
  margin: 0;
}

.users-admin-page__password-row input {
  flex: 1;
  min-width: 240px;
}

.users-admin-page__notice {
  padding: 10px 12px;
  border: 1px solid #cfe4d6;
  border-radius: 10px;
  background: #eef8f1;
  color: #247448;
  font-weight: 800;
}

@media (max-width: 900px) {
  .users-admin-page__role-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 600px) {
  .users-admin-page__form,
  .users-admin-page__role-grid {
    grid-template-columns: 1fr;
  }

  .users-admin-page__password-row {
    display: grid;
  }
}


/* =========================================================
   MAINTENANCE UX SYSTEM
   Agregar al FINAL del CSS global compartido.
   ========================================================= */

.maintenance-page {
  --maintenance-primary: #15803d;
  --maintenance-primary-dark: #166534;
  --maintenance-primary-soft: #f0fdf4;
  --maintenance-border: #e3e8e5;
  --maintenance-border-strong: #cfd7d2;
  --maintenance-text: #18231d;
  --maintenance-muted: #6f7c75;
  --maintenance-surface: #ffffff;

  min-height: 100vh;
  padding: 28px;
  background: #f5f7f5;
  color: var(--maintenance-text);
}

.maintenance-header {
  max-width: 1180px;
  margin: 0 auto 20px;
}

.maintenance-header h1 {
  margin: 6px 0 4px;
  font-size: clamp(1.65rem, 2.5vw, 2.05rem);
  letter-spacing: -0.04em;
}

.maintenance-header p {
  font-size: 0.82rem;
  line-height: 1.45;
}

.maintenance-card {
  max-width: 1180px;
  gap: 16px;
  border-radius: 16px;
  padding: 18px;
  box-shadow:
    0 1px 2px rgb(15 23 42 / 3%),
    0 10px 28px rgb(15 23 42 / 4%);
}

.maintenance-alert {
  max-width: 1180px;
  margin: 0 auto 12px;
  border-radius: 10px;
  padding: 10px 12px;
  font-size: 0.76rem;
  font-weight: 700;
}

.maintenance-alert--error {
  border: 1px solid #fecaca;
  color: #b91c1c;
  background: #fef2f2;
}

.maintenance-alert--success {
  border: 1px solid #bbf7d0;
  color: #166534;
  background: #f0fdf4;
}

.maintenance-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
}

.maintenance-toolbar__heading {
  display: flex;
  align-items: flex-end;
  gap: 10px;
}

.maintenance-toolbar__heading h2 {
  margin: 4px 0 0;
  font-size: 1.02rem;
}

.maintenance-count {
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  margin-bottom: 1px;
  border-radius: 999px;
  padding: 2px 8px;
  color: #59675f;
  background: #f0f3f1;
  font-size: 0.66rem;
  font-weight: 700;
  white-space: nowrap;
}

.maintenance-toolbar__actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}

.maintenance-search {
  display: flex;
  align-items: center;
  gap: 8px;
}

.maintenance-search input {
  width: 270px;
  min-height: 36px;
  height: 36px;
  border: 1px solid var(--maintenance-border);
  border-radius: 9px;
  padding: 0 11px;
  background: #fff;
  font-size: 0.76rem;
}

.maintenance-search input:focus {
  outline: none;
  border-color: var(--maintenance-primary);
  box-shadow: 0 0 0 3px rgb(21 128 61 / 10%);
}

.maintenance-search button,
.maintenance-toolbar__actions > button,
.maintenance-pagination button,
.maintenance-modal button {
  min-height: 34px;
  border-radius: 9px;
  padding: 7px 12px;
  font-size: 0.72rem;
}

.maintenance-table-wrap {
  overflow-x: auto;
  border: 1px solid var(--maintenance-border);
  border-radius: 12px;
  background: #fff;
}

.maintenance-table {
  width: 100%;
  border-collapse: collapse;
  background: #fff;
}

.maintenance-table th {
  height: 38px;
  padding: 0 12px;
  border-bottom: 1px solid var(--maintenance-border);
  color: #6d7972;
  background: #f7f9f8;
  font-size: 0.66rem;
  font-weight: 800;
  text-align: left;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  white-space: nowrap;
}

.maintenance-table td {
  height: 56px;
  padding: 9px 12px;
  border-bottom: 1px solid #edf1ee;
  color: #39473f;
  font-size: 0.76rem;
  vertical-align: middle;
}

.maintenance-table tbody tr:last-child td {
  border-bottom: 0;
}

.maintenance-table tbody tr:hover {
  background: #fafcfb;
}

.maintenance-table td strong {
  display: block;
  color: var(--maintenance-text);
  font-size: 0.77rem;
}

.maintenance-table td small {
  display: block;
  margin-top: 3px;
  color: var(--maintenance-muted);
  font-size: 0.67rem;
}

.maintenance-badge {
  display: inline-flex;
  align-items: center;
  min-height: 23px;
  border-radius: 999px;
  padding: 2px 8px;
  font-size: 0.65rem;
  font-weight: 700;
  white-space: nowrap;
}

.maintenance-badge--success {
  color: #16733a;
  background: #eaf8ef;
}

.maintenance-badge--neutral {
  color: #456050;
  background: #eef3ef;
}

.maintenance-badge--muted {
  color: #667085;
  background: #f1f3f2;
}

.maintenance-badge--danger {
  color: #b42318;
  background: #fef0ef;
}

.maintenance-row-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
}

.maintenance-icon-button {
  display: inline-grid !important;
  place-items: center;
  width: 32px;
  min-height: 32px !important;
  height: 32px;
  border: 1px solid var(--maintenance-border) !important;
  border-radius: 9px !important;
  padding: 0 !important;
  color: #53615a !important;
  background: #fff !important;
}

.maintenance-icon-button:hover {
  border-color: #add7b9 !important;
  color: var(--maintenance-primary) !important;
  background: var(--maintenance-primary-soft) !important;
}

.maintenance-icon-button svg {
  width: 16px;
  height: 16px;
}

.maintenance-pagination {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 10px;
  margin-top: 2px;
}

.maintenance-pagination > button:first-child {
  justify-self: start;
}

.maintenance-pagination > button:last-child {
  justify-self: end;
}

.maintenance-pagination span {
  color: var(--maintenance-muted);
  font-size: 0.7rem;
}

/* Modal */

.maintenance-modal-backdrop {
  position: fixed;
  z-index: 1000;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgb(15 23 42 / 16%);
}

.maintenance-modal {
  display: flex;
  flex-direction: column;
  width: min(100%, 660px);
  max-height: min(84vh, 760px);
  overflow: hidden;
  border: 1px solid var(--maintenance-border);
  border-radius: 16px;
  background: var(--maintenance-surface);
  box-shadow:
    0 24px 60px rgb(15 23 42 / 16%),
    0 8px 24px rgb(15 23 42 / 8%);
}

.maintenance-modal--wide {
  width: min(100%, 860px);
}

.maintenance-modal__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 20px;
  border-bottom: 1px solid var(--maintenance-border);
}

.maintenance-modal__header h2 {
  margin: 4px 0 0;
  font-size: 1.08rem;
  letter-spacing: -0.025em;
}

.maintenance-modal__header p:last-child {
  margin: 4px 0 0;
  color: var(--maintenance-muted);
  font-size: 0.72rem;
}

.maintenance-modal__close {
  width: 30px;
  min-height: 30px !important;
  border-color: transparent !important;
  padding: 0 !important;
  color: var(--maintenance-muted) !important;
  background: transparent !important;
  font-size: 1.3rem !important;
  font-weight: 400 !important;
}

.maintenance-modal__close:hover:not(:disabled) {
  border-color: var(--maintenance-border) !important;
  color: var(--maintenance-text) !important;
  background: #f5f7f6 !important;
}

.maintenance-modal__form {
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
}

.maintenance-modal__body {
  display: grid;
  gap: 16px;
  overflow-y: auto;
  padding: 18px 20px;
}

.maintenance-modal__footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 12px 20px;
  border-top: 1px solid var(--maintenance-border);
  background: #fafbfa;
}

/* Forms */

.maintenance-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px 14px;
}

.maintenance-form-grid label,
.maintenance-inline-fields label {
  display: grid;
  gap: 5px;
  color: #45534b;
  font-size: 0.7rem;
  font-weight: 700;
}

.maintenance-form-grid input,
.maintenance-form-grid select,
.maintenance-inline-fields input,
.maintenance-inline-fields select {
  min-height: 36px;
  height: 36px;
  border: 1px solid var(--maintenance-border);
  border-radius: 9px;
  padding: 0 10px;
  background: #fff;
  font-size: 0.76rem;
}

.maintenance-form-grid input:focus,
.maintenance-form-grid select:focus,
.maintenance-inline-fields input:focus,
.maintenance-inline-fields select:focus {
  outline: none;
  border-color: var(--maintenance-primary);
  box-shadow: 0 0 0 3px rgb(21 128 61 / 10%);
}

.maintenance-switch {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  border: 1px solid var(--maintenance-border);
  border-radius: 11px;
  padding: 11px 12px;
  background: #fafcfb;
  cursor: pointer;
}

.maintenance-switch > span {
  display: grid;
  gap: 2px;
}

.maintenance-switch strong {
  font-size: 0.72rem;
}

.maintenance-switch small {
  color: var(--maintenance-muted);
  font-size: 0.66rem;
}

.maintenance-switch input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.maintenance-switch i {
  position: relative;
  flex: 0 0 auto;
  width: 36px;
  height: 20px;
  border-radius: 999px;
  background: #d8dedb;
  transition: background-color 140ms ease;
}

.maintenance-switch i::after {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 3px rgb(15 23 42 / 18%);
  content: "";
  transition: transform 140ms ease;
}

.maintenance-switch:has(input:checked) i {
  background: var(--maintenance-primary);
}

.maintenance-switch:has(input:checked) i::after {
  transform: translateX(16px);
}

.maintenance-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.maintenance-summary-grid article {
  display: grid;
  gap: 4px;
  border: 1px solid var(--maintenance-border);
  border-radius: 10px;
  padding: 10px;
  background: #fafcfb;
}

.maintenance-summary-grid span {
  color: var(--maintenance-muted);
  font-size: 0.65rem;
}

.maintenance-summary-grid strong {
  font-size: 0.76rem;
}

.maintenance-section {
  display: grid;
  gap: 12px;
  border-top: 1px solid var(--maintenance-border);
  padding-top: 16px;
}

.maintenance-section h3 {
  margin: 0;
  font-size: 0.86rem;
