   ========================================================= */

.business-config-layout {
  width: 100%;
  max-width: 1180px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  align-items: start;
}

.business-config-card {
  width: 100%;
  min-width: 0;
  max-width: none !important;
  margin: 0 !important;
  align-self: start;
}

/* Alcance y finanzas ocupan todo el ancho */
.business-config-card:first-child,
.business-config-card:last-child {
  grid-column: 1 / -1;
}

