.business-config-card:nth-child(2) {
  grid-column: 1;
}

.business-config-card:nth-child(3) {
  grid-column: 2;
}

/* Capacidades POS a todo el ancho para aprovechar mejor el espacio */
.business-config-card:nth-child(4) {
  grid-column: 1 / -1;
}

.business-config-card > div:first-child h2 {
  margin: 2px 0 0;
  font-size: 0.96rem;
}

/* Alcance */
.business-config-point {
  display: grid;
  grid-template-columns: 150px minmax(0, 360px);
  align-items: center;
  gap: 10px;
  max-width: 540px;
  color: #45534b;
  font-size: 0.7rem;
  font-weight: 700;
}

.business-config-point select {
  width: 100%;
  min-height: 36px;
  border: 1px solid var(--maintenance-border);
  border-radius: 9px;
  padding: 0 10px;
  color: var(--maintenance-text);
  background: #fff;
  font-size: 0.74rem;
}

/* Módulos Empresa / Sucursal */
.business-config-card:nth-child(2) .settings-actions,
.business-config-card:nth-child(3) .settings-actions {
  display: grid;
  grid-template-columns: 1fr;
  gap: 8px;
}

/* Capacidades POS en 3 columnas */
.business-config-card:nth-child(4) .settings-actions {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.business-config-card .settings-toggle {
  width: 100%;
  min-height: 68px;
  display: grid;
  grid-template-columns: 26px minmax(0, 1fr) auto;
  align-items: center;
  gap: 9px;
  padding: 9px 11px;
  border-radius: 11px;
  text-align: left;
}

.business-config-card .settings-toggle > span {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.business-config-card .settings-toggle strong {
  font-size: 0.72rem;
}

.business-config-card .settings-toggle small {
  color: #758179;
  font-size: 0.62rem;
  font-weight: 500;
  line-height: 1.32;
}

.business-config-card .settings-toggle b {
  min-width: 34px;
  border-radius: 999px;
  padding: 4px 7px;
  color: #68746d;
  background: #eef2ef;
  font-size: 0.58rem;
  text-align: center;
}

.business-config-card .settings-toggle--active b {
  color: #17613c;
  background: #dcf3e5;
}

/* Financiero */
.business-config-card.settings-financial {
  gap: 14px;
}

.business-config-card .settings-financial__grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.business-config-card .settings-financial__modes {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.business-config-card .settings-financial__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  border-top: 1px solid var(--maintenance-border);
  padding-top: 12px;
}

/* Tablet */
@media (max-width: 980px) {
  .business-config-layout {
    grid-template-columns: 1fr;
  }

  .business-config-card:first-child,
  .business-config-card:nth-child(2),
  .business-config-card:nth-child(3),
  .business-config-card:nth-child(4),
  .business-config-card:last-child {
    grid-column: 1;
  }

  .business-config-card:nth-child(4) .settings-actions {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

/* Mobile */
@media (max-width: 640px) {
  .business-config-point {
    grid-template-columns: 1fr;
  }

  .business-config-card:nth-child(4) .settings-actions,
  .business-config-card .settings-financial__grid,
  .business-config-card .settings-financial__modes {
    grid-template-columns: 1fr;
  }

  .business-config-card .settings-financial__footer {
    align-items: stretch;
    flex-direction: column;
  }

  .business-config-card .settings-financial__footer button {
    width: 100%;
  }
}

