/* =========================================================
   FIX DISTRIBUCIÓN — PURCHASE ORDERS
   Agregar al FINAL de apps/web/src/styles.css

   Objetivo:
   - Eliminar la columna vacía de la izquierda.
   - Hacer que Nueva orden + Historial ocupen todo el ancho.
   - Mantener la cabecera compacta.
   - Distribuir filtros y KPIs de forma uniforme.
   ========================================================= */

.purchase-orders-v2.maintenance-page {
  width: 100%;
  max-width: 1380px;
  margin: 0 auto;
}

/* IMPORTANTE:
   El layout anterior heredaba la distribución en 2 columnas.
   Lo convertimos a una sola columna. */
.purchase-orders-v2.maintenance-page .purchase-orders-v2__layout {
  width: 100%;
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) !important;
  gap: 12px !important;
  align-items: start;
}

/* Nueva orden: command bar horizontal a todo el ancho */
.purchase-orders-v2.maintenance-page .purchase-orders-v2__command {
  width: 100%;
  min-width: 0;
  display: flex !important;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin: 0 !important;
  padding: 12px 14px !important;
}

.purchase-orders-v2.maintenance-page .purchase-orders-v2__command > div {
  min-width: 0;
}

.purchase-orders-v2.maintenance-page .purchase-orders-v2__command h2 {
  margin: 2px 0 3px;
  font-size: .9rem;
}

.purchase-orders-v2.maintenance-page
  .purchase-orders-v2__command
  p:not(.eyebrow) {
  margin: 0;
  color: #748078;
  font-size: .66rem;
}

/* Historial a todo el ancho */
.purchase-orders-v2.maintenance-page .purchase-orders-v2__orders {
  width: 100%;
  min-width: 0;
  margin: 0 !important;
  padding: 13px !important;
}

/* Encabezado Historial */
.purchase-orders-v2.maintenance-page .purchase-orders-v2__orders-header {
  margin-bottom: 10px;
}

/* Filtros:
   búsqueda toma más espacio;
   selects/fechas permanecen compactos. */
.purchase-orders-v2.maintenance-page
  .purchase-orders-v2__toolbar--filters {
  width: 100%;
  display: grid !important;
  grid-template-columns:
    minmax(260px, 1.5fr)
    minmax(130px, .65fr)
    minmax(180px, .9fr)
    minmax(135px, .6fr)
    minmax(135px, .6fr)
    auto !important;
  gap: 9px !important;
  align-items: end;
  padding: 10px !important;
}

/* Corrige el botón limpiar cuando alguna regla anterior
   lo empuja a otra fila. */
.purchase-orders-v2.maintenance-page
  .purchase-orders-v2__clear-filters {
  align-self: end;
  justify-self: end;
  white-space: nowrap;
}

/* KPIs ocupando toda la fila */
.purchase-orders-v2.maintenance-page .purchase-orders-v2__summary {
  width: 100%;
  grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
  gap: 10px !important;
  margin: 11px 0 !important;
}

.purchase-orders-v2.maintenance-page
  .purchase-orders-v2__summary article {
  width: 100%;
  min-height: 96px !important;
}

/* Lista de órdenes: usar mejor el ancho disponible */
.purchase-orders-v2.maintenance-page
  .purchase-orders-v2__order-list {
  width: 100%;
}

.purchase-orders-v2.maintenance-page
  .purchase-orders-v2__order-card {
  width: 100%;
  grid-template-columns: 42px minmax(0, 1fr) auto !important;
  gap: 12px !important;
  min-height: 72px !important;
  padding: 9px 11px !important;
}

/* Más aire entre metadata sin agrandar la card */
.purchase-orders-v2.maintenance-page
  .purchase-orders-v2__order-meta {
  gap: 7px 16px !important;
}

/* Header:
   evita que selector + botones se separen demasiado */
.purchase-orders-v2.maintenance-page
  .purchase-orders-v2__header-actions {
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 9px !important;
}

/* Desktop mediano */
@media (max-width: 1180px) {
  .purchase-orders-v2.maintenance-page
    .purchase-orders-v2__toolbar--filters {
    grid-template-columns:
      minmax(220px, 1fr)
      minmax(130px, .7fr)
      minmax(170px, .9fr)
      repeat(2, minmax(130px, .65fr)) !important;
  }

  .purchase-orders-v2.maintenance-page
    .purchase-orders-v2__clear-filters {
    grid-column: 1 / -1;
    justify-self: end;
  }
}

/* Tablet */
@media (max-width: 900px) {
  .purchase-orders-v2.maintenance-page
    .purchase-orders-v2__toolbar--filters {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;
  }

  .purchase-orders-v2.maintenance-page
    .purchase-orders-v2__search {
    grid-column: 1 / -1;
  }

  .purchase-orders-v2.maintenance-page
    .purchase-orders-v2__summary {
    grid-template-columns: 1fr !important;
  }

  .purchase-orders-v2.maintenance-page
    .purchase-orders-v2__clear-filters {
    grid-column: 1 / -1;
    justify-self: stretch;
  }
}

/* Mobile */
@media (max-width: 640px) {
  .purchase-orders-v2.maintenance-page
    .purchase-orders-v2__command {
    align-items: stretch;
    flex-direction: column;
  }

  .purchase-orders-v2.maintenance-page
    .purchase-orders-v2__command > button {
    width: 100%;
  }

  .purchase-orders-v2.maintenance-page
    .purchase-orders-v2__toolbar--filters {
    grid-template-columns: 1fr !important;
