.order-tickets-maintenance {
  width: 100%;
  max-width: 1380px;
  margin: 0 auto;
}

.order-tickets-maintenance
  .ticket-screen__toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.order-tickets-maintenance__actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 8px;
}

.order-tickets-maintenance__summary {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin: 12px 0;
}

.order-tickets-maintenance__summary > div {
  min-width: 0;
  display: grid;
