/* ---------------------------------------------------------
   PRINT
   Mantiene el ticket limpio e independiente de la UI.
   --------------------------------------------------------- */

@media print {
  @page {
    margin: 8mm;
  }

  body {
    background: #fff !important;
  }

  .no-print {
    display: none !important;
  }

  .order-tickets-maintenance {
    width: auto;
    max-width: none;
    margin: 0;
  }

  .ticket-pages {
    display: block !important;
  }

  .work-ticket {
    width: 100%;
    margin: 0;
    border: 1px solid #111 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    page-break-after: always;
    break-after: page;
  }

  .work-ticket:last-child {
    page-break-after: auto;
    break-after: auto;
  }

  .work-ticket__code,
  .work-ticket__meta > div,
  .work-ticket__total {
    background: transparent !important;
  }
}

