@media (max-width: 680px) {
  .order-tickets-maintenance
    .ticket-screen__toolbar,
  .order-tickets-maintenance__actions {
    align-items: stretch;
    flex-direction: column;
  }

  .order-tickets-maintenance__actions button {
    width: 100%;
  }

  .ticket-pages,
  .order-tickets-maintenance__summary,
  .work-ticket__meta {
    grid-template-columns: 1fr;
  }
}
