  margin: 0 auto;
  padding: 14px 18px 28px !important;

  background:
    radial-gradient(
      circle at 93% 2%,
      rgb(32 102 107 / 5%),
      transparent 30%
    ),
    #f6f9f7;
}

/* =========================================================
   HEADER — COMPACTO Y MODERNO
   ========================================================= */

.coffee-pos > .coffee-pos__header.maintenance-header {
  width: 100% !important;
  min-height: 64px !important;

  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;

  gap: 16px !important;

  margin: 0 0 12px !important;
  padding: 10px 14px !important;

  border: 1px solid #195b60 !important;
  border-radius: 12px !important;

  background:
    linear-gradient(
      135deg,
      #1d6267 0%,
      #20666b 58%,
      #1a5d62 100%
    ) !important;

  color: #fff !important;

  box-shadow:
    0 1px 2px rgb(15 23 42 / 7%),
    0 8px 22px rgb(15 23 42 / 8%) !important;
}

.coffee-pos .maintenance-header__content {
  min-width: 0;

  display: flex !important;
  align-items: center !important;

  gap: 10px !important;
}

.coffee-pos .maintenance-header__icon {
  width: 38px !important;
  height: 38px !important;

  flex: 0 0 38px !important;

  display: grid !important;
  place-items: center !important;

  border: 1px solid rgb(255 255 255 / 55%);
  border-radius: 9px !important;

  color: #176267 !important;
  background: #fff !important;

  box-shadow:
    0 3px 8px rgb(8 49 52 / 10%);
}

.coffee-pos .maintenance-header__icon svg {
  width: 18px !important;
  height: 18px !important;
}

.coffee-pos .maintenance-header__text h1 {
  margin: 0 !important;

  color: #fff !important;

  font-size: .96rem !important;
  font-weight: 780 !important;
  line-height: 1.15 !important;
  letter-spacing: -.01em !important;
}

.coffee-pos .maintenance-header__text p {
  margin: 2px 0 0 !important;

  color: #dceeed !important;

  font-size: .58rem !important;
  font-weight: 500 !important;
  line-height: 1.3 !important;
}

.coffee-pos__tabs {
  display: flex !important;
  align-items: center !important;
  justify-content: flex-end !important;

  flex-wrap: wrap;

  gap: 7px !important;
}

/* Header: acciones secundarias claras; acción activa con énfasis */
.coffee-pos__tabs button {
  min-height: 31px !important;

  border: 1px solid rgb(255 255 255 / 35%) !important;
  border-radius: 8px !important;

  background: rgb(255 255 255 / 93%) !important;
  color: #28544a !important;

  box-shadow: none !important;
}

.coffee-pos__tabs button.active {
  border-color: #238a61 !important;

  background: #168052 !important;
  color: #fff !important;
}

/* =========================================================
   ESTÁNDAR GLOBAL DE BOTONES DENTRO DEL POS
   ========================================================= */

.coffee-pos button {
  min-height: 31px !important;
  height: auto !important;

  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;

  gap: 7px !important;

  padding: 5px 10px !important;

  border-radius: 7px !important;

  font-size: .61rem !important;
  font-weight: 720 !important;
  line-height: 1.1 !important;
}

.coffee-pos button > svg {
  width: 14px !important;
  height: 14px !important;

  flex: 0 0 14px !important;

  margin: 0 !important;
}

/* =========================================================
   BARRAS DE ESTADO
   ========================================================= */

.coffee-pos > .operations-success,
.coffee-pos > .operations-error {
  min-height: 38px;

  display: flex;
  align-items: center;

  margin: 0 0 10px !important;
  padding: 8px 12px !important;

  border-radius: 10px !important;

  font-size: .62rem !important;
  font-weight: 650 !important;
}

.coffee-pos > .operations-success {
  border: 1px solid #d7eadf !important;

  color: #17643f !important;
  background: #edf8f1 !important;
}

.coffee-pos > .operations-error {
  border: 1px solid #efd9d7 !important;

  color: #8a3f39 !important;
  background: #fff4f2 !important;
}

/* =========================================================
   LAYOUT PRINCIPAL — PROPORCIÓN 64 / 36
   ========================================================= */

.coffee-pos__layout {
  width: 100%;

  display: grid !important;

  grid-template-columns:
    minmax(0, 1.72fr)
    minmax(390px, .92fr) !important;

  gap: 14px !important;

  align-items: start !important;
}

/* =========================================================
   PANELES PRINCIPALES
   ========================================================= */

.coffee-pos__catalog,
.coffee-pos__cart {
  min-width: 0;

  border: 1px solid #dce5e0 !important;
  border-radius: 12px !important;

  background: #fff !important;

  box-shadow:
    0 1px 2px rgb(15 23 42 / 3%),
    0 10px 28px rgb(15 23 42 / 4%) !important;
}

.coffee-pos__catalog {
  padding: 12px !important;
}

.coffee-pos__cart {
  padding: 12px !important;
}

/* =========================================================
   ESCÁNER + BÚSQUEDA
   ========================================================= */

.pos-barcode-scanner {
  margin: 0 0 10px !important;
  padding: 11px !important;

  border: 1px solid #e0e8e4 !important;
  border-radius: 10px !important;

  background: #f9fbfa !important;
}

.pos-barcode-scanner > label {
  margin-bottom: 5px;

  color: #26372f;

  font-size: .61rem !important;
  font-weight: 800 !important;
}

.coffee-pos .operations-search {
  min-height: 38px !important;

  display: flex !important;
  align-items: center !important;

  gap: 8px !important;

  padding: 0 10px !important;

  border: 1px solid #d8e2dd !important;
  border-radius: 9px !important;

  background: #fff !important;

  transition:
    border-color 140ms ease,
    box-shadow 140ms ease;
}

.coffee-pos .operations-search:focus-within {
  border-color: #7ca9aa !important;

  box-shadow:
    0 0 0 3px rgb(32 102 107 / 8%) !important;
}

.coffee-pos .operations-search svg {
  color: #397974 !important;
}

.coffee-pos .operations-search input {
  min-height: 34px !important;

  border: 0 !important;
  outline: 0 !important;

  padding: 0 !important;

  background: transparent !important;

  box-shadow: none !important;

  font-size: .65rem !important;
}

.pos-barcode-scanner__status {
  min-height: 27px;

  display: flex !important;
  align-items: center !important;

  flex-wrap: wrap;

  gap: 8px !important;

  margin-top: 6px !important;

  color: #6d7b74 !important;

  font-size: .55rem !important;
}

.pos-barcode-scanner__ready {
  display: inline-flex;
  align-items: center;

  min-height: 22px;

  padding: 3px 7px;

  border-radius: 999px;

  color: #16643f !important;
  background: #e5f4eb !important;

  font-weight: 800 !important;
}

/* Buscador principal separado visualmente */
.coffee-pos__catalog > .operations-search {
  margin-top: 2px;
}

/* =========================================================
   FILTROS DE CATEGORÍA
   ========================================================= */

.coffee-pos .operations-filters {
  width: 100%;

  display: flex !important;
  align-items: center !important;

  gap: 6px !important;

  margin: 10px 0 12px !important;

  padding: 0 0 2px;

  overflow-x: auto;
  scrollbar-width: thin;
}

.coffee-pos .operations-filter {
  min-height: 29px !important;

  flex: 0 0 auto;

  padding: 4px 10px !important;

  border: 1px solid #dce4e0 !important;
  border-radius: 999px !important;

  background: #fff !important;
  color: #45564d !important;

  box-shadow: none !important;
}

.coffee-pos .operations-filter:hover:not(:disabled) {
  border-color: #aebdb6 !important;

  background: #f5f8f6 !important;
}

.coffee-pos .operations-filter--active {
  border-color: #20666b !important;

  background: #edf5f4 !important;
  color: #174f52 !important;
}

/* =========================================================
   GRID DE PRODUCTOS
   ========================================================= */

.retail-product-grid {
  display: grid !important;

  grid-template-columns:
    repeat(4, minmax(0, 1fr)) !important;

  gap: 10px !important;

  align-items: stretch;
}

.coffee-pos .retail-product-card {
  position: relative;

  min-width: 0;
  min-height: 176px !important;

  display: flex !important;
  flex-direction: column !important;

  align-items: stretch !important;
  justify-content: flex-start !important;

  gap: 3px !important;

  padding: 8px !important;

  overflow: hidden;

  border: 1px solid #dfe7e3 !important;
  border-radius: 10px !important;

  background: #fff !important;
  color: #26372f !important;

  text-align: left !important;
  white-space: normal !important;

  box-shadow:
    0 2px 7px rgb(15 23 42 / 3%) !important;

  transition:
    transform 140ms ease,
    border-color 140ms ease,
    box-shadow 140ms ease !important;
}

.coffee-pos .retail-product-card:hover:not(:disabled) {
  transform: translateY(-2px);

  border-color: #9dbab6 !important;

  box-shadow:
    0 8px 20px rgb(15 23 42 / 7%) !important;
}

.coffee-product-image-wrap,
.retail-product-icon {
  width: 100%;
  height: 86px !important;

  flex: 0 0 86px;

  display: grid;
  place-items: center;

  margin-bottom: 5px !important;

  overflow: hidden;

  border-radius: 8px !important;

  background:
    linear-gradient(
      145deg,
      #f7faf8,
      #eef4f1
    ) !important;
}

.coffee-product-image {
  width: 100%;
  height: 100%;

  object-fit: contain !important;

  padding: 4px;
}

.retail-product-icon {
  color: #187b54 !important;
}

.retail-product-icon svg {
  width: 28px !important;
  height: 28px !important;
}

.coffee-pos .retail-product-card > strong {
  overflow: hidden;

  color: #24362d !important;

  font-size: .66rem !important;
  font-weight: 780 !important;
  line-height: 1.2 !important;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.coffee-pos .retail-product-card > span,
.coffee-pos .retail-product-card > small {
  overflow: hidden;

  color: #718078 !important;

  font-size: .52rem !important;
  line-height: 1.25 !important;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.coffee-pos .retail-product-card > b {
  margin-top: auto !important;
  padding-top: 5px;

  color: #126b4a !important;

  font-size: .7rem !important;
  font-weight: 850 !important;
}

.coffee-pos .inventory-alert {
  position: absolute;

  right: 7px;
  top: 7px;

  z-index: 2;

  width: fit-content;

  padding: 3px 6px;

  border-radius: 999px;

  font-size: .48rem !important;
  font-weight: 800 !important;
}

/* =========================================================
   CARRITO — ENCABEZADO
   ========================================================= */

.retail-cart__title {
  min-height: 43px;

  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;

  gap: 8px !important;

  padding-bottom: 10px !important;

  border-bottom: 1px solid #e9eeeb;
}

.retail-cart__title-main {
  min-width: 0;

  display: flex !important;
  align-items: center !important;

  gap: 7px !important;

  flex-wrap: wrap;
}

.retail-cart__title-main > svg {
  width: 18px !important;
  height: 18px !important;

  color: #176d70 !important;
}

.retail-cart__title h2 {
  margin: 0 !important;

  color: #23352c !important;

  font-size: .78rem !important;
  font-weight: 800 !important;
}

.retail-cart__count {
  color: #0e7b55 !important;

  font-size: .58rem !important;
  font-weight: 800 !important;
}

.retail-cart__clear {
  min-height: 28px !important;

  padding: 4px 8px !important;
}

/* =========================================================
   CONTEXTO DE VENTA
   ========================================================= */

.retail-cart__context {
  display: grid !important;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 8px !important;

  margin: 10px 0 0;
  padding: 10px !important;

  border: 1px solid #e2e9e5;
  border-radius: 10px;

  background:
    linear-gradient(
      145deg,
      #fafcfb,
      #f6f9f7
    ) !important;
}

.retail-cart__context label,
.retail-cart__checkout label {
  min-width: 0;

  display: grid;

  gap: 4px;

  color: #53645b;

  font-size: .58rem !important;
  font-weight: 750 !important;
}

.retail-cart__context input,
.retail-cart__context select,
.retail-cart__checkout input,
.retail-cart__checkout select {
  width: 100%;
  min-width: 0;
  min-height: 34px !important;

  padding: 5px 8px !important;

  border: 1px solid #d9e2de !important;
  border-radius: 8px !important;

  background: #fff !important;

  color: #26372f;

  font-size: .62rem !important;
}

/* Modalidad de venta ocupa todo el ancho */
.pos-sale-mode {
  grid-column: 1 / -1;
}

.pos-sale-mode__label {
  display: block;

  margin-bottom: 6px;

  color: #53645b;

  font-size: .58rem !important;
  font-weight: 750 !important;
}

.pos-sale-mode__options {
  display: grid !important;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 6px !important;
}

.coffee-pos .pos-sale-mode__option {
  min-height: 62px !important;

  display: grid !important;

  align-content: center;

  gap: 3px !important;

  padding: 7px 8px !important;

  border: 1px solid #dce4e0 !important;
  border-radius: 9px !important;

  background: #fff !important;
  color: #42544a !important;

  white-space: normal !important;

  box-shadow: none !important;
}

.coffee-pos .pos-sale-mode__option:hover:not(:disabled) {
  border-color: #aebdb6 !important;

  background: #f9fbfa !important;
}

.coffee-pos .pos-sale-mode__option--active {
  border-color: #20757a !important;

  background: #edf6f5 !important;
  color: #174f52 !important;

  box-shadow:
    inset 0 0 0 1px rgb(32 102 107 / 8%) !important;
}

.pos-sale-mode__option strong {
  font-size: .61rem !important;
}

.pos-sale-mode__option small {
  color: #77847d !important;

  font-size: .49rem !important;
  font-weight: 500 !important;
  line-height: 1.25 !important;
}

/* =========================================================
   TABLA DEL CARRITO
   ========================================================= */

.retail-cart__scroll {
  max-height: 320px;

  margin-top: 10px;

  overflow: auto;

  border: 1px solid #e0e8e4 !important;
  border-radius: 9px !important;

  background: #fff;
}

.retail-cart__table-head,
.retail-cart__item {
  display: grid !important;

  grid-template-columns:
    minmax(120px, 1.55fr)
    minmax(70px, .8fr)
    minmax(108px, 1fr)
    48px
    minmax(82px, .9fr)
    36px !important;

  align-items: center;

  gap: 6px !important;
}

.retail-cart__table-head {
  position: sticky;

  top: 0;

  z-index: 3;

  min-height: 34px;

  padding: 7px 8px !important;

  border-bottom: 1px solid #e4ebe7;

  background: #f3f7f5 !important;

  color: #617068 !important;

  font-size: .5rem !important;
  font-weight: 850 !important;
}

.retail-cart__item {
  min-height: 48px;

  padding: 7px 8px !important;

  border-top: 1px solid #edf1ef;
}

.retail-cart__item:hover {
  background: #fbfdfc;
}

.retail-cart__product-cell strong,
.retail-cart__price-cell,
.retail-cart__subtotal-cell,
.retail-cart__unit-cell {
  font-size: .57rem !important;
}

.quantity-control {
  display: grid !important;

  grid-template-columns:
    26px
    minmax(46px, 1fr)
    26px;

  gap: 3px !important;

  align-items: center;
}

.coffee-pos .quantity-control button,
.coffee-pos .retail-cart__remove {
  min-width: 26px !important;
  min-height: 26px !important;

  padding: 3px !important;

  border-radius: 6px !important;
}

.quantity-input {
  width: 100%;
  min-height: 27px !important;

  padding: 3px 4px !important;

  text-align: center;

  font-size: .57rem !important;
}

.retail-cart__empty {
  min-height: 118px;

  display: grid;

  place-items: center;

  margin: 8px !important;
  padding: 20px 12px !important;

  border: 1px dashed #cad8d1;
  border-radius: 8px;

  color: #74817a;

  background: #fbfdfc;

  text-align: center;

  font-size: .58rem !important;
}

/* =========================================================
   RESUMEN FINANCIERO + CHECKOUT
   ========================================================= */

.pos-financial-summary {
  display: grid !important;

  gap: 5px !important;

  margin-top: 10px !important;
  padding: 10px 11px !important;

  border: 1px solid #d9e8df !important;
  border-radius: 9px !important;

  background:
    linear-gradient(
      145deg,
      #f2f8f4,
      #eef6f2
    ) !important;
}

.pos-financial-summary > div {
  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 10px;

  color: #617068;

  font-size: .58rem !important;
}

.pos-financial-summary__total {
  margin-top: 3px;

  padding-top: 7px;

  border-top: 1px dashed #cbdcd2;
}

.pos-financial-summary__total span {
  color: #273a30;

  font-weight: 800;
}

.pos-financial-summary__total strong {
  color: #126b4a !important;

  font-size: .78rem !important;
  font-weight: 850 !important;
}

.pos-financial-summary > small {
  color: #7d8982;

  font-size: .48rem !important;
  line-height: 1.3;
}

.retail-cart__checkout {
  display: grid !important;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 8px !important;

  margin-top: 10px;
}

.retail-cart__checkout .pos-financial-summary {
  grid-column: 1 / -1;

  margin-top: 0 !important;
}

.retail-cart__checkout > button {
  width: 100%;

  min-height: 34px !important;
}

/* Acción principal */
.retail-cart__checkout > button:not(.secondary-button) {
  border-color: #126b4a !important;

  background: #126b4a !important;
  color: #fff !important;
}

/* =========================================================
   HOLD BOARD
   ========================================================= */

.coffee-hold-board {
  padding: 12px !important;

  border: 1px solid #dce5e0 !important;
  border-radius: 12px !important;

  background: #fff !important;

  box-shadow:
    0 1px 2px rgb(15 23 42 / 3%),
    0 10px 28px rgb(15 23 42 / 4%) !important;
}

.food-service-board__header h2 {
  margin: 2px 0 !important;

  color: #24362d;

  font-size: .86rem !important;
}

.food-service-board__header p {
  margin: 0;

  color: #738078;

  font-size: .59rem !important;
}

.coffee-account-grid {
  display: grid !important;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 9px !important;

  margin-top: 10px;
}

.coffee-account-card {
  min-width: 0;

  padding: 10px !important;

  border: 1px solid #dfe7e3 !important;
  border-radius: 9px !important;

  background: #fff;

  box-shadow:
    0 2px 8px rgb(15 23 42 / 3%);
}

.coffee-account-card h3 {
  margin: 7px 0 3px !important;

  font-size: .7rem !important;
}

.coffee-account-actions {
  display: flex !important;

  gap: 6px !important;

  margin-top: 8px;

  flex-wrap: wrap;
}

/* =========================================================
   MODAL DE PESO
   ========================================================= */

.pos-weight-modal-backdrop {
  backdrop-filter: blur(3px);
}

.pos-weight-modal {
  width: min(420px, calc(100vw - 24px)) !important;

  padding: 14px !important;

  border: 1px solid #dce5e0 !important;
  border-radius: 12px !important;

  background: #fff !important;

  box-shadow:
    0 24px 60px rgb(15 23 42 / 18%) !important;
}

.pos-weight-modal__header h2 {
  font-size: .84rem !important;
}

.pos-weight-modal__facts > div,
.pos-weight-modal__subtotal {
  padding: 9px !important;

  border-radius: 8px !important;
}

/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1280px) {
  .coffee-pos__layout {
    grid-template-columns:
      minmax(0, 1.4fr)
      minmax(380px, .95fr) !important;
  }

  .retail-product-grid {
    grid-template-columns:
      repeat(3, minmax(0, 1fr)) !important;
  }

  .coffee-account-grid {
    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 980px) {
  .coffee-pos__layout {
    grid-template-columns: 1fr !important;
  }

  .retail-product-grid {
    grid-template-columns:
      repeat(4, minmax(0, 1fr)) !important;
  }

  .coffee-pos__cart {
    position: static !important;
  }
}

@media (max-width: 760px) {
  .coffee-pos {
    padding-inline: 10px !important;
  }

  .coffee-pos > .coffee-pos__header.maintenance-header {
    align-items: stretch !important;
    flex-direction: column !important;
  }

  .coffee-pos__tabs {
    justify-content: flex-start !important;
  }

  .retail-product-grid,
  .coffee-account-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;
  }

  .retail-cart__context,
  .retail-cart__checkout {
    grid-template-columns: 1fr !important;
  }

  .pos-sale-mode {
    grid-column: auto;
  }

  .pos-sale-mode__options {
    grid-template-columns: 1fr !important;
  }

  .retail-cart__checkout .pos-financial-summary {
    grid-column: auto;
  }
}

@media (max-width: 520px) {
  .retail-product-grid,
  .coffee-account-grid {
    grid-template-columns: 1fr !important;
  }

  .retail-cart__table-head {
    display: none !important;
  }

  .retail-cart__item {
    grid-template-columns:
      minmax(0, 1fr)
      auto !important;
  }
}
/* =========================================================
   POS WORKSPACE — MODERN UI V4
   Ajustes solicitados:
   1) Imágenes completas dentro de su espacio.
   2) Tipografía ligeramente mayor.
   3) Subtotal por artículo visible en columna derecha.
