/* =========================================================
   CACTUS ERP — BUTTON SYSTEM GLOBAL V1
   ESTÁNDAR APROBADO PARA TODAS LAS PANTALLAS
   ========================================================= */

:root {
  --btn-primary-bg: #176447;
  --btn-primary-bg-hover: #12543b;
  --btn-primary-text: #ffffff;

  --btn-secondary-bg: #f7f8fa;
  --btn-secondary-bg-hover: #eef1f3;
  --btn-secondary-border: #d7dee3;
  --btn-secondary-border-hover: #b8c2c9;
  --btn-secondary-text: #3f4d55;

  --btn-active-bg: #e8edef;
  --btn-active-border: #87959e;
  --btn-active-text: #26363d;

  --btn-disabled-bg: #eceff1;
  --btn-disabled-border: #d8dde1;
  --btn-disabled-text: #9aa4aa;
}


/* =========================================================
   1. BOTÓN PRIMARIO
   Verde = siempre texto blanco
   ========================================================= */

button:not(
  .secondary-button,
  .maintenance-icon-button,
  .operations-filter,
  .maintenance-category-icon-option,
  .maintenance-category-item,
  .maintenance-station-item,
  .purchase-orders-v2__refresh,
  .maintenance-modal__close
) {
  background: var(--btn-primary-bg) !important;
  background-image: none !important;

  color: var(--btn-primary-text) !important;

  border-color: var(--btn-primary-bg) !important;

  box-shadow: none !important;
}

button:not(
  .secondary-button,
  .maintenance-icon-button,
  .operations-filter,
  .maintenance-category-icon-option,
  .maintenance-category-item,
  .maintenance-station-item,
  .purchase-orders-v2__refresh,
  .maintenance-modal__close
):hover:not(:disabled) {
  background: var(--btn-primary-bg-hover) !important;

  color: #ffffff !important;

  border-color: var(--btn-primary-bg-hover) !important;
}


/* Iconos de botones primarios */
button:not(
  .secondary-button,
  .maintenance-icon-button,
  .operations-filter,
  .maintenance-category-icon-option,
  .maintenance-category-item,
  .maintenance-station-item,
  .purchase-orders-v2__refresh,
  .maintenance-modal__close
) svg {
  color: currentColor !important;
  stroke: currentColor !important;
}


/* =========================================================
   2. BOTONES SECUNDARIOS
   Nunca verdes
   ========================================================= */

button.secondary-button {
  background: var(--btn-secondary-bg) !important;
  background-image: none !important;

  color: var(--btn-secondary-text) !important;

  border: 1px solid var(--btn-secondary-border) !important;

  box-shadow: none !important;
}

button.secondary-button:hover:not(:disabled) {
  background: var(--btn-secondary-bg-hover) !important;

  color: #26363d !important;

  border-color: var(--btn-secondary-border-hover) !important;
}

button.secondary-button svg {
  color: currentColor !important;
  stroke: currentColor !important;
}


/* =========================================================
   3. BOTONES DE ICONO
   Editar, actualizar, movimientos, etc.
   ========================================================= */

button.maintenance-icon-button,
.purchase-orders-v2__refresh {
  background: #f7f9fa !important;
  background-image: none !important;

  color: #596870 !important;

  border: 1px solid #d8dfe4 !important;

  box-shadow: none !important;
}

button.maintenance-icon-button:hover:not(:disabled),
.purchase-orders-v2__refresh:hover:not(:disabled) {
  background: #edf1f3 !important;

  color: #26363d !important;

  border-color: #b9c3ca !important;
}

button.maintenance-icon-button svg,
.purchase-orders-v2__refresh svg {
  color: currentColor !important;
}


/* =========================================================
   4. FILTROS
   Todos / Abiertos / Agotados / Stock bajo / etc.
   ========================================================= */

button.operations-filter,
.inventory-replenishment-v2__filters button {
  background: #ffffff !important;
  background-image: none !important;

  color: #56636c !important;

  border: 1px solid #d7dee3 !important;

  box-shadow: none !important;
}

button.operations-filter:hover:not(:disabled),
.inventory-replenishment-v2__filters button:hover:not(:disabled) {
  background: #f1f4f5 !important;

  color: #26363d !important;

  border-color: #b8c2c9 !important;
