/* =========================================================
   CACTUS ERP — COLOR SYSTEM GLOBAL
   Regla oficial para botones, paneles y estados
   ========================================================= */

:root {
  /* -------------------------------------------------------
     BRAND / PRIMARY
     ------------------------------------------------------- */

  --erp-primary: #176447;
  --erp-primary-hover: #12543b;
  --erp-primary-soft: #eef6f2;
  --erp-primary-border: #cfe2d8;

  /* -------------------------------------------------------
     NEUTRALS
     ------------------------------------------------------- */

  --erp-bg: #f5f7f8;
  --erp-surface: #ffffff;
  --erp-surface-soft: #f8fafb;
  --erp-surface-muted: #eef2f4;

  --erp-border: #d9e0e5;
  --erp-border-strong: #b8c2c9;

  --erp-text: #26363d;
  --erp-text-secondary: #5f6d75;
  --erp-text-muted: #7b8790;

  /* -------------------------------------------------------
     SEMANTIC COLORS
     ------------------------------------------------------- */

  --erp-success-bg: #eef7f2;
  --erp-success-border: #cde2d5;
  --erp-success-text: #35684d;

  --erp-warning-bg: #fff8e8;
  --erp-warning-border: #ead8aa;
  --erp-warning-text: #7a5c18;

  --erp-danger-bg: #fff1f0;
  --erp-danger-border: #efc7c3;
  --erp-danger-text: #973f37;

  --erp-info-bg: #eef3f7;
  --erp-info-border: #cedbe5;
  --erp-info-text: #466375;

  /* -------------------------------------------------------
     ACTIVE / SELECTED
     ------------------------------------------------------- */

  --erp-active-bg: #e8edef;
  --erp-active-border: #87959e;
  --erp-active-text: #26363d;
}

/* =========================================================
   BUTTONS
   ========================================================= */

/* Primario */
.erp-button-primary,
button.erp-button-primary {
  background: var(--erp-primary) !important;
  color: #fff !important;

  border: 1px solid var(--erp-primary) !important;
  border-radius: 8px !important;

  box-shadow: none !important;
}

.erp-button-primary:hover:not(:disabled),
button.erp-button-primary:hover:not(:disabled) {
  background: var(--erp-primary-hover) !important;
  border-color: var(--erp-primary-hover) !important;
}

/* Secundario */
.erp-button-secondary,
button.secondary-button,
button.erp-button-secondary {
  background: var(--erp-surface-soft) !important;
  color: var(--erp-text) !important;

  border: 1px solid var(--erp-border) !important;

  box-shadow: none !important;
}

.erp-button-secondary:hover:not(:disabled),
button.secondary-button:hover:not(:disabled),
button.erp-button-secondary:hover:not(:disabled) {
  background: var(--erp-surface-muted) !important;

  border-color: var(--erp-border-strong) !important;
}

/* Botón de icono */
.erp-icon-button,
button.maintenance-icon-button {
  background: var(--erp-surface-soft) !important;
  color: var(--erp-text-secondary) !important;

  border: 1px solid var(--erp-border) !important;

  box-shadow: none !important;
}

.erp-icon-button:hover:not(:disabled),
button.maintenance-icon-button:hover:not(:disabled) {
  background: var(--erp-surface-muted) !important;
  color: var(--erp-text) !important;
}

/* Disabled */
button:disabled {
  opacity: 1 !important;

  background: #eceff1 !important;
  color: #9aa4aa !important;

  border-color: #d8dde1 !important;

  cursor: not-allowed !important;
}

/* =========================================================
   FILTERS
   ========================================================= */

.erp-filter-button,
.operations-filter {
  background: var(--erp-surface) !important;
  color: var(--erp-text-secondary) !important;

  border: 1px solid var(--erp-border) !important;

  box-shadow: none !important;
}

.erp-filter-button:hover:not(:disabled),
.operations-filter:hover:not(:disabled) {
  background: var(--erp-surface-soft) !important;
  color: var(--erp-text) !important;

  border-color: var(--erp-border-strong) !important;
}

.erp-filter-button.active,
.operations-filter--active {
  background: var(--erp-active-bg) !important;
  color: var(--erp-active-text) !important;

  border-color: var(--erp-active-border) !important;
}

/* =========================================================
   PANELS / CARDS
   ========================================================= */

.erp-panel,
.settings-card,
.maintenance-card {
  background: var(--erp-surface) !important;

  border: 1px solid var(--erp-border) !important;
  border-radius: 10px !important;

  box-shadow:
    0 1px 2px rgb(16 24 40 / 4%) !important;
}

/* Panel secundario */
.erp-panel-soft {
  background: var(--erp-surface-soft) !important;

  border: 1px solid var(--erp-border) !important;
}

/* Nunca usar verde en paneles normales */
.erp-panel:not(.erp-panel--success),
.settings-card:not(.erp-panel--success),
.maintenance-card:not(.erp-panel--success) {
  background-image: none !important;
}

/* =========================================================
   STATUS
   ========================================================= */

.erp-status-success,
.maintenance-badge--success {
  background: var(--erp-success-bg) !important;
  color: var(--erp-success-text) !important;

  border: 1px solid var(--erp-success-border) !important;
}

.erp-status-warning,
.maintenance-badge--warning {
  background: var(--erp-warning-bg) !important;
  color: var(--erp-warning-text) !important;

  border: 1px solid var(--erp-warning-border) !important;
}

.erp-status-danger,
.maintenance-badge--danger {
  background: var(--erp-danger-bg) !important;
  color: var(--erp-danger-text) !important;

  border: 1px solid var(--erp-danger-border) !important;
}

.erp-status-info {
  background: var(--erp-info-bg) !important;
  color: var(--erp-info-text) !important;

  border: 1px solid var(--erp-info-border) !important;
}

/* =========================================================
   DASHBOARD KPI CARDS
   ========================================================= */

.dashboard-card,
.dashboard-kpi-card {
  background: var(--erp-surface) !important;

  border: 1px solid var(--erp-border) !important;

  box-shadow:
    0 1px 3px rgb(16 24 40 / 5%) !important;
}

.dashboard-card__icon,
.dashboard-kpi-card__icon {
  background: var(--erp-surface-muted) !important;
  color: var(--erp-text-secondary) !important;
}

/* Solo una KPI positiva explícita puede usar verde suave */
.dashboard-kpi-card--success .dashboard-kpi-card__icon {
  background: var(--erp-success-bg) !important;
  color: var(--erp-success-text) !important;
}

/* Advertencia */
.dashboard-kpi-card--warning .dashboard-kpi-card__icon {
  background: var(--erp-warning-bg) !important;
  color: var(--erp-warning-text) !important;
}

/* Crítico */
.dashboard-kpi-card--danger .dashboard-kpi-card__icon {
  background: var(--erp-danger-bg) !important;
  color: var(--erp-danger-text) !important;
}

/* =========================================================
   CACTUS ERP — DASHBOARD ENTERPRISE V2
   ========================================================= */

.dashboard-v2 {
  --db-bg: #f5f7f8;
  --db-surface: #ffffff;
  --db-soft: #f8fafb;
  --db-border: #d9e0e5;
  --db-border-strong: #bcc7cd;
  --db-text: #26363d;
  --db-muted: #6f7d85;
  --db-primary: #176447;
  --db-primary-hover: #12543b;
  --db-primary-soft: #eef6f2;
  --db-danger: #973f37;
  --db-danger-soft: #fff1f0;
  --db-warning: #8a6518;
  --db-warning-soft: #fff8e8;
  --db-info: #466375;
  --db-info-soft: #eef3f7;

  min-height: 100vh;
  display: grid;
  grid-template-columns: 218px minmax(0, 1fr);
  background: var(--db-bg);
  color: var(--db-text);
}

.dashboard-v2 *,
.dashboard-v2 *::before,
.dashboard-v2 *::after {
  box-sizing: border-box;
}

.dashboard-v2__sidebar {
  position: sticky;
  top: 0;
  height: 100vh;
  min-height: 0;
  display: flex;
  flex-direction: column;
  padding: 10px 10px 12px;
  overflow: hidden;
  background: linear-gradient(180deg, #07392b 0%, #05271e 100%);
  color: #fff;
}

.dashboard-v2__brand {
  width: 100%;
  min-height: 62px;
  display: flex !important;
  align-items: center;
  justify-content: flex-start;
  padding: 6px 8px !important;
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}

.dashboard-v2__brand img {
  width: 118px;
  max-height: 48px;
  object-fit: contain;
  object-position: left center;
}

.dashboard-v2__sidebar-title {
  padding: 4px 10px 13px;
  color: rgb(255 255 255 / 68%);
  font-size: 11px;
  font-weight: 600;
}

.dashboard-v2__nav {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding-right: 3px;
  scrollbar-width: thin;
  scrollbar-color: rgb(255 255 255 / 20%) transparent;
}

.dashboard-v2__nav-group {
  display: grid;
  gap: 3px;
}

.dashboard-v2__nav-group--system {
  margin-top: auto;
}

.dashboard-v2__nav-group small {
  padding: 0 9px 4px;
  color: rgb(255 255 255 / 43%);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .12em;
}

.dashboard-v2__nav-group button {
  min-height: 33px !important;
  display: flex !important;
  align-items: center;
  justify-content: flex-start !important;
  gap: 9px !important;
  padding: 6px 9px !important;
  border: 1px solid transparent !important;
  border-radius: 7px !important;
  background: transparent !important;
  background-image: none !important;
  color: rgb(255 255 255 / 78%) !important;
  box-shadow: none !important;
  font-size: 11px !important;
  font-weight: 600 !important;
}

.dashboard-v2__nav-group button svg {
  color: rgb(255 255 255 / 67%) !important;
}

.dashboard-v2__nav-group button:hover:not(:disabled) {
  background: rgb(255 255 255 / 8%) !important;
  color: #fff !important;
}

.dashboard-v2__nav-group button.is-active {
  background: #128454 !important;
  color: #fff !important;
}

.dashboard-v2__nav-group button.is-active svg {
  color: #fff !important;
}

.dashboard-v2__profile {
  flex: 0 0 auto;
  display: grid;
  grid-template-columns: 31px minmax(0, 1fr) 31px;
  gap: 8px;
  align-items: center;
  margin-top: 12px;
  padding: 11px 7px 0;
  border-top: 1px solid rgb(255 255 255 / 10%);
}

.dashboard-v2__avatar {
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #159260;
  color: #fff;
  font-size: 11px;
  font-weight: 800;
}

.dashboard-v2__profile-copy {
  min-width: 0;
  display: grid;
}

.dashboard-v2__profile-copy strong {
  overflow: hidden;
  color: #fff;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dashboard-v2__profile-copy small {
  color: rgb(255 255 255 / 50%);
  font-size: 8px;
}

.dashboard-v2__logout {
  width: 31px !important;
  height: 31px !important;
  min-height: 31px !important;
  display: grid !important;
  place-items: center;
  padding: 0 !important;
  border: 1px solid rgb(255 255 255 / 10%) !important;
  border-radius: 7px !important;
  background: transparent !important;
  color: rgb(255 255 255 / 72%) !important;
  box-shadow: none !important;
}

.dashboard-v2__workspace {
  width: 100%;
  max-width: 1540px;
  margin: 0 auto;
  padding: 22px 26px 28px;
}

.dashboard-v2__header {
  min-height: 66px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--db-border);
}

.dashboard-v2__eyebrow,
.dashboard-v2__section-head > div > span {
  color: var(--db-primary);
  font-size: 8px;
  font-weight: 850;
  letter-spacing: .12em;
}

.dashboard-v2__header h1 {
  margin: 3px 0 2px;
  color: #162229;
  font-size: clamp(24px, 2vw, 32px);
  line-height: 1.05;
  letter-spacing: -.035em;
}

.dashboard-v2__header p {
  margin: 0;
  color: var(--db-muted);
  font-size: 11px;
}

.dashboard-v2__header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.dashboard-v2__context {
  min-width: 170px;
  display: grid;
  gap: 2px;
  padding: 9px 12px;
  border: 1px solid #e5e9ec;
  border-radius: 10px;
  background: #fff;
}

.dashboard-v2__context span {
  color: var(--db-muted);
  font-size: 8px;
}

.dashboard-v2__context strong {
  max-width: 220px;
  overflow: hidden;
  color: var(--db-text);
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dashboard-v2__primary {
  min-height: 36px !important;
  display: inline-flex !important;
  align-items: center !important;
  gap: 7px !important;
  padding: 7px 13px !important;
  border: 1px solid var(--db-primary) !important;
  border-radius: 8px !important;
  background: var(--db-primary) !important;
  color: #fff !important;
  box-shadow: none !important;
  font-size: 10px !important;
  font-weight: 750 !important;
}

.dashboard-v2__primary:hover:not(:disabled) {
  background: var(--db-primary-hover) !important;
  border-color: var(--db-primary-hover) !important;
}

.dashboard-v2__refresh {
  width: 36px !important;
  height: 36px !important;
  min-height: 36px !important;
  display: grid !important;
  place-items: center;
  padding: 0 !important;
  border: 1px solid var(--db-border) !important;
  border-radius: 8px !important;
  background: #fff !important;
  color: #53636b !important;
  box-shadow: none !important;
}

.dashboard-v2__update-line {
  min-height: 34px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  color: var(--db-muted);
  font-size: 9px;
}

.dashboard-v2__kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.dashboard-v2__kpi {
  min-height: 112px;
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  padding: 14px;
  border: 1px solid var(--db-border);
  border-radius: 12px;
  background: var(--db-surface);
  box-shadow: 0 2px 7px rgb(16 24 40 / 3%);
}

.dashboard-v2__kpi-icon {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border-radius: 50%;
}

.dashboard-v2__kpi-icon--success {
  background: var(--db-primary-soft);
  color: var(--db-primary);
}

.dashboard-v2__kpi-icon--info {
  background: var(--db-info-soft);
  color: #23638b;
}

.dashboard-v2__kpi-icon--warning {
  background: var(--db-warning-soft);
  color: #c36d00;
}

.dashboard-v2__kpi > div {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.dashboard-v2__kpi > div > span {
  color: #50616b;
  font-size: 11px;
}

.dashboard-v2__kpi strong {
  overflow: hidden;
  color: #18252c;
  font-size: 18px;
  letter-spacing: -.02em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dashboard-v2__kpi small {
  color: var(--db-muted);
  font-size: 8px;
}

.dashboard-v2__panel {
  padding: 15px;
  border: 1px solid var(--db-border);
  border-radius: 12px;
  background: var(--db-surface);
  box-shadow: 0 2px 7px rgb(16 24 40 / 3%);
}

.dashboard-v2__section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 12px;
}

.dashboard-v2__section-head > div {
  display: grid;
  gap: 2px;
}

.dashboard-v2__section-head h2 {
  margin: 0;
  color: #1f2e35;
  font-size: 14px;
}

.dashboard-v2__text-action {
  display: inline-flex !important;
  align-items: center !important;
  gap: 3px !important;
  min-height: 28px !important;
  padding: 4px 6px !important;
  border: 0 !important;
  background: transparent !important;
  color: #40535d !important;
  box-shadow: none !important;
  font-size: 9px !important;
  font-weight: 700 !important;
}

.dashboard-v2__attention {
  margin-top: 10px;
}

.dashboard-v2__attention-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.dashboard-v2__attention-card {
  min-height: 82px !important;
  display: grid !important;
  grid-template-columns: 36px minmax(0, 1fr) auto;
  gap: 10px !important;
  align-items: center !important;
  padding: 11px 12px !important;
  border-radius: 9px !important;
  box-shadow: none !important;
  text-align: left !important;
}

.dashboard-v2__attention-card > span:nth-child(2) {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.dashboard-v2__attention-card small {
  font-size: 7px;
  font-weight: 850;
  letter-spacing: .1em;
}

.dashboard-v2__attention-card strong {
  color: #25333a;
  font-size: 11px;
}

.dashboard-v2__attention-card b {
  font-size: 12px;
}

.dashboard-v2__attention-icon {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 50%;
}

.dashboard-v2__attention-card--danger {
  border: 1px solid #efcfcb !important;
  background: #fff8f7 !important;
  color: var(--db-danger) !important;
}

.dashboard-v2__attention-card--danger .dashboard-v2__attention-icon {
  background: #ffe5e2;
}

.dashboard-v2__attention-card--warning {
  border: 1px solid #ead8aa !important;
  background: #fffaf0 !important;
  color: var(--db-warning) !important;
}

.dashboard-v2__attention-card--warning .dashboard-v2__attention-icon {
  background: #fff0c8;
}

.dashboard-v2__attention-card--info {
  border: 1px solid #cedbe5 !important;
  background: #f6faff !important;
  color: var(--db-info) !important;
}

.dashboard-v2__attention-card--info .dashboard-v2__attention-icon {
  background: #e7f1f8;
}

.dashboard-v2__middle-grid,
.dashboard-v2__bottom-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 10px;
  margin-top: 10px;
}

.dashboard-v2__operation-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.dashboard-v2__operation-stat {
  min-width: 0;
  display: grid;
  gap: 4px;
  padding: 8px 12px;
  border-right: 1px solid #e8ecef;
}

.dashboard-v2__operation-stat:last-child {
  border-right: 0;
}

.dashboard-v2__operation-stat svg {
  margin-bottom: 3px;
  color: var(--db-primary);
}

.dashboard-v2__operation-stat span {
  color: #53646d;
  font-size: 9px;
}

.dashboard-v2__operation-stat strong {
  color: #1c2930;
  font-size: 20px;
}

.dashboard-v2__operation-stat small {
  color: var(--db-muted);
  font-size: 7px;
}

.dashboard-v2__integration-note {
  margin-top: 12px;
  padding: 8px 10px;
  border-radius: 7px;
  background: #f7f9fa;
  color: var(--db-muted);
  font-size: 8px;
}

.dashboard-v2__quick-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 7px;
}

.dashboard-v2__quick-grid button {
  min-height: 66px !important;
  display: grid !important;
  grid-template-columns: 30px minmax(0, 1fr) auto;
  gap: 8px !important;
  align-items: center !important;
  padding: 8px !important;
  border: 1px solid #dfe5e8 !important;
  border-radius: 8px !important;
  background: #fff !important;
  color: var(--db-text) !important;
  box-shadow: none !important;
  text-align: left !important;
}

.dashboard-v2__quick-grid button:hover {
  border-color: var(--db-border-strong) !important;
  background: #f8fafb !important;
}

.dashboard-v2__quick-grid button > span {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  background: var(--db-primary-soft);
  color: var(--db-primary);
}

.dashboard-v2__quick-grid button > div {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.dashboard-v2__quick-grid strong {
  overflow: hidden;
  color: #25333a;
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dashboard-v2__quick-grid small {
  overflow: hidden;
  color: var(--db-muted);
  font-size: 7px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dashboard-v2__finance-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.dashboard-v2__finance-grid > div {
  min-width: 0;
  display: grid;
  gap: 6px;
  padding: 12px 15px;
  border-right: 1px solid #e8ecef;
}

.dashboard-v2__finance-grid > div:last-child {
  border-right: 0;
}

.dashboard-v2__finance-grid span {
  color: #5e6e77;
  font-size: 9px;
}

.dashboard-v2__finance-grid strong {
  color: #1d2a31;
  font-size: 17px;
}

.dashboard-v2__finance-grid small {
  color: var(--db-muted);
  font-size: 8px;
}

.dashboard-v2__finance-grid .is-danger strong {
  color: #c13f35;
}

.dashboard-v2__finance-grid .is-warning strong {
  color: #a8750d;
}

.dashboard-v2__empty-state {
  min-height: 128px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 5px;
  padding: 18px;
  border: 1px dashed #d5dde1;
  border-radius: 9px;
  background: #fafbfc;
  text-align: center;
}

.dashboard-v2__empty-icon {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--db-info-soft);
  color: var(--db-info);
}

.dashboard-v2__empty-state strong {
  font-size: 10px;
}

.dashboard-v2__empty-state p {
  max-width: 380px;
  margin: 0;
  color: var(--db-muted);
  font-size: 8px;
  line-height: 1.45;
}

@media (max-width: 1280px) {
  .dashboard-v2 {
    grid-template-columns: 190px minmax(0, 1fr);
  }

  .dashboard-v2__workspace {
    padding: 18px;
  }

  .dashboard-v2__quick-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 1040px) {
  .dashboard-v2 {
    grid-template-columns: 72px minmax(0, 1fr);
  }

  .dashboard-v2__brand {
    justify-content: center;
    padding: 4px !important;
  }

  .dashboard-v2__brand img {
    width: 52px;
  }

  .dashboard-v2__sidebar-title,
  .dashboard-v2__nav-group small,
  .dashboard-v2__nav-group button span,
  .dashboard-v2__profile-copy {
    display: none;
  }

  .dashboard-v2__nav-group button {
    justify-content: center !important;
    padding: 6px !important;
  }

  .dashboard-v2__profile {
    grid-template-columns: 1fr;
    justify-items: center;
  }

  .dashboard-v2__logout {
    display: none !important;
  }

  .dashboard-v2__kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .dashboard-v2__attention-grid {
    grid-template-columns: 1fr;
  }

  .dashboard-v2__middle-grid,
  .dashboard-v2__bottom-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 760px) {
  .dashboard-v2 {
    display: block;
  }

  .dashboard-v2__sidebar {
    position: static;
    width: 100%;
    height: auto;
    min-height: 0;
    flex-direction: row;
    align-items: center;
    overflow: visible;
  }

  .dashboard-v2__brand {
    width: auto;
    margin-right: auto;
  }

  .dashboard-v2__nav {
    flex: initial;
    overflow: visible;
  }

  .dashboard-v2__nav-group:not(:first-child),
  .dashboard-v2__nav-group button:not(.is-active),
  .dashboard-v2__profile {
    display: none;
  }

  .dashboard-v2__workspace {
    padding: 14px;
  }

  .dashboard-v2__header {
    align-items: flex-start;
    flex-direction: column;
  }

  .dashboard-v2__header-actions {
    width: 100%;
  }

  .dashboard-v2__context {
    flex: 1;
    min-width: 0;
  }

  .dashboard-v2__update-line {
    align-items: flex-start;
    flex-direction: column;
    padding: 8px 0;
  }

  .dashboard-v2__kpis {
    grid-template-columns: 1fr;
  }

  .dashboard-v2__operation-grid,
  .dashboard-v2__finance-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 520px) {
  .dashboard-v2__header-actions {
    flex-wrap: wrap;
  }

  .dashboard-v2__context {
    width: 100%;
    flex-basis: 100%;
  }

  .dashboard-v2__primary {
    flex: 1;
    justify-content: center;
  }

  .dashboard-v2__quick-grid,
  .dashboard-v2__operation-grid,
  .dashboard-v2__finance-grid {
    grid-template-columns: 1fr;
  }

  .dashboard-v2__section-head {
    align-items: flex-start;
    flex-direction: column;
  }
}
/* =========================================================
   DASHBOARD — REQUIERE ATENCIÓN
   IMPORTANTE:
   Estas cards son <button>, pero NO son botones de acción.
   NUNCA deben utilizar fondo verde.
   ========================================================= */

.dashboard-v2 .dashboard-v2__attention-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}


/* ---------------------------------------------------------
   BASE — FORZAR CARD NEUTRA
   --------------------------------------------------------- */

.dashboard-v2 button.dashboard-v2__attention-card,
.dashboard-v2 button.dashboard-v2__attention-card:enabled,
.dashboard-v2 button.dashboard-v2__attention-card:active,
.dashboard-v2 button.dashboard-v2__attention-card:focus {
  appearance: none !important;

  min-height: 92px !important;

  display: grid !important;
  grid-template-columns: 42px minmax(0, 1fr) 20px !important;
  align-items: center !important;
  gap: 12px !important;

  width: 100% !important;
  padding: 14px 15px !important;

  /* ELIMINA DEFINITIVAMENTE EL VERDE */
  background: #ffffff !important;
  background-color: #ffffff !important;
  background-image: none !important;

  color: #26363d !important;

  border: 1px solid #dce3e7 !important;
  border-radius: 10px !important;

  box-shadow:
    0 1px 2px rgb(16 24 40 / 3%),
    0 2px 5px rgb(16 24 40 / 3%) !important;

  text-align: left !important;
  cursor: pointer !important;

  outline: none !important;

  transition:
    border-color 150ms ease,
    box-shadow 150ms ease,
    transform 150ms ease,
    background-color 150ms ease !important;
}


/* ---------------------------------------------------------
   HOVER — GRIS, NUNCA VERDE
   --------------------------------------------------------- */

.dashboard-v2 button.dashboard-v2__attention-card:hover:not(:disabled) {
  background: #f7f9fa !important;
  background-color: #f7f9fa !important;
  background-image: none !important;

  color: #26363d !important;

  border-color: #bdc8ce !important;

  box-shadow:
    0 2px 4px rgb(16 24 40 / 5%),
    0 5px 12px rgb(16 24 40 / 6%) !important;

  transform: translateY(-1px);
}


/* ---------------------------------------------------------
   FOCUS — ACCESIBILIDAD SIN VERDE
   --------------------------------------------------------- */

.dashboard-v2 button.dashboard-v2__attention-card:focus-visible {
  background: #ffffff !important;

  outline: 2px solid #8fa2ad !important;
  outline-offset: 2px !important;
}


/* ---------------------------------------------------------
   CONTENIDO
   --------------------------------------------------------- */

.dashboard-v2__attention-card > span:nth-child(2) {
  min-width: 0;

  display: grid;
  gap: 3px;
}

.dashboard-v2__attention-card small {
  font-size: 8px !important;
  font-weight: 800 !important;
  letter-spacing: 0.08em;
}

.dashboard-v2__attention-card strong {
  color: #26363d !important;

  font-size: 11px !important;
  font-weight: 700 !important;

  line-height: 1.3;
}

.dashboard-v2__attention-card b {
  color: #18252c !important;

  font-size: 14px !important;
  font-weight: 800 !important;

  line-height: 1.25;
}


/* Flecha derecha */

.dashboard-v2__attention-card > svg {
  color: #89969d !important;

  width: 17px;
  height: 17px;

  transition: transform 150ms ease;
}

.dashboard-v2__attention-card:hover > svg {
  transform: translateX(2px);
}


/* =========================================================
   ICONO BASE
   ========================================================= */

.dashboard-v2__attention-icon {
  width: 42px !important;
  height: 42px !important;

  display: grid !important;
  place-items: center !important;

  border-radius: 9px !important;
}


/* =========================================================
   CRÍTICO
   Card blanca + indicador rojo
   ========================================================= */

.dashboard-v2 button.dashboard-v2__attention-card--danger {
  background: #ffffff !important;
  background-color: #ffffff !important;

  border: 1px solid #e4d6d4 !important;
  border-left: 4px solid #c64b43 !important;
}

.dashboard-v2 button.dashboard-v2__attention-card--danger:hover {
  background: #fffafa !important;
  background-color: #fffafa !important;

  border-color: #dfc5c2 !important;
  border-left-color: #c64b43 !important;
}

.dashboard-v2__attention-card--danger
  .dashboard-v2__attention-icon {
  background: #fff0ef !important;
  color: #b7433b !important;
}

.dashboard-v2__attention-card--danger small {
  color: #b7433b !important;
}


/* =========================================================
   ATENCIÓN
   Card blanca + indicador ámbar
   ========================================================= */

.dashboard-v2 button.dashboard-v2__attention-card--warning {
  background: #ffffff !important;
  background-color: #ffffff !important;

  border: 1px solid #e5ddca !important;
  border-left: 4px solid #d29a2b !important;
}

.dashboard-v2 button.dashboard-v2__attention-card--warning:hover {
  background: #fffdf8 !important;
  background-color: #fffdf8 !important;

  border-color: #ded0ad !important;
  border-left-color: #d29a2b !important;
}

.dashboard-v2__attention-card--warning
  .dashboard-v2__attention-icon {
  background: #fff6df !important;
  color: #a8700b !important;
}

.dashboard-v2__attention-card--warning small {
  color: #94640d !important;
}


/* =========================================================
   INVENTARIO
   Card blanca + indicador azul/gris
   NO VERDE
   ========================================================= */

.dashboard-v2 button.dashboard-v2__attention-card--info {
  background: #ffffff !important;
  background-color: #ffffff !important;

  border: 1px solid #d5dfe4 !important;
  border-left: 4px solid #607f91 !important;
}

.dashboard-v2 button.dashboard-v2__attention-card--info:hover {
  background: #f9fbfc !important;
  background-color: #f9fbfc !important;

  border-color: #c5d3da !important;
  border-left-color: #607f91 !important;
}

.dashboard-v2__attention-card--info
  .dashboard-v2__attention-icon {
  background: #edf3f6 !important;
  color: #506f80 !important;
}

.dashboard-v2__attention-card--info small {
  color: #506f80 !important;
}


/* =========================================================
   PROTECCIÓN CONTRA ESTILOS GLOBALES
   Ningún estado de estas cards puede ponerse verde.
   ========================================================= */

.dashboard-v2 button.dashboard-v2__attention-card:hover,
.dashboard-v2 button.dashboard-v2__attention-card:active,
.dashboard-v2 button.dashboard-v2__attention-card:focus,
.dashboard-v2 button.dashboard-v2__attention-card:focus-visible {
  background-image: none !important;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1040px) {
  .dashboard-v2 .dashboard-v2__attention-grid {
    grid-template-columns: 1fr;
  }
}
/* =========================================================
   DASHBOARD — LOGO / BRAND
   Fondo negro + logo centrado
   ========================================================= */

.dashboard-v2__brand {
  width: 100% !important;
  height: 72px !important;
  min-height: 72px !important;

  display: flex !important;
  align-items: center !important;
  justify-content: center !important;

  padding: 8px 12px !important;
  margin: 0 0 8px 0 !important;

  /* Fondo negro para destacar el logo */
  background: #050706 !important;
  background-color: #050706 !important;
  background-image: none !important;

  border: 1px solid rgba(255, 255, 255, 0.08) !important;
  border-radius: 10px !important;

  box-shadow: none !important;

  cursor: pointer;
  overflow: hidden;
}

.dashboard-v2__brand img {
  display: block !important;

  width: auto !important;
  height: auto !important;

  max-width: 145px !important;
  max-height: 54px !important;

  object-fit: contain !important;
  object-position: center center !important;

  margin: 0 auto !important;
}


/* Hover muy discreto.
   El logo no debe parecer un botón primario. */

.dashboard-v2__brand:hover:not(:disabled) {
  background: #0b0d0c !important;
  background-color: #0b0d0c !important;

  border-color: rgba(255, 255, 255, 0.13) !important;

  box-shadow: none !important;
}


/* Evita que estilos globales de button
   conviertan el contenedor del logo en verde */

.dashboard-v2 button.dashboard-v2__brand,
.dashboard-v2 button.dashboard-v2__brand:hover,
.dashboard-v2 button.dashboard-v2__brand:focus,
.dashboard-v2 button.dashboard-v2__brand:active {
  background: #050706 !important;
  background-color: #050706 !important;
  background-image: none !important;

  color: #ffffff !important;
}

/* =========================================================
   MÓDULOS DE TRABAJO — HOVER PASTEL
   Sin verde en cards ni hover
   ========================================================= */

.dashboard-v2 .dashboard-v2__quick-grid button {
  background: #ffffff !important;
  background-color: #ffffff !important;
  background-image: none !important;

  border: 1px solid #dfe5e8 !important;
  color: #26363d !important;

  box-shadow: none !important;

  transition:
    background-color 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease,
    transform 160ms ease !important;
}


/* HOVER — azul gris pastel */

.dashboard-v2 .dashboard-v2__quick-grid button:hover:not(:disabled) {
  background: #f1f6f8 !important;
  background-color: #f1f6f8 !important;
  background-image: none !important;

  border-color: #c5d4dc !important;

  color: #26363d !important;

  box-shadow:
    0 3px 8px rgba(34, 55, 66, 0.06) !important;

  transform: translateY(-1px);
}


/* ACTIVE — ligeramente más marcado */

.dashboard-v2 .dashboard-v2__quick-grid button:active:not(:disabled) {
  background: #e9f1f4 !important;
  background-color: #e9f1f4 !important;
  background-image: none !important;

  border-color: #b8cad3 !important;

  transform: translateY(0);
}


/* FOCUS — sin verde */

.dashboard-v2 .dashboard-v2__quick-grid button:focus-visible {
  background: #f1f6f8 !important;

  outline: 2px solid #9eb4bf !important;
  outline-offset: 2px !important;
}


/* =========================================================
   ICONOS
   Normal = gris azulado pastel
   Hover = azul pastel ligeramente más marcado
   ========================================================= */

.dashboard-v2 .dashboard-v2__quick-grid button > span {
  background: #eef3f5 !important;
  background-color: #eef3f5 !important;

  color: #5b7481 !important;

  transition:
    background-color 160ms ease,
    color 160ms ease !important;
}

.dashboard-v2 .dashboard-v2__quick-grid button:hover > span {
  background: #ddeaf0 !important;
  background-color: #ddeaf0 !important;

  color: #486b7c !important;
}


/* Flecha */

.dashboard-v2 .dashboard-v2__quick-grid button > svg {
  color: #98a5ac !important;

  transition:
    color 160ms ease,
    transform 160ms ease;
}

.dashboard-v2 .dashboard-v2__quick-grid button:hover > svg {
  color: #647f8c !important;
  transform: translateX(2px);
}
/* =========================================================
   DASHBOARD — MEJORA DE LEGIBILIDAD
   Estado Operacional + Módulos de Trabajo
   ========================================================= */


/* =========================================================
   1. ESTADO OPERACIONAL
   ========================================================= */

/* Label principal:
   En espera / En proceso / Tickets POS / Caja */

.dashboard-v2 .dashboard-v2__operation-stat > span {
  color: #465860 !important;

  font-size: 12px !important;
  font-weight: 700 !important;

  line-height: 1.3 !important;
}


/* Valor principal */

.dashboard-v2 .dashboard-v2__operation-stat > strong {
  color: #1c2930 !important;

  font-size: 22px !important;
  font-weight: 800 !important;

  line-height: 1.15 !important;
}


/* Texto secundario:
   "Pendiente integración" */

.dashboard-v2 .dashboard-v2__operation-stat > small {
  color: #74838b !important;

  font-size: 9px !important;
  font-weight: 500 !important;

  line-height: 1.35 !important;
}


/* Iconos un poco más visibles */

.dashboard-v2 .dashboard-v2__operation-stat > svg {
  width: 21px !important;
  height: 21px !important;

  margin-bottom: 5px !important;
}


/* =========================================================
   2. MÓDULOS DE TRABAJO
   ========================================================= */

/* Título:
   CarWash / Punto de Venta / Caja / Gastos / Productos... */

.dashboard-v2 .dashboard-v2__quick-grid button strong {
  color: #26363d !important;

  font-size: 11px !important;
  font-weight: 750 !important;

  line-height: 1.3 !important;
}


/* Descripción:
   Operación / Ventas y facturación / Apertura y cierre... */

.dashboard-v2 .dashboard-v2__quick-grid button small {
  color: #6f7d85 !important;

  font-size: 9px !important;
  font-weight: 500 !important;

  line-height: 1.3 !important;
}


/* Un poco más de espacio vertical para evitar
   que el aumento de texto comprima las cards */

.dashboard-v2 .dashboard-v2__quick-grid button {
  min-height: 72px !important;

  padding: 10px !important;

  grid-template-columns:
    34px minmax(0, 1fr) auto !important;

  gap: 9px !important;
}


/* Contenedor del icono */

.dashboard-v2 .dashboard-v2__quick-grid button > span {
  width: 34px !important;
  height: 34px !important;

  border-radius: 8px !important;
}


/* Icono */

.dashboard-v2 .dashboard-v2__quick-grid button > span svg {
  width: 19px !important;
  height: 19px !important;
}


/* =========================================================
   3. TÍTULOS DE LAS SECCIONES
   Estado operacional / Módulos de trabajo
   ========================================================= */

.dashboard-v2 .dashboard-v2__section-head h2 {
  font-size: 16px !important;
  font-weight: 750 !important;

  line-height: 1.25 !important;
}


/* Label superior:
   OPERACIÓN DE HOY / ACCESOS RÁPIDOS */

.dashboard-v2 .dashboard-v2__section-head > div > span {
  font-size: 9px !important;
  font-weight: 850 !important;

  letter-spacing: 0.1em !important;
}

/* ==========================================================
   CARWASH — NUEVA ORDEN — DASHBOARD UI V3
   Este archivo reemplaza el bloque anterior de NewOrderPage.
   Recomendado: importar SOLO en NewOrderPage o agregar al final
   del styles.css. Todo está aislado bajo .carwash-dashboard-ui.
   ========================================================== */

.carwash-dashboard-ui {
  --c-bg: #f4f6f8;
  --c-surface: #ffffff;
  --c-surface-soft: #f8fafc;
  --c-border: #e2e8f0;
  --c-border-strong: #cbd5e1;
  --c-text: #172033;
  --c-muted: #677489;
  --c-soft: #8a96a8;
  --c-blue: #46637d;
  --c-blue-soft: #eef3f7;
  --c-blue-soft-2: #e8eff5;
  --c-green: #1f6a49;
  --c-green-hover: #18583c;
  --c-green-soft: #edf8f2;
  --c-danger: #a64646;
  --c-danger-soft: #fff3f3;
  --c-shadow: 0 8px 22px rgb(15 23 42 / 5%);

  min-height: 100vh;
  background: var(--c-bg);
  color: var(--c-text);
}

/* reset global green button inside this screen */
.carwash-dashboard-ui button {
  min-height: auto;
  border-radius: 0;
  padding: 0;
  background: transparent;
  color: inherit;
  box-shadow: none;
}

.carwash-dashboard-ui button:hover {
  filter: none;
}

/* TOPBAR */
.carwash-dashboard-ui__topbar {
  min-height: 72px;
  position: sticky;
  top: 0;
  z-index: 30;
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr) 140px;
  align-items: center;
  gap: 18px;
  padding: 10px 18px;
  border-bottom: 1px solid var(--c-border);
  background: rgb(255 255 255 / 96%);
  backdrop-filter: blur(12px);
}

.carwash-dashboard-ui__brand {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 12px;
}

.carwash-dashboard-ui__logo {
  font-size: 1rem;
  letter-spacing: .12em;
}

.carwash-dashboard-ui__brand > div {
  min-width: 0;
  display: grid;
  gap: 1px;
}

.carwash-dashboard-ui__brand > div strong {
  font-size: .8rem;
}

.carwash-dashboard-ui__brand > div span {
  overflow: hidden;
  color: var(--c-muted);
  font-size: .7rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.carwash-dashboard-ui__nav {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 4px;
  overflow-x: auto;
}

.carwash-dashboard-ui__nav-item {
  min-height: 38px !important;
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 0 11px !important;
  border: 1px solid transparent !important;
  border-radius: 9px !important;
  background: transparent !important;
  color: #536173 !important;
  font-size: .72rem;
  font-weight: 800;
  white-space: nowrap;
}

.carwash-dashboard-ui__nav-item:hover {
  border-color: #d9e2e9 !important;
  background: #f0f4f7 !important;
  color: #30465a !important;
}

.carwash-dashboard-ui__nav-item--primary {
  border-color: var(--c-green) !important;
  background: var(--c-green) !important;
  color: #fff !important;
}

.carwash-dashboard-ui__nav-item--primary:hover {
  border-color: var(--c-green-hover) !important;
  background: var(--c-green-hover) !important;
  color: #fff !important;
}

.carwash-dashboard-ui__user {
  display: grid;
  justify-items: end;
  gap: 2px;
}

.carwash-dashboard-ui__user span {
  color: var(--c-soft);
  font-size: .66rem;
}

.carwash-dashboard-ui__user strong {
  font-size: .74rem;
}

/* LAYOUT */
.carwash-dashboard-ui__workspace {
  width: 100%;
  max-width: 1720px;
  min-height: calc(100vh - 72px);
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(380px, 430px) minmax(0, 1fr);
  gap: 16px;
  padding: 16px;
}

.carwash-dashboard-ui__order,
.carwash-dashboard-ui__panel {
  border: 1px solid var(--c-border);
  border-radius: 14px;
  background: var(--c-surface);
  box-shadow: var(--c-shadow);
}

.carwash-dashboard-ui__order {
  position: sticky;
  top: 88px;
  max-height: calc(100vh - 104px);
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 18px;
  overflow-y: auto;
}

.carwash-dashboard-ui__catalog {
  min-width: 0;
  display: grid;
  align-content: start;
  gap: 16px;
}

.carwash-dashboard-ui__panel {
  padding: 18px;
}

/* HEADINGS */
.carwash-dashboard-ui__heading,
.carwash-dashboard-ui__panel-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
}

.carwash-dashboard-ui__heading h1,
.carwash-dashboard-ui__panel-heading h2 {
  margin: 4px 0 0;
  color: var(--c-text);
}

.carwash-dashboard-ui__heading h1 {
  font-size: 1.45rem;
}

.carwash-dashboard-ui__panel-heading h2 {
  font-size: 1rem;
}

.carwash-dashboard-ui__heading p {
  margin: 4px 0 0;
  color: var(--c-muted);
  font-size: .73rem;
  line-height: 1.45;
}

.carwash-dashboard-ui__eyebrow {
  color: #6e7e91;
  font-size: .62rem;
  font-weight: 900;
  letter-spacing: .13em;
  text-transform: uppercase;
}

.carwash-dashboard-ui__badge {
  padding: 5px 8px;
  border: 1px solid #d6e0e8;
  border-radius: 999px;
  background: #f1f5f8;
  color: #5d6d7e;
  font-size: .66rem;
  font-weight: 900;
}

.carwash-dashboard-ui__icon-button {
  width: 36px;
  min-height: 36px !important;
  display: grid !important;
  place-items: center;
  border: 1px solid var(--c-border) !important;
  border-radius: 9px !important;
  background: #fff !important;
  color: #526173 !important;
}

.carwash-dashboard-ui__icon-button:hover {
  background: #f0f4f7 !important;
}

/* CONTEXT + FORMS */
.carwash-dashboard-ui__context {
  min-height: 58px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid #d9e3eb;
  border-radius: 11px;
  background: #f7f9fb;
  color: #536b81;
}

.carwash-dashboard-ui__context > div {
  display: grid;
  gap: 2px;
}

.carwash-dashboard-ui__context > div span {
  color: var(--c-muted);
  font-size: .63rem;
  font-weight: 800;
  text-transform: uppercase;
}

.carwash-dashboard-ui__context > div strong {
  overflow: hidden;
  color: var(--c-text);
  font-size: .82rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.carwash-dashboard-ui__context select {
  max-width: 180px;
}

.carwash-dashboard-ui__context-code {
  padding: 5px 8px;
  border: 1px solid #c6d5e0;
  border-radius: 999px;
  background: #edf3f7;
  color: #49637a;
  font-size: .64rem;
  font-weight: 900;
}

.carwash-dashboard-ui__form-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 120px;
  gap: 10px;
}

.carwash-dashboard-ui__form-grid label,
.carwash-dashboard-ui__field {
  display: grid;
  gap: 6px;
}

.carwash-dashboard-ui__form-grid label > span,
.carwash-dashboard-ui__field > span {
  color: #48566a;
  font-size: .72rem;
  font-weight: 800;
}

.carwash-dashboard-ui input,
.carwash-dashboard-ui select {
  min-height: 42px;
  border: 1px solid var(--c-border-strong);
  border-radius: 10px;
  padding: 0 11px;
  background: #fff;
  color: var(--c-text);
