}

.carwash-dashboard-ui__filters {
  display: flex;
  gap: 6px;
}

.carwash-dashboard-ui__filter {
  min-height: 40px !important;
  padding: 0 13px !important;
  border: 1px solid var(--c-border) !important;
  border-radius: 9px !important;
