  }
}

/* =========================================================
   PURCHASE ORDERS — BOTÓN "ABRIR ORDEN"
   Acción secundaria: NO verde.
   "Nueva orden" permanece como acción primaria verde.
   ========================================================= */

.purchase-orders-v2__open-order-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;

  min-height: 36px;
  padding: 0.5rem 0.9rem;

  background: #ffffff;
  color: #31516c;

  border: 1px solid #b8cad8;
  border-radius: 9px;

  font: inherit;
  font-weight: 700;
  line-height: 1;

  cursor: pointer;
  box-shadow: none;

  transition:
    background-color 160ms ease,
    border-color 160ms ease,
    color 160ms ease,
    box-shadow 160ms ease;
}

.purchase-orders-v2__open-order-button:hover {
  background: #f4f8fb;
  border-color: #86a9c2;
  color: #203f59;
}

.purchase-orders-v2__open-order-button:focus-visible {
  outline: 3px solid rgba(78, 133, 173, 0.22);
  outline-offset: 2px;
}

.purchase-orders-v2__open-order-button:active {
  background: #eaf2f7;
}

.purchase-orders-v2__open-order-button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

/* =========================================================
   PURCHASE ORDERS
   ABRIR ORDEN — OVERRIDE FINAL
   Acción secundaria: azul, NO verde
   ========================================================= */

.purchase-orders-v2
  .purchase-orders-v2__open-order-button {
  background: #2563eb !important;
  background-color: #2563eb !important;

  color: #ffffff !important;

  border: 1px solid #2563eb !important;
  border-color: #2563eb !important;

  box-shadow: none !important;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-height: 36px;
  padding: 0.5rem 0.9rem;

  border-radius: 9px;

  font-weight: 700;
  line-height: 1;

  cursor: pointer;
}

/* Hover */

.purchase-orders-v2
  .purchase-orders-v2__open-order-button:hover {
  background: #1d4ed8 !important;
  background-color: #1d4ed8 !important;

  color: #ffffff !important;

  border-color: #1d4ed8 !important;

  box-shadow:
    0 3px 8px rgba(37, 99, 235, 0.18) !important;
}

/* Click */

.purchase-orders-v2
  .purchase-orders-v2__open-order-button:active {
  background: #1e40af !important;
  background-color: #1e40af !important;

  border-color: #1e40af !important;

  color: #ffffff !important;
}

/* Teclado / accesibilidad */

.purchase-orders-v2
  .purchase-orders-v2__open-order-button:focus-visible {
  outline: 3px solid rgba(37, 99, 235, 0.25) !important;
