/* =========================================================
   CXC PRINT VISIBILITY FIX
   Corrige reglas legacy globales de impresión
   ========================================================= */

@media print {

  /*
   * styles.css contiene reglas legacy que ocultan
   * el árbol durante impresión.
   *
   * Para CxC hacemos visible explícitamente:
   * 1. la página
   * 2. el contenedor del reporte
   * 3. todos sus descendientes
   */

  body:has(.cxc-receivables-page) > * {
    visibility: visible !important;
  }

  body:has(.cxc-receivables-page)
    .cxc-receivables-page {
    visibility: visible !important;
    display: block !important;

    position: static !important;
    width: 100% !important;
    max-width: none !important;

    margin: 0 !important;
    padding: 0 !important;

    background: #ffffff !important;
  }

  body:has(.cxc-receivables-page)
    .cxc-receivables-page
    > *:not(.cxc-print-only) {
    display: none !important;
  }

  body:has(.cxc-receivables-page)
    .cxc-print-only,
  body:has(.cxc-receivables-page)
    .cxc-print-only * {
    visibility: visible !important;
  }

  body:has(.cxc-receivables-page)
    .cxc-print-only {
    display: block !important;

    position: static !important;

    width: 100% !important;
    max-width: none !important;

    margin: 0 !important;
    padding: 0 !important;

    opacity: 1 !important;

    color: #111827 !important;
    background: #ffffff !important;
  }
}
