/* =========================================================
   POS REPORT — CHECKBOX PUNTOS INCLUIDOS
   ========================================================= */

.pos-sales-report-page
.pos-point-profitability__point-option {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  width: auto;
  min-height: 36px;
  padding: 7px 10px;
  border: 1px solid #d4e0e5;
  border-radius: 9px;
  background: #fff;
  color: #1d2933;
  font-size: .8rem;
  font-weight: 700;
  cursor: pointer;
}

.pos-sales-report-page
.pos-point-profitability__point-option:hover {
  border-color: #b7cbd3;
  background: #f8fbfb;
}

.pos-sales-report-page
.pos-point-profitability__point-option input[type="checkbox"] {
  appearance: none;
  width: 16px;
  height: 16px;
  margin: 0;
  border: 1.5px solid #9fb2bc;
  border-radius: 4px;
  background: #fff;
  display: grid;
  place-content: center;
  cursor: pointer;
}

.pos-sales-report-page
.pos-point-profitability__point-option input[type="checkbox"]::before {
  content: "";
  width: 8px;
  height: 8px;
  transform: scale(0);
  transition: transform .12s ease-in-out;
  clip-path: polygon(
    14% 44%,
    0 59%,
    40% 100%,
    100% 16%,
    84% 0,
    38% 62%
  );
  background: #fff;
}

.pos-sales-report-page
.pos-point-profitability__point-option input[type="checkbox"]:checked {
  border-color: #1d6748;
  background: #1d6748;
}

.pos-sales-report-page
.pos-point-profitability__point-option input[type="checkbox"]:checked::before {
  transform: scale(1);
}

.pos-sales-report-page
.pos-point-profitability__point-option input[type="checkbox"]:focus-visible {
  outline: 2px solid rgba(29, 103, 72, .22);
  outline-offset: 2px;
}

.pos-sales-report-page
.pos-point-profitability__point-option input[type="checkbox"]:disabled {
  opacity: .55;
  cursor: not-allowed;
}

.pos-sales-report-page
.pos-point-profitability__point-option span {
  white-space: nowrap;
}

