  margin-top: 9px;
  padding: 10px 12px;
  border-radius: 9px;
  background: #fff;
}

.touch-pos-v1__notice--error {
  border: 1px solid #e6b4b4;
  background: #fff1f1;
  color: #a33d3d;
}

.touch-pos-v1__notice--success {
  border: 1px solid #bcd9c8;
  background: #eef8f2;
  color: #236244;
}

.touch-pos-v1__workspace {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(390px, .72fr);
  gap: 12px;
  margin-top: 12px;
}

.touch-pos-v1__catalog,
.touch-pos-v1__order,
.touch-pos-v1__hold {
  border: 1px solid #d7e2dd;
  border-radius: 14px;
  background: #fff;
  box-shadow: 0 3px 12px rgb(15 23 42 / 4%);
}

.touch-pos-v1__catalog {
  min-width: 0;
  padding: 12px;
}

.touch-pos-v1__catalog-top {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 220px;
  gap: 8px;
}

.touch-pos-v1__search,
.touch-pos-v1__scanner {
  min-height: 48px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
  border: 1px solid #cedbd5;
  border-radius: 11px;
  background: #f9fbfa;
  color: #698078;
}

.touch-pos-v1__search input,
.touch-pos-v1__scanner input {
  width: 100%;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  font: inherit;
}

.touch-pos-v1__categories {
  display: flex;
  gap: 8px;
  margin: 11px 0;
  overflow-x: auto;
  padding-bottom: 3px;
}

.touch-pos-v1__category {
  min-width: 92px;
  min-height: 64px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 4px;
  flex: 0 0 auto;
  padding: 7px 12px;
  border: 1px solid #d7e1dd;
  border-radius: 11px;
  background: #fff;
  color: #53645b;
  font-size: .69rem;
  font-weight: 800;
}

.touch-pos-v1__category--active {
  border-color: #6c9c86;
  background: #eaf5ef;
  color: #126b4a;
}

.touch-pos-v1__catalog-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  padding: 4px 2px 9px;
}

.touch-pos-v1__catalog-heading h2,
.touch-pos-v1__order-header h2,
.touch-pos-v1__section-heading h2 {
  margin: 2px 0 0;
  font-size: 1rem;
}

.touch-pos-v1__catalog-heading small {
  color: #718078;
}

.touch-pos-v1__products {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(145px, 1fr));
  gap: 9px;
}

.touch-pos-v1__product {
  min-width: 0;
  min-height: 190px;
  display: flex;
  flex-direction: column;
  padding: 8px;
  overflow: hidden;
  border: 1px solid #dce5e1;
  border-radius: 12px;
  background: #fff;
  text-align: left;
  box-shadow: 0 2px 6px rgb(15 23 42 / 4%);
}

.touch-pos-v1__product:active:not(:disabled) {
  transform: scale(.98);
}

.touch-pos-v1__product-visual {
  position: relative;
  height: 102px;
  display: grid;
  place-items: center;
  overflow: hidden;
  border-radius: 9px;
  background: #f6f9f7;
  color: #4c7863;
}

.touch-pos-v1__product-visual img {
  max-width: 94px;
  max-height: 94px;
  object-fit: contain;
}

.touch-pos-v1__stock {
  position: absolute;
  top: 5px;
  right: 5px;
  padding: 3px 6px;
  border-radius: 999px;
  font-size: .56rem;
  font-weight: 900;
}

.touch-pos-v1__stock--low {
  background: #fff3d6;
  color: #956915;
}

.touch-pos-v1__stock--out {
  background: #fee7e7;
  color: #a53e3e;
}

.touch-pos-v1__product--disabled {
  opacity: .55;
}

.touch-pos-v1__product-info {
  display: grid;
  gap: 3px;
  padding: 7px 2px 1px;
}

.touch-pos-v1__product-info > strong {
  overflow: hidden;
  font-size: .78rem;
  line-height: 1.15;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.touch-pos-v1__product-info > small {
  color: #718078;
  font-size: .63rem;
}

.touch-pos-v1__product-info > div {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 6px;
  margin-top: 4px;
}

.touch-pos-v1__product-info > div span {
  color: #73837a;
  font-size: .6rem;
}

.touch-pos-v1__product-info b {
  color: #126b4a;
  font-size: .82rem;
}

.touch-pos-v1__pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-top: 11px;
}

.touch-pos-v1__pagination button {
  width: 44px;
  height: 44px;
  border: 1px solid #cfdbd6;
  border-radius: 9px;
  background: #fff;
}

.touch-pos-v1__order {
  position: sticky;
  top: 10px;
  align-self: start;
  max-height: calc(100vh - 22px);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.touch-pos-v1__order-header {
  min-height: 61px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  border-bottom: 1px solid #e2e9e5;
}

.touch-pos-v1__order-count {
  min-width: 52px;
  height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border-radius: 10px;
  background: #eaf5ef;
  color: #126b4a;
}

.touch-pos-v1__sale-modes {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  padding: 9px 11px;
  background: #f8faf9;
}

.touch-pos-v1__sale-mode {
  min-height: 42px;
  padding: 5px;
  border: 1px solid #d4ded9;
  border-radius: 8px;
  background: #fff;
  color: #5b6c63;
  font-size: .65rem;
  font-weight: 800;
}

.touch-pos-v1__sale-mode--active {
  border-color: #569078;
  background: #e8f4ee;
  color: #126b4a;
}

.touch-pos-v1__customer,
.touch-pos-v1__payment {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  padding: 9px 11px;
}

.touch-pos-v1__customer label,
.touch-pos-v1__payment label,
.touch-pos-v1__reference {
  display: grid;
  gap: 4px;
  color: #68786f;
  font-size: .62rem;
  font-weight: 800;
}

.touch-pos-v1__customer select,
.touch-pos-v1__payment select,
.touch-pos-v1__payment input,
.touch-pos-v1__reference input {
  width: 100%;
  min-height: 40px;
  padding: 6px 8px;
  border: 1px solid #cedad4;
  border-radius: 8px;
  background: #fff;
}

.touch-pos-v1__reference {
  margin: 0 11px 9px;
}

.touch-pos-v1__cart {
  flex: 1 1 auto;
  min-height: 145px;
  overflow-y: auto;
  border-top: 1px solid #e5ebe8;
  border-bottom: 1px solid #e5ebe8;
}

.touch-pos-v1__cart-empty {
  min-height: 170px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 5px;
  color: #849087;
}

.touch-pos-v1__cart-empty span {
  font-size: .65rem;
}

.touch-pos-v1__cart-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto 35px;
  align-items: center;
  gap: 7px;
  padding: 8px 10px;
  border-bottom: 1px solid #edf1ef;
}

.touch-pos-v1__cart-item-main {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.touch-pos-v1__cart-item-main strong {
  overflow: hidden;
  font-size: .72rem;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.touch-pos-v1__cart-item-main small {
  color: #718078;
  font-size: .61rem;
}

.touch-pos-v1__price-change {
  width: fit-content;
  padding: 1px 0;
  border: 0;
  background: transparent;
  color: #126b4a;
  font-size: .57rem;
  font-weight: 800;
}

.touch-pos-v1__quantity {
  display: grid;
  grid-template-columns: 34px 44px 34px;
  gap: 3px;
}

.touch-pos-v1__quantity button,
.touch-pos-v1__quantity input {
  height: 34px;
  min-height: 34px;
  border: 1px solid #ced9d4;
  border-radius: 7px;
  background: #fff;
  text-align: center;
}

.touch-pos-v1__quantity input {
  width: 44px;
}

.touch-pos-v1__line-total {
  font-size: .69rem;
  white-space: nowrap;
}

.touch-pos-v1__remove {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 1px solid #ebcccc;
  border-radius: 7px;
  background: #fff5f5;
  color: #ad4e4e;
}

.touch-pos-v1__clear {
  margin: 6px 10px 0 auto;
  border: 0;
  background: transparent;
  color: #a45353;
  font-size: .61rem;
  font-weight: 800;
}

.touch-pos-v1__summary {
  display: grid;
  gap: 5px;
  margin: 9px 11px 5px;
  padding: 9px 10px;
  border: 1px solid #d0e2d8;
  border-radius: 10px;
  background: #eef7f2;
}

.touch-pos-v1__summary > div {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-size: .68rem;
}

.touch-pos-v1__grand-total {
  margin-top: 3px;
  padding-top: 7px;
  border-top: 1px dashed #b8cec1;
}

.touch-pos-v1__grand-total span {
  font-size: .78rem;
  font-weight: 900;
}

.touch-pos-v1__grand-total strong {
  color: #126b4a;
  font-size: 1.22rem;
}

.touch-pos-v1__actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  padding: 5px 11px 11px;
}

.touch-pos-v1__actions button {
  min-height: 48px;
  border: 1px solid #cbd8d2;
  border-radius: 9px;
  background: #fff;
  font-weight: 850;
}

.touch-pos-v1__actions .touch-pos-v1__pay {
  border-color: #126b4a;
  background: #126b4a;
  color: #fff;
}

.touch-pos-v1__actions .touch-pos-v1__secondary {
  background: #f5f8f6;
  color: #44574d;
}

.touch-pos-v1__hold {
  margin-top: 12px;
  padding: 14px;
}

.touch-pos-v1__section-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.touch-pos-v1__account-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 10px;
  margin-top: 12px;
}

.touch-pos-v1__account-card {
  padding: 11px;
  border: 1px solid #d8e2dd;
  border-radius: 11px;
  background: #fff;
}

.touch-pos-v1__account-head,
.touch-pos-v1__account-total {
  display: flex;
  justify-content: space-between;
  gap: 10px;
}

.touch-pos-v1__account-head h3 {
  margin: 2px 0;
}

.touch-pos-v1__status,
.touch-pos-v1__account-mode {
  width: fit-content;
  padding: 4px 7px;
  border-radius: 999px;
  background: #eaf5ef;
  color: #126b4a;
  font-size: .6rem;
  font-weight: 900;
}

.touch-pos-v1__account-lines {
  display: grid;
  gap: 3px;
  margin: 10px 0;
  color: #66766e;
  font-size: .65rem;
}

.touch-pos-v1__account-total {
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px solid #edf1ef;
}

.touch-pos-v1__primary-action {
  width: 100%;
  min-height: 44px;
  margin-top: 10px;
  border: 0;
  border-radius: 8px;
  background: #126b4a;
  color: #fff;
  font-weight: 850;
}

.touch-pos-v1__empty {
  padding: 50px 20px;
  color: #7a8981;
  text-align: center;
}

@media (max-width: 1199px) {
  .touch-pos-v1__workspace {
    grid-template-columns: 1fr;
  }

  .touch-pos-v1__order {
    position: static;
    max-height: none;
  }
}

@media (max-width: 720px) {
  .touch-pos-v1 {
    padding: 7px;
  }

  .touch-pos-v1__header {
    align-items: flex-start;
    flex-direction: column;
  }

  .touch-pos-v1__nav {
    width: 100%;
    overflow-x: auto;
  }

  .touch-pos-v1__catalog-top {
    grid-template-columns: 1fr;
  }

  .touch-pos-v1__products {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .touch-pos-v1__customer,
  .touch-pos-v1__payment,
  .touch-pos-v1__actions {
    grid-template-columns: 1fr;
  }
}


/* =========================================================
   CACTUS TOUCH POS — COLOR / SURFACE FIX V1
   Corrige contaminación de estilos globales de button.
   Scope exclusivo: .touch-pos-v1
   ========================================================= */

/* BASE */
.touch-pos-v1 {
  background: #f3f6f5 !important;
  color: #1f2d27 !important;
}

/* ---------------------------------------------------------
   HEADER
   --------------------------------------------------------- */

.touch-pos-v1 .touch-pos-v1__header {
  background: #ffffff !important;
  border-color: #d8e2de !important;
}

.touch-pos-v1 .touch-pos-v1__brand-icon {
  background: #e9f4ef !important;
  color: #176c50 !important;
}

/* Navegación: neutra salvo activa */
.touch-pos-v1 button.touch-pos-v1__nav-button {
  background: #ffffff !important;
  background-image: none !important;
  color: #34483f !important;

  border: 1px solid #cfdad5 !important;

  box-shadow: none !important;
}

.touch-pos-v1 button.touch-pos-v1__nav-button:hover:not(:disabled) {
  background: #f4f7f6 !important;
  border-color: #aebfb7 !important;
  color: #263a31 !important;
}

.touch-pos-v1 button.touch-pos-v1__nav-button--active {
  background: #176c50 !important;
  background-image: none !important;

  border-color: #176c50 !important;

  color: #ffffff !important;
}

.touch-pos-v1 button.touch-pos-v1__nav-button--secondary {
  background: #f6f8f7 !important;
  color: #31443b !important;
}

/* ---------------------------------------------------------
   CATÁLOGO
   --------------------------------------------------------- */

.touch-pos-v1 .touch-pos-v1__catalog {
  background: #ffffff !important;
  border-color: #d9e3df !important;
}

/* Búsqueda / scanner */
.touch-pos-v1 .touch-pos-v1__search,
.touch-pos-v1 .touch-pos-v1__scanner {
  background: #ffffff !important;
  border-color: #ccd9d3 !important;
}

.touch-pos-v1 .touch-pos-v1__search input,
.touch-pos-v1 .touch-pos-v1__scanner input {
  background: transparent !important;
  color: #25372f !important;
}

/* ---------------------------------------------------------
   CATEGORÍAS
   --------------------------------------------------------- */

.touch-pos-v1 button.touch-pos-v1__category {
  background: #ffffff !important;
  background-image: none !important;

  color: #455850 !important;

  border: 1px solid #d4dfda !important;

  box-shadow: none !important;
}

.touch-pos-v1 button.touch-pos-v1__category svg {
  color: #587068 !important;
}

.touch-pos-v1 button.touch-pos-v1__category:hover:not(:disabled) {
  background: #f3f7f5 !important;

  border-color: #aabdb4 !important;

  color: #243b31 !important;
}

.touch-pos-v1 button.touch-pos-v1__category--active {
  background: #e8f3ee !important;
  background-image: none !important;

  border-color: #78a28f !important;

  color: #176c50 !important;

  box-shadow:
    inset 0 0 0 1px rgb(23 108 80 / 8%) !important;
}

.touch-pos-v1 button.touch-pos-v1__category--active svg {
  color: #176c50 !important;
}

/* ---------------------------------------------------------
   TARJETAS PRODUCTOS
   --------------------------------------------------------- */

.touch-pos-v1 button.touch-pos-v1__product {
  background: #ffffff !important;
  background-image: none !important;

  color: #1e2d26 !important;

  border: 1px solid #d9e3df !important;

  box-shadow:
    0 2px 7px rgb(15 23 42 / 5%) !important;

  transform: none !important;
}

.touch-pos-v1 button.touch-pos-v1__product:hover:not(:disabled) {
  background: #ffffff !important;

  border-color: #adc1b7 !important;

  box-shadow:
    0 5px 14px rgb(15 23 42 / 10%) !important;

  transform: translateY(-1px) !important;
}

.touch-pos-v1 button.touch-pos-v1__product:active:not(:disabled) {
  background: #f8fbf9 !important;

  transform: scale(.985) !important;
}

/* Área imagen */
.touch-pos-v1 .touch-pos-v1__product-visual {
  background: #f6f8f7 !important;
  color: #59806e !important;
}

/* Nombre */
.touch-pos-v1 .touch-pos-v1__product-info > strong {
  color: #1d2b25 !important;
}

/* Categoría */
