}

/* ---------------------------------------------------------
   ORDEN
   --------------------------------------------------------- */

.touch-pos-v1 .touch-pos-v1__order {
  background: #ffffff !important;
  border-color: #d7e2dd !important;
}

.touch-pos-v1 .touch-pos-v1__order-header {
  background: #ffffff !important;
}

/* Contador */
.touch-pos-v1 .touch-pos-v1__order-count {
  background: #eaf4ef !important;
  color: #176c50 !important;
}

/* ---------------------------------------------------------
