.touch-pos-v1 button.touch-pos-v1__sale-mode {
  background: #ffffff !important;
  background-image: none !important;

  color: #53655d !important;

  border: 1px solid #d3ded9 !important;

  box-shadow: none !important;
}

.touch-pos-v1 button.touch-pos-v1__sale-mode:hover:not(:disabled) {
  background: #f4f7f6 !important;

  border-color: #aebfb7 !important;
}

.touch-pos-v1 button.touch-pos-v1__sale-mode--active {
  background: #e7f3ed !important;
  background-image: none !important;

  border-color: #6c9e87 !important;

  color: #176c50 !important;
}

/* ---------------------------------------------------------
   FORMULARIOS
