.touch-pos-v1 select,
.touch-pos-v1 input {
  background: #ffffff !important;

  color: #24352d !important;

  border-color: #ccd8d2 !important;
}

.touch-pos-v1 select:focus,
.touch-pos-v1 input:focus {
  border-color: #6b9b85 !important;

  outline: 2px solid rgb(23 108 80 / 10%) !important;
