  background: #ffffff !important;
  background-image: none !important;

  color: #34483f !important;

  border: 1px solid #cbd8d2 !important;

  box-shadow: none !important;
}

/* Acción primaria de cobro */
.touch-pos-v1
.touch-pos-v1__actions
button.touch-pos-v1__pay {
  background: #176c50 !important;
