.bulk-assignment-modal__body {
  padding: 14px 22px 12px;
  overflow: visible;
}

.bulk-assignment-filters {
  display: grid;
  grid-template-columns:
    minmax(250px, 1.15fr)
    minmax(260px, 1fr)
    minmax(210px, 0.8fr);
