  align-items: end;
}

.bulk-assignment-filters label {
  min-width: 0;
}

.bulk-assignment-filters input,
.bulk-assignment-filters select {
  min-height: 40px;
}

.bulk-assignment-selection-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 52px;
  margin: 14px 0 10px;
  padding: 8px 12px;
  border: 1px solid var(--border-color, #d9e2df);
  border-radius: 12px;
  background:
    linear-gradient(
      90deg,
      rgba(20, 145, 92, 0.07),
      rgba(20, 145, 92, 0.02)
    );
}

.bulk-assignment-select-all {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  margin: 0;
  cursor: pointer;
}

.bulk-assignment-select-all__text {
  display: flex;
  align-items: baseline;
  gap: 12px;
  min-width: 0;
}

.bulk-assignment-select-all__text strong {
  white-space: nowrap;
}

.bulk-assignment-select-all__text small {
  color: var(--text-muted, #667085);
  white-space: nowrap;
}

.bulk-assignment-selected-count {
  display: inline-flex;
