 * Pantallas medianas:
 * reorganiza filtros sin afectar el flujo.
 */
@media (max-width: 980px) {
  .bulk-assignment-modal {
    width: calc(100vw - 24px);
  }

  .bulk-assignment-filters {
    grid-template-columns: 1fr 1fr;
  }

  .bulk-assignment-filters label:last-child {
    grid-column: 1 / -1;
  }

  .bulk-assignment-select-all__text small {
    display: none;
  }
}

@media (max-width: 680px) {
  .bulk-assignment-filters {
    grid-template-columns: 1fr;
  }

  .bulk-assignment-filters label:last-child {
    grid-column: auto;
  }

  .bulk-assignment-selection-bar {
    align-items: flex-start;
    flex-direction: column;
  }

  .bulk-assignment-table-wrap {
    overflow-x: auto;
  }

  .bulk-assignment-note {
    align-items: flex-start;
    flex-direction: column;
    gap: 3px;
  }
}

/* =========================================================
   Bulk Assignment - Checkbox normalization
   ========================================================= */

/*
 * Ocultar completamente el checkbox nativo.
 * El label sigue siendo clickeable y accesible.
 */
.bulk-assignment-modal .checkbox-input {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  margin: 0 !important;
  padding: 0 !important;
  opacity: 0 !important;
  overflow: hidden !important;
  pointer-events: none;
}

/*
 * Check visual estándar.
 */
.bulk-assignment-modal .checkbox-checkmark {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  width: 18px;
  height: 18px;
  min-width: 18px;
  min-height: 18px;

  padding: 0;
  margin: 0;

  border: 1.5px solid #b9c6c1;
  border-radius: 5px;

  background: #ffffff;
  color: transparent;

  transition:
    background-color 120ms ease,
    border-color 120ms ease,
    box-shadow 120ms ease;
}

/*
 * Icono interno.
 */
.bulk-assignment-modal .checkbox-checkmark svg {
  width: 12px;
  height: 12px;
  opacity: 0;
  stroke: currentColor;
}

/*
 * Estado seleccionado.
 */
.bulk-assignment-modal
  .checkbox-input:checked
  + .checkbox-checkmark {
  border-color: #16875d;
  background: #16875d;
  color: #ffffff;
}

.bulk-assignment-modal
  .checkbox-input:checked
  + .checkbox-checkmark
  svg {
  opacity: 1;
}

/*
 * Focus accesible.
 */
.bulk-assignment-modal
  .checkbox-input:focus-visible
  + .checkbox-checkmark {
  box-shadow:
    0 0 0 3px rgba(22, 135, 93, 0.16);
}

/*
 * Disabled.
 */
.bulk-assignment-modal
  .checkbox-input:disabled
  + .checkbox-checkmark {
  cursor: not-allowed;
  opacity: 0.45;
}

/* =========================================================
   Seleccionar todos
   ========================================================= */

.bulk-assignment-modal
  .bulk-assignment-select-all
  .checkbox-checkmark {
  width: 20px;
  height: 20px;
  min-width: 20px;
  min-height: 20px;
  border-radius: 6px;
}

.bulk-assignment-modal
  .bulk-assignment-select-all
  .checkbox-checkmark
  svg {
  width: 13px;
  height: 13px;
}

/*
 * Evita que el selector ocupe espacio exagerado.
 */
.bulk-assignment-select-all {
  min-height: 32px;
}

/* =========================================================
   Checkbox de filas
   ========================================================= */

.bulk-assignment-modal
  .bulk-assignment-row-check
  .checkbox-checkmark {
  width: 17px;
  height: 17px;
  min-width: 17px;
  min-height: 17px;
  border-radius: 5px;
}

.bulk-assignment-modal
  .bulk-assignment-row-check
  .checkbox-checkmark
  svg {
  width: 11px;
  height: 11px;
}

.bulk-assignment-check-cell {
  width: 42px;
  min-width: 42px;
  padding-left: 12px !important;
  padding-right: 8px !important;
}

.bulk-assignment-row-check {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;

  width: 28px;
  height: 28px;

  margin: 0;
  padding: 0;
}

/*
 * Toda la fila seleccionada conserva un feedback sutil,
 * sin competir visualmente con el checkbox.
 */
.bulk-assignment-row.row-selected {
  background: rgba(22, 135, 93, 0.045);
}


