.pos-payment-modal__cash > span {
  font-size: 13px;
  font-weight: 700;
  color: #334155;
}

.pos-payment-modal__cash > div {
  display: flex;
  align-items: center;

  min-height: 58px;

  border: 2px solid #cbd5e1;
  border-radius: 12px;
  background: #ffffff;

  transition:
    border-color 0.16s ease,
    box-shadow 0.16s ease;
}

.pos-payment-modal__cash > div:focus-within {
  border-color: #2563eb;
  box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.1);
}

.pos-payment-modal__cash > div > span {
  flex: 0 0 auto;

  padding-left: 16px;

  font-size: 17px;
  font-weight: 800;
  color: #64748b;
}

.pos-payment-modal__cash input {
  flex: 1 1 auto;

  width: 100%;
  min-width: 0;
  height: 54px;

  padding: 0 16px 0 8px !important;

  border: 0 !important;
  outline: 0 !important;
  background: transparent !important;
  box-shadow: none !important;

  font-size: 27px;
  font-weight: 800;
  text-align: right;
  color: #172033;
}

.pos-payment-modal__change {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;

  margin-top: 14px;
  padding: 16px;

  border: 1px solid #dbe4ec;
  border-radius: 12px;
  background: #f8fafc;
}

.pos-payment-modal__change span {
  font-size: 14px;
  font-weight: 700;
  color: #475569;
}

.pos-payment-modal__change strong {
  font-size: 24px;
  line-height: 1;
  color: #475569;
}

.pos-payment-modal__change--ready {
  border-color: #a7d7bb;
  background: #f0fdf4;
}

.pos-payment-modal__change--ready strong {
  color: #15803d;
}

.pos-payment-modal__pending {
  margin: 8px 2px 0;

  font-size: 12px;
  font-weight: 700;
  text-align: right;
  color: #b45309;
}

.pos-payment-modal__non-cash {
  padding: 16px;

  border: 1px solid #dbe4ec;
  border-radius: 12px;
  background: #f8fafc;

  font-size: 14px;
  line-height: 1.5;
  color: #475569;
}

.pos-payment-modal__actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;

  margin-top: 24px;
  padding-top: 18px;

  border-top: 1px solid #e5e7eb;
}

.pos-payment-modal__actions button {
  min-height: 44px;
  padding: 0 18px;

  border-radius: 10px;

  font-size: 14px;
  font-weight: 800;
}

.pos-payment-modal__confirm {
  border: 1px solid #15803d;
  background: #16a34a;
  color: #ffffff;
  cursor: pointer;
}

.pos-payment-modal__confirm:hover:not(:disabled) {
  background: #15803d;
}

.pos-payment-modal__confirm:disabled {
  border-color: #cbd5e1;
  background: #e2e8f0;
  color: #94a3b8;
  cursor: not-allowed;
}

@media (max-width: 560px) {
  .pos-payment-modal__backdrop {
    padding: 12px;
  }

  .pos-payment-modal {
    padding: 18px;
    border-radius: 14px;
  }

  .pos-payment-modal__summary {
    grid-template-columns: 1fr;
  }

  .pos-payment-modal__actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }
}
