/* =========================================================
   POS · VISTA PREVIA DEL TICKET
   ========================================================= */

.pos-ticket-preview__backdrop {
  position: fixed;
  inset: 0;
  z-index: 1300;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(15, 23, 42, 0.58);
  backdrop-filter: blur(3px);
}

.pos-ticket-preview {
  display: flex;
  flex-direction: column;
  width: min(100%, 520px);
  max-height: min(92vh, 860px);
  overflow: hidden;
  border-radius: 14px;
  background: #fff;
  box-shadow:
    0 24px 70px rgba(15, 23, 42, 0.25),
    0 4px 18px rgba(15, 23, 42, 0.12);
}

.pos-ticket-preview__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 18px;
  border-bottom: 1px solid #e2e8f0;
}

.pos-ticket-preview__header > div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.pos-ticket-preview__header span {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: #64748b;
}

.pos-ticket-preview__header h2 {
  margin: 0;
  font-size: 19px;
}

.pos-ticket-preview__body {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  padding: 18px;
  background: #eef2f6;
}

.pos-ticket-preview__body iframe {
  display: block;
  width: 100%;
  min-height: 590px;
  border: 0;
  border-radius: 8px;
  background: #fff;
  box-shadow: 0 2px 12px rgba(15, 23, 42, 0.1);
}

.pos-ticket-preview__actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 14px 18px;
