/* =========================================================
   ISSUED SALES DOCUMENTS — MODERN UI
   Scoped: no modifica otros reportes POS
   ========================================================= */

.issued-sales-documents-page {
  --issued-border: #dce7e3;
  --issued-muted: #687a72;
  --issued-soft: #f6f9f8;
  --issued-accent: #176c54;
  --issued-accent-soft: #edf7f3;
}

/* Header más limpio */
.issued-sales-documents-page .pos-sales-report-header {
  min-height: 76px;
  padding: 14px 18px !important;
  border: 1px solid var(--issued-border);
  border-radius: 14px !important;
  background: #fff !important;
  box-shadow: 0 5px 18px rgb(15 23 42 / 4%);
  color: #20342b !important;
}

.issued-sales-documents-page .maintenance-header__content {
  align-items: center;
}

.issued-sales-documents-page .maintenance-header__icon {
  width: 40px;
  height: 40px;
  padding: 8px;
  border: 1px solid #cfe2dc;
  border-radius: 11px;
  background: var(--issued-accent-soft);
  color: #176b70;
}

.issued-sales-documents-page .pos-sales-report-header h1 {
  margin: 0;
  color: #20342b !important;
  font-size: 1.25rem;
  letter-spacing: -.025em;
}

.issued-sales-documents-page .pos-sales-report-header p {
  margin-top: 3px;
  color: var(--issued-muted) !important;
  font-size: .67rem;
}

/* Filtros */
.issued-sales-documents__filters {
  padding: 13px 14px !important;
  border: 1px solid var(--issued-border);
  box-shadow: 0 4px 14px rgb(15 23 42 / 3%);
}

.issued-sales-documents__filters .pos-sales-report-section-title {
  margin-bottom: 11px;
}

.issued-sales-documents__filters .pos-sales-report-filter-grid {
  grid-template-columns:
    minmax(150px, .75fr)
    minmax(150px, .75fr)
    minmax(210px, 1fr)
    minmax(230px, 1.1fr)
    auto;
  gap: 10px;
}

.issued-sales-documents__filters .pos-sales-report-filter-grid > button {
  min-width: 110px;
  height: 34px !important;
}

.issued-sales-documents__filters input,
.issued-sales-documents__filters select {
  border-color: #d4e1dc;
  background: #fff;
  transition:
    border-color 140ms ease,
    box-shadow 140ms ease;
}

.issued-sales-documents__filters input:focus,
.issued-sales-documents__filters select:focus {
  border-color: #6aa697;
  box-shadow: 0 0 0 3px rgb(23 108 84 / 9%);
}

/* KPIs */
.issued-sales-documents__kpis {
  display: flex !important;
  gap: 10px !important;
  margin: 0 0 12px !important;
}

.issued-sales-documents__kpis article {
  width: 220px;
  min-height: 76px !important;
  padding: 10px 12px !important;
  border-color: var(--issued-border) !important;
  box-shadow: 0 4px 14px rgb(15 23 42 / 3%) !important;
}

.issued-sales-documents__kpis article > strong {
  margin-top: 4px !important;
  font-size: 1rem !important;
}

.issued-sales-documents__kpis article small {
  margin-top: 3px !important;
}

.issued-sales-documents__kpis .pos-sales-report-kpi-total {
  border-top: 3px solid var(--issued-accent) !important;
}

/* Listado */
.issued-sales-documents__list {
  padding: 13px 14px !important;
  border: 1px solid var(--issued-border);
  border-radius: 12px !important;
  box-shadow: 0 5px 18px rgb(15 23 42 / 3%);
}

.issued-sales-documents__list .pos-sales-report-section-title {
  margin-bottom: 12px;
}

.issued-sales-documents__table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
}

.issued-sales-documents__table thead th {
  position: sticky;
  top: 0;
  z-index: 1;
  height: 34px;
  border-bottom: 1px solid #d8e3df;
  background: #f3f7f5;
  color: #526c61;
  font-size: .57rem !important;
  font-weight: 800;
  letter-spacing: .025em;
  text-transform: uppercase;
}

.issued-sales-documents__table tbody td {
  height: 46px;
  border-bottom: 1px solid #edf2f0;
  color: #34483f;
  vertical-align: middle;
}

.issued-sales-documents__table tbody tr {
  transition: background 120ms ease;
}

.issued-sales-documents__table tbody tr:hover {
  background: #f8fbfa;
}

.issued-sales-documents__table tbody tr:last-child td {
  border-bottom: 0;
}

.issued-sales-documents__reference {
  color: #27473a;
  font-weight: 800;
  letter-spacing: -.01em;
}

.issued-sales-documents__type,
.issued-sales-documents__payment {
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  padding: 3px 7px;
  border-radius: 999px;
  white-space: nowrap;
  font-size: .56rem;
  font-weight: 750;
}

.issued-sales-documents__type {
  border: 1px solid #d6e6e0;
  background: #f2f8f5;
  color: #356452;
}

.issued-sales-documents__type.is-account {
  border-color: #dce1ea;
  background: #f5f6f9;
  color: #566174;
}

.issued-sales-documents__payment {
  background: #f4f6f5;
  color: #53645c;
}

.issued-sales-documents__view-button {
  min-width: 62px;
}

/* Desktop */
@media (min-width: 1101px) {
  .issued-sales-documents__list
    .pos-sales-transactions__table-wrap {
    max-height: min(590px, calc(100vh - 390px));
    overflow: auto;
  }
}

/* Tablet */
@media (max-width: 1100px) {
  .issued-sales-documents__filters .pos-sales-report-filter-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .issued-sales-documents__filters .pos-sales-report-filter-grid > button {
    width: 100%;
  }
}

/* Mobile */
@media (max-width: 680px) {
  .issued-sales-documents-page {
    padding-inline: 10px;
  }

  .issued-sales-documents-page .pos-sales-report-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .issued-sales-documents-page .pos-sales-report-header-actions {
    width: 100%;
  }

  .issued-sales-documents__filters .pos-sales-report-filter-grid {
    grid-template-columns: 1fr;
  }

  .issued-sales-documents__kpis {
    display: grid !important;
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }

  .issued-sales-documents__kpis article {
    width: auto;
  }
}

/* =========================================================
   ISSUED SALES DOCUMENTS — DETAIL MODAL
   ========================================================= */

.issued-sales-documents__modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgb(15 23 42 / 48%);
  backdrop-filter: blur(3px);
}

.issued-sales-documents__modal {
  width: min(920px, 100%);
  max-height: min(88vh, 900px);
  overflow: hidden;
  border: 1px solid #dbe6e2;
  border-radius: 16px;
  background: #fff;
  box-shadow: 0 24px 70px rgb(15 23 42 / 22%);
}

.issued-sales-documents__modal-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  padding: 20px 22px 17px;
  border-bottom: 1px solid #e8efec;
  background:
    linear-gradient(
      180deg,
      #ffffff 0%,
      #fbfdfc 100%
    );
