.issued-sales-documents__modal-date {
  color: #78877f;
  font-size: .62rem;
  font-weight: 650;
}

.issued-sales-documents__modal-heading h2 {
  margin: 0;
  color: #1f3028;
  font-size: 1.35rem;
  line-height: 1.15;
  letter-spacing: -.035em;
}

.issued-sales-documents__modal-heading p {
  margin: 5px 0 0;
  color: #6f7f77;
  font-size: .68rem;
}

.issued-sales-documents__modal-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.issued-sales-documents__modal-close {
