/* Summary */
.issued-sales-documents__modal-summary {
  display: grid;
  grid-template-columns:
    minmax(180px, 1.2fr)
    minmax(300px, 2fr)
    minmax(170px, .9fr);
  gap: 12px;
}

.issued-sales-documents__modal-customer,
.issued-sales-documents__modal-metrics,
.issued-sales-documents__modal-total {
  min-width: 0;
  border: 1px solid #e1e9e6;
  border-radius: 12px;
  background: #fafcfb;
}

.issued-sales-documents__modal-customer {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 13px 14px;
}

.issued-sales-documents__modal-customer span,
.issued-sales-documents__modal-metrics span,
.issued-sales-documents__modal-total span {
  color: #718078;
  font-size: .58rem;
  font-weight: 750;
  text-transform: uppercase;
  letter-spacing: .025em;
}

.issued-sales-documents__modal-customer strong {
  display: block;
  margin-top: 5px;
  overflow-wrap: anywhere;
  color: #263a30;
  font-size: .83rem;
}

.issued-sales-documents__modal-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  overflow: hidden;
}

.issued-sales-documents__modal-metrics > div {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 0;
  padding: 13px 14px;
}

.issued-sales-documents__modal-metrics > div + div {
  border-left: 1px solid #e6edeb;
}

.issued-sales-documents__modal-metrics strong {
  display: block;
  margin-top: 5px;
  color: #30443a;
  font-size: .78rem;
  white-space: nowrap;
}

.issued-sales-documents__modal-total {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 13px 15px;
  border-color: #cfe1da;
  background: #f1f8f5;
}

.issued-sales-documents__modal-total strong {
  display: block;
  margin-top: 4px;
  color: #14684e;
  font-size: 1.18rem;
  line-height: 1.1;
  letter-spacing: -.025em;
  white-space: nowrap;
}

/* Sections */
.issued-sales-documents__modal-section {
  display: grid;
  gap: 9px;
}

.issued-sales-documents__modal-section-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 12px;
}

.issued-sales-documents__modal-section-heading h3 {
  margin: 0;
  color: #26382f;
  font-size: .87rem;
}

.issued-sales-documents__modal-section-heading p {
  margin: 2px 0 0;
  color: #7b8982;
  font-size: .57rem;
}

/* Detail tables */
.issued-sales-documents__modal-table-wrap {
  overflow-x: auto;
  border: 1px solid #dfe8e4;
  border-radius: 10px;
}

.issued-sales-documents__modal-table {
  width: 100%;
  border-collapse: collapse;
  background: #fff;
}

.issued-sales-documents__modal-table th {
  padding: 8px 10px;
  border-bottom: 1px solid #dde6e2;
  background: #f4f7f6;
  color: #526b60;
  font-size: .56rem;
  font-weight: 800;
  letter-spacing: .025em;
  text-align: left;
  text-transform: uppercase;
  white-space: nowrap;
}

.issued-sales-documents__modal-table td {
  padding: 9px 10px;
  border-bottom: 1px solid #edf2f0;
  color: #34483f;
  font-size: .64rem;
  vertical-align: middle;
}

.issued-sales-documents__modal-table tbody tr:last-child td {
  border-bottom: 0;
}

.issued-sales-documents__modal-table tbody tr:hover {
  background: #fafcfb;
}

.issued-sales-documents__modal-table td:not(:first-child),
.issued-sales-documents__modal-table th:not(:first-child) {
  text-align: right;
}

.issued-sales-documents__modal-table td:nth-child(2),
.issued-sales-documents__modal-table th:nth-child(2) {
  text-align: center;
}

.issued-sales-documents__modal-empty {
  padding: 20px !important;
  color: #77867e !important;
  text-align: center !important;
}

/* Responsive */
@media (max-width: 760px) {
  .issued-sales-documents__modal-backdrop {
    align-items: end;
    padding: 0;
  }

  .issued-sales-documents__modal {
    width: 100%;
    max-height: 94vh;
